INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('07ae6b0d-22b4-5c81-ad60-b5c4a1a4e474', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 46, 46, 'ባቢሎንን ከያዝዋት ሰዎች ድምፅ የተነሣ ምድር ተናወጠች፤ ጩኸትም በአሕዛብ መካከል ተሰማ።”'),
  ('eea5d393-e20f-54c8-ad7c-e4a05bf80a67', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ በባቢሎን ላይና በከለዳውያን ምድር በሚኖሩት ላይ የሚያቃጥልና የሚያጠፋ ነፋስን አስነሣለሁ።'),
  ('483aee55-d818-51f5-a9f0-0f60cbe92d61', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 2, 2, 'በባቢሎንም ላይ ተሳዳቢ ሰዎችን እሰድዳለሁ፤ እነርሱም ይሰድቧታል፤ ምድርዋንም ባዶ ያደርጋሉ፤ በመከራም ቀን በዙሪያዋ ይከብቡአታል።'),
  ('ef980e33-cd91-580e-a2c4-d5bba46f5b52', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 3, 3, 'በቀስት ወርዋሪው ላይ፥ በጥሩርም በሚነሣው ላይ ቀስተኛው ቀስቱን ይገትር፤ ለጐበዛዝቷ አትዘኑ፤ ሠራዊቷንም ሁሉ አጥፉ።'),
  ('c0286b34-3482-5d0d-ac9d-ad529366d8c5', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 4, 4, 'የተገደሉት በከለዳውያን ምድር ይወድቃሉ፤ የቈሰሉትም በውጭ ይወድቃሉ።'),
  ('458fbb83-b85f-5659-a9fe-745703d3bd4f', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 5, 5, '“ምድራቸው በእስራኤል ቅዱስ ላይ በተሠራው በደል የተሞላች ብትሆንም፥ እስራኤል መበለት አልሆነችም፤ ይሁዳም ከአምላኩ ከሠራዊት ጌታ ከእግዚአብሔር ዘንድ አልራቀም።'),
  ('b5b0f6a5-74ca-588e-aa36-7fe0367c11f0', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 6, 6, 'ከባቢሎን መካከል ሽሹ፤ እያንዳንዳችሁም ነፍሳችሁን አድኑ፤ በበደልዋ አትጥፉ፤ የእግዚአብሔር በቀል ጊዜ ነውና፥ እርሱም ብድራቷን ይከፍላታልና።'),
  ('57adb58a-e59e-5da5-ac42-c1932911463c', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 7, 7, 'ባቢሎን በእግዚአብሔር እጅ ውስጥ ምድርን ሁሉ ያሰከረች የወርቅ ጽዋ ነበረች፤ አሕዛብም ከጠጅዋ ጠጥተዋል፤ ስለዚህ አሕዛብ ተንገዳግደዋል።'),
  ('8ad7a612-5545-523d-aef0-43fa445e9adf', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 8, 8, 'ባቢሎን በድንገት ወድቃ ተሰባብራለች፤ አልቅሱላት፤ ትፈወስም እንደ ሆነ ለቍስልዋ መድኀኒት ውሰዱላት።'),
  ('731e4a8b-c054-5f95-aaf3-9955059111bc', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 9, 9, 'ባቢሎንን ፈወስናት፥ እርስዋ ግን አልተፈወሰችም፤ ፍርድዋ እስከ ሰማይ ደርሶአልና፥ እስከ ከዋክብትም ድረስ ከፍ ከፍ ብሎአልና፥ እንተዋት፤ ሁላችንም ወደ ሀገራችን እንሂድ።'),
  ('639aa333-d428-5529-a5ab-c1799c1dcccf', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 10, 10, 'እግዚአብሔር ፍርዳችንን አውጥቶአል፤ ኑ በጽዮን የአምላካችን የእግዚአብሔርን ሥራ እንናገር።'),
  ('e905a1ef-c1ae-5cbc-ae27-f4e0481ff17b', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 11, 11, '“ፍላጾችን አዘጋጁ፤ ጕራንጕሬዎችንም ሙሉ፤ እግዚአብሔር ያጠፋት ዘንድ ቍጣው በባቢሎን ላይ ነውና የሜዶንን ንጉሥ መንፈስ አስነሥቶአል፤ የእግዚአብሔር በቀል የመቅደሱ በቀል ነውና።'),
  ('e9b67c65-ff5e-566f-a81e-2c4f09ae4328', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 12, 12, 'በባቢሎን ቅጥሮች ላይ ዓላማውን አንሡ፤ ከጕራንጕሬአችሁ ጋር ጽኑ፤ ተመልካቾችን አቁሙ፤ መሣሪያችሁን አዘጋጁ። እግዚአብሔር በባቢሎን በሚኖሩት ላይ የተናገረውን ያደርግ ዘንድ ጀምሮአልና።'),
  ('66e4e347-5555-5ff0-a1ed-0085e3a23648', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 13, 13, 'አንቺ በብዙ ውኃ አጠገብ የተቀመጥሽ፥ በመዝገብም የበለጠግሽ ሆይ! እንደ ስስትሽ መጠን ፍጻሜሽ ደርሶአል።'),
  ('8e2fff8f-a9e7-5c3e-adba-4cb28a21d077', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 14, 14, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ሲል በራሱ ምሎአል፦ በእውነት ሰዎችን እንደ አንበጣ እሞላብሻለሁ፤ እነርሱም እየሮጡ ይወርዱብሻል።”'),
  ('5a997be7-d3c2-5773-a43c-009fdbc2f199', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 15, 15, 'ምድርን በኀይሉ የፈጠረ፥ ዓለሙን በጥበቡ የመሠረተ፥ ሰማያትንም በማስተዋሉ የዘረጋ እርሱ ነው።'),
  ('47fb4f32-ebc3-51ed-afc4-5f85b2bcd45f', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 16, 16, 'ድምፁን ባሰማ ጊዜ ውኆች በሰማይ ይታወካሉ፤ ከምድርም ዳር ደመናትን ያወጣል፤ ለዝናብም ጊዜ መብረቅን ያደርጋል፤ ነፋስንም ከቤተ መዛግብቱ ያወጣል።'),
  ('9f21ee2f-46d0-506e-ae4c-be0756894a23', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 17, 17, 'ሰው ሁሉ ዕውቀትን አጥቶአል፥ አንጥረኛም ሁሉ ከቀረጸው ምስል የተነሣ አፍሮአል፤ ሐሰተኞች ጣዖታትን ሠርተዋልና፥ እስትንፋስም የላቸውምና።'),
  ('106b3374-4159-51f9-a089-7e77676725bd', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 18, 18, 'ሥራቸው ከንቱ ነው፤ እግዚአብሔርም በጐበኛቸው ጊዜ ይጠፋሉ።'),
  ('be9a9e5d-27c7-566c-a11d-e3a05eea7013', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 19, 19, 'የያዕቆብ ዕድል ፋንታ እንደ እነዚህ አይደለም፤ እርሱ የሁሉ ፈጣሪ ነውና። እስራኤልም የርስቱ ነገድ ነው። ስሙም የሠራዊት ጌታ እግዚአብሔር ነው።'),
  ('ac8b700d-7e3a-568f-a4cc-c28cd1232d7d', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 20, 20, '“አንቺ የጦር መሣሪያን በተንሽብኝ፤ እኔም ሕዝቡን እበትንብሻለሁ፤ ከአንቺም ነገሥታትን አስወግዳለሁ።'),
  ('a3f69be6-0cf2-56b2-a18d-dffe1c13d55e', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 21, 21, 'በአንቺ ፈረሱንና ፈረሰኛውን እበትናለሁ፤ በአንቺም ሰረገላውንና በላዩ የሚቀመጠውን እበትናለሁ።'),
  ('eec74b7d-c2a8-56de-ae8f-13d665259041', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 22, 22, 'በአንቺም ወንድና ሴትን እበትናለሁ፤ በአንቺም ሽማግሌውንና ብላቴናውን እበትናለሁ፤ በአንቺም ጐልማሳውንና ቆንጆዪቱን እበትናለሁ፤'),
  ('5cc71080-f9b7-5260-ad61-47302def5e1a', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 23, 23, 'በአንቺም እረኛውንና መንጋውን እበትናለሁ፤ በአንቺም አራሹንና ጥማዱን እበትናለሁ፤ በአንቺም አለቆችንና መሳፍንትን እበትናለሁ።'),
  ('a670f941-32a6-5ecb-a862-0eddcf136869', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 24, 24, 'በጽዮን በዐይናችሁ ፊት ስለ ሠሩት ክፋታቸው ሁሉ በባቢሎንና በከለዳውያን ምድር የሚኖሩትን ሁሉ እበቀላለሁ፥ ይላል እግዚአብሔር።'),
  ('f157bdae-3c3d-5e8f-aa39-3f57e214ae19', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 25, 25, '“አንተ ምድርን ሁሉ የምታጠፋ አጥፊ ተራራ ሆይ! እነሆ፥ እኔ በአንተ ላይ ነኝ፥ ይላል እግዚአብሔር፤ እጄንም እዘረጋብሃለሁ፤ ከድንጋዮቹም ላይ አንከባልልሃለሁ፤ የተቃጠለም ተራራ አደርግሃለሁ።'),
  ('54be010c-e59b-5c76-a0f3-8ac410870092', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 26, 26, 'ከአንተም ለማዕዘን የሚሆን ድንጋይንና ለመሠረት የሚሆን ድንጋይን አይወስዱም፤ ለዘለዓለምም አጠፋሃለሁ፥ ይላል እግዚአብሔር።'),
  ('17b59068-5fd0-5d42-ad12-05e39afe33c5', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 27, 27, '“በምድር ላይ ዓላማን አንሡ፤ በአሕዛብም መካከል መለከትን ንፉ፤ አሕዛብንም ለዩባት፤ የአራራትንና የሚኒን የአስከናዝንም መንግሥታት እዘዙባት፤ ጦረኞችንም በላይዋ አቁሙ፤ ብዛታቸው እንደ አንበጣ የሆኑ ፈረሶችን በላይዋ አውጡ።'),
  ('03adb12a-a8c9-5bf1-aecf-d08ba1220ac2', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 28, 28, 'አሕዛብንም፥ የሜዶንንም ነገሥታት፥ አለቆችንም፥ መሳፍንትንም ሁሉ፥ የግዛታቸውንም ምድር ሁሉ ለዩባት።'),
  ('b7ad39b8-ee64-55d0-a8df-72ad3541e706', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 29, 29, 'ማንም እንዳይቀመጥባት የባቢሎንን ምድር ባድማ ያደርጋት ዘንድ የእግዚአብሔር ዐሳብ በባቢሎን ላይ ጸንቶአልና ምድር ተናወጠች፤ ታመመችም።'),
  ('be58eb0b-7932-53bb-a3b0-5d00775df184', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 30, 30, 'የባቢሎን ተዋጊዎች መዋጋትን ትተዋል፤ በአምባዎቻቸውም ውስጥ ተቀምጠዋል፤ ኀይላቸውም ጠፍቶአል፤ እንደ ሴቶችም ሆነዋል፤ ማደሪያዎችዋም ነድደዋል፤ መወርወሪያዎችዋም ተሰብረዋል።'),
  ('f1c4abaf-c5b6-5b95-a386-cb8f718f0334', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 31, 31, 'ለባቢሎን ንጉሥ ይነግር ዘንድ ሯጩ ሯጩን ለመገናኘት፤ መልእክተኛውም መልእክተኛውን ለመገናኘት ይሮጣል፤ ከተማዋ ከዳር እስከ ዳር ተይዛለችና፤'),
  ('eeeb4c9b-5e97-5b23-adfa-49b7872fec1f', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 32, 32, 'መሻገሪያዎችዋም ተይዘዋልና፥ ቅጥርዋም በእሳት ተቃጥሎአልና፥ ሰልፈኞችም ተማርከዋልና።”'),
  ('a937f31d-6e05-5813-abf0-110b177688c0', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 33, 33, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፥ “የባቢሎን ንጉሥ ቤት እንደ ተረገጠ አውድማ ናት፤ ጥቂት ቈይታ የመከር ጊዜ ይደርስባታል።'),
  ('771bee08-b8ca-5a28-a89d-c7b0cdf72481', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 34, 34, 'የባቢሎን ንጉሥ ናቡከደነፆር በላኝ፤ ከፋፈለኝም፤ እንደ ባዶ ዕቃም አደረገኝ፤ እንደ ዘንዶም ዋጠኝ፤ ከሚጣፍጠውም ሥጋዬ ሆዱን ሞላ።'),
  ('f1e7af9a-5e34-56ab-af2f-1372d335bae2', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 35, 35, 'በጽዮን የምትኖር በእኔ ላይ የተደረገ ግፍና ሥቃይ በባቢሎን ላይ ይሁን ትላለች፤ ኢየሩሳሌምም ደሜ በከለዳውያን ምድር በሚኖሩት ላይ ይሁን ትላለች።”'),
  ('ad90f2a4-2625-5a41-add0-14387515e6b2', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 36, 36, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፥ “እነሆ የሚገፋሽን እፈርድበታለሁ፤ በቀልሽንም እበቀልልሻለሁ፤ ባሕርዋንም ድርቅ አደርገዋለሁ፤ ምንጭዋንም አደርቃለሁ።'),
  ('3e412c56-13ad-5e33-a845-2fb89856d6d1', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 37, 37, 'ባቢሎንም ባድማና የቀበሮ ማደሪያ፥ ማፍዋጫም ትሆናለች፤ የሚቀመጥባትም ሰው አይገኝም።'),
  ('b931772d-3d96-5b57-ae71-14253be9190b', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 38, 38, 'በአንድነትም እንደ አንበሶች ያገሣሉ፤ እንደ አንበሳም ደቦሎች ያጕረመርማሉ።'),
  ('894345c9-3ca3-5504-abb6-a2f3a36d9ccf', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 39, 39, 'በሞቃቸው ጊዜ እንዲዝሉ፥ የዘለዓለምም እንቅልፍ እንዲተኙ መጠጥን አጠጣቸዋለሁ፤ አሰክራቸዋለሁም፤ ከዚያም በኋላ አይነቁም፥ ይላል እግዚአብሔር።'),
  ('67f8b7c4-2b36-5ad7-a4f0-621239b0c8b2', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 40, 40, 'እንደ ጠቦቶችና እንደ አውራ በጎች፥ እንደ አውራ ፍየሎችም ወደ መታረድ አወርዳቸዋለሁ።'),
  ('63e85488-c7c5-5a9a-afcc-54d8bccbcfed', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 41, 41, '“የምድርም ሁሉ ክብር እንዴት ተያዘች! እንዴትስ ተወሰደች! ባቢሎን በአሕዛብ መካከል እንዴት ለጥፋት ሆነች!'),
  ('18041bc0-9dcc-5e96-a924-9bf52d439dbf', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 42, 42, 'ባሕር በባቢሎን ላይ ወጣ፤ በሞገዱም ብዛት ተከደነች።'),
  ('7d35e90a-4b7a-53c2-a120-d981b69113b8', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 43, 43, 'ከተሞችዋ ባድማና ደረቅ ምድር፥ ሰውም የማይቀመጥበት፥ የሰውም ልጅ የማያልፍበት ምድር ሆኑ።'),
  ('9de7bf1c-d5d9-5e42-a0c3-aa1c8d7196a4', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 44, 44, 'በባቢሎንም ላይ እበቀላለሁ፤ የዋጠችውንም ከአፍዋ አስተፋታለሁ፤ አሕዛብም ከዚያ ወዲያ ወደ እርስዋ አይሰበሰቡም፤ የባቢሎንም ቅጥሮች ይወድቃሉ።'),
  ('9507551f-efc7-5299-a827-581307d8748b', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 45, 45, '“ሕዝቤ ሆይ! ከመካከልዋ ውጡ፤ እያንዳንዳችሁም ከእግዚአብሔር ጽኑ ቍጣ ራሳችሁን አድኑ።'),
  ('12b0f7b5-7b60-501c-ae76-4aeb26589f3e', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 46, 46, 'በምድርም ከሚሰማ ወሬ የተነሣ አትፍሩ፤ ልባችሁም የዛለ አይሁን፤ በአንድ ዓመት ወሬ ይመጣል፤ ከዚያም በኋላ በሌላው ዓመት ወሬ ይመጣል፤ በምድርም ላይ ግፍ ይነግሣል፤ አለቃም በአለቃ ላይ ይነሣል።'),
  ('0cb7abe4-e670-5c05-ae9c-acf6832e369f', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 47, 47, 'ስለዚህ እነሆ የተቀረጹትን የባቢሎንን ምስሎች የምበቀልበት ዘመን ይመጣል፤ ምድርዋም ሁሉ ትደርቃለች፤ ተዋግተውም የሞቱት ሁሉ በመካከልዋ ይወድቃሉ።'),
  ('38f5cac6-037f-56c4-a9fd-d2fef231ddf2', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 48, 48, 'አጥፊዎች ከሰሜን ይመጡባታልና ሰማይና ምድር፥ በእነርሱም ያለው ሁሉ ስለ ባቢሎን ደስ ይላቸዋል፥ ይላል እግዚአብሔር።'),
  ('d1f2eefe-d6ba-5698-ade6-5ceabf1064a5', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 49, 49, 'ባቢሎንም በእስራኤል ስለ ተገደሉት ትወድቃለች፤ ስለ ባቢሎንም በምድር ሁሉ የተገደሉት ይወድቃሉ።'),
  ('ea8d636c-16b1-5927-a090-018b3c88811d', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 50, 50, '“ከሰይፍ ያመለጣችሁ ሆይ! ሂዱ፤ አትቁሙ፤ በሩቅ ያላችሁም እግዚአብሔርን አስቡ፤ ኢየሩሳሌምንም በልባችሁ አስቡ።'),
  ('6575dd70-a845-506b-a2ee-a2bfca3d6a82', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 51, 51, 'ስድባችንን ስለ ሰማን አፍረናል፤ ባዕዳን ሰዎችም ወደ ቤተ መቅደሳችን ወደ እግዚአብሔር ቤት ገብተዋልና ውርደት ፊታችንን ከድኖታል።'),
  ('9207a344-cb0c-5d98-ae5d-f0d007010552', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 52, 52, 'ስለዚህ እነሆ የተቀረጹትን ምስሎችዋን የምበቀልበት ዘመን ይመጣል፥ ይላል እግዚአብሔር፤ በምድርዋም ሁሉ የተገደሉት ይወድቃሉ።'),
  ('7b787314-8397-5512-aa6c-f994c77e02a6', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 53, 53, 'ባቢሎንም ወደ ሰማይ ብትወጣ፥ ቅፅሮችዋንም በኀይልዋ ብታጸና፥ ከእኔ ዘንድ አጥፊዎች ይመጡባታል፥ ይላል እግዚአብሔር።'),
  ('a4f93549-7387-576b-a887-375bad4b56d1', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 54, 54, '“ከባቢሎን የጩኸት ድምፅ፥ ከከለዳውያንም ምድር የታላቅ ጥፋት ድምፅ ተሰምቶአል።'),
  ('bf4f3c40-c76c-5bb2-a2d1-c3cd3470cb16', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 55, 55, 'እግዚአብሔር ባቢሎንን አጥፍቶአታልና፥ ከእርስዋም ሞገዱ እንደ ብዙ ውኃዎች የሚተመውን ታላቁን ድምፅ ዝም አሰኝቶአልና፤ የድምፃቸው ጩኸት ተሰምቶአል።'),
  ('0d825fa0-712b-5bbd-aecf-a90883ede389', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 56, 56, 'ጥፋት በባቢሎን ላይ መጥቶባታልና፥ ተዋጊዎችዋ ተያዙ፤ ቀስታቸውም ተሰባበረ፤ እግዚአብሔር ተበቅሎአቸዋልና፥ እግዚአብሔርም ፍዳን ከፍሎአቸዋልና።'),
  ('234c628d-4773-5a84-aeef-403876926b71', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 57, 57, 'መሳፍንቶችዋንና ጥበበኞችዋንም፥ አለቆችዋንና ሹሞችዋን፥ ኀያላኖችዋንም አሰክራለሁ፤ ለዘለዓለምም አንቀላፍተው አይነቁም ይላል ስሙ ሁሉን የሚገዛ እግዚአብሔር የተባለው ንጉሥ።'),
  ('b72659c7-913b-57b8-aae0-c8b9d13d5aee', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '021fe0b4-3da7-506d-a66f-16a8be49cf51', 58, 58, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ሰፊው የባቢሎን ቅጥር ፈጽሞ ይፈርሳል፤ ረጃጅሞች በሮችዋም በእሳት ይቃጠላሉ፤ ሕዝቡ ለከንቱ ይደክማሉ፤ አሕዛብም በመጀመሪያ በእሳት ያልቃሉ።”'),
  ('c95b616b-03c6-5bf0-a096-26586649a102', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 1, 59, 'የይሁዳ ንጉሥ ሴዴቅያስ በነገሠ በአራተኛው ዓመት ከእርሱ ዘንድ ወደ ባቢሎን በሄደ ጊዜ ለማሴው ልጅ ለኔርዩ ልጅ ለሠራያ ነቢዩ ኤርምያስ ያዘዘው ቃል ይህ ነው።'),
  ('c556737d-004e-5386-acf3-79c6ed100df1', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 2, 60, 'ሠራያም የቤቱ አዛዥ ነበረ፤ በባቢሎንም ላይ የሚመጣውን ክፉ ነገር ሁሉ፥ ስለ ባቢሎን የተጻፈውን ይህን ቃል ሁሉ ኤርምያስ በአንድ መጽሐፍ ላይ ጻፈው።'),
  ('c31e26d7-be1c-59fa-a43f-5305a436f101', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 3, 61, 'ኤርምያስም ሠራያን እንዲህ አለው፥ “ወደ ባቢሎን በገባህ ጊዜ እይ፤ ይህንም ቃል ሁሉ አንብብና፦'),
  ('fe1e2ccb-56f8-59cd-a066-35b14a4e8ca3', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 4, 62, 'አቤቱ! ከሰው ጀምሮ እስከ እንስሳ ድረስ ማንም እንዳይቀመጥባት፥ ለዘለዓለምም ባድማ እንድትሆን ታጠፋት ዘንድ በዚች ስፍራ ላይ ተናግረሃል በል።'),
  ('391e521a-ac9e-5acf-a4f5-062bf654e024', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 5, 63, 'ይህንም መጽሐፍ ማንበብ ከፈጸምህ በኋላ፥ ድንጋይን እሰርበት፤ በኤፍራጥስም ወንዝ ውስጥ ጣለው።'),
  ('522852c4-6e9d-5816-a438-4316c30930f8', 'c3514273-fd46-5a85-a377-6e6e65b5c74f', '37b83815-481e-5e49-ad1c-7b59c646d4e9', 6, 64, 'አንተም፦ እኔ ከማመጣባት ክፉ ነገር የተነሣ እንዲሁ ባቢሎን ትሰጥማለች፤ አትነሣምም በል።”'),
  ('307fa2d3-d764-5a88-a6c5-37006d282f0b', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 1, 1, 'ሴዴቅያስ መንገሥ በጀመረ ጊዜ የሃያ አንድ ዓመት ጐልማሳ ነበረ፤ በኢየሩሳሌምም ዐሥራ አንድ ዓመት ነገሠ፤ እናቱም አሚጣል የተባለች የልብና ሰው የኤርምያስ ልጅ ነበረች።'),
  ('41b84305-fb7a-5f86-a57a-d56678da460b', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 2, 2, 'ኢዮአቄምም እንዳደረገ ሁሉ በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('5ea0726f-05d5-5034-affc-9c779c72baf9', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 3, 3, 'ከፊቱም አውጥቶ እስኪጥላቸው ድረስ የእግዚአብሔር ቍጣ በኢየሩሳሌምና በይሁዳ ላይ ሆኖአልና፤ ሴዴቅያስም በባቢሎን ንጉሥ ላይ ዐመፀ።'),
  ('67bcd141-060e-5c1b-abf3-b1443fc44bb5', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 4, 4, 'ሴዴቅያስም በነገሠ በዘጠነኛው ዓመት በዐሥረኛው ወር ከወሩም በዐሥረኛው ቀን የባቢሎን ንጉሥ ናቡከደነፆርና ሠራዊቱ ሁሉ በኢየሩሳሌም ላይ መጥተው ከበቡአት፤ በዙሪያዋም አራት ክንድ ግንብ ሠራ።'),
  ('ba92a460-373d-5b5d-a29a-026fc09a132b', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 5, 5, 'ከተማዪቱም እስከ ንጉሡ እስከ ሴዴቅያስ እስከ ዐሥራ አንደኛው ዓመተ መንግሥት ድረስ ተከብባ ነበር።'),
  ('d4749999-92a9-5bf1-ad76-3bc9ccba6ecb', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 6, 6, 'በአራተኛውም ወር በዘጠነኛው ቀን በከተማዪቱ ራብ ጸንቶ ነበር፤ ለሀገሩም ሰዎች እንጀራ ታጣ።'),
  ('735c43fe-3324-57f8-acc7-cc646a324572', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 7, 7, 'ከተማዪቱም ተሰበረች፤ ሰልፈኞችም ሁሉ ሸሹ፤ በሁለቱም ቅጥር መካከል ባለው በር ወደ ንጉሥ አትክልት በሚወስደው መንገድ በሌሊት ከከተማዪቱ ወጡ። ከለዳውያንም በከተማዪቱ ዙሪያ ነበሩ፤ በዓረባም መንገድ ሄዱ።'),
  ('6365ce95-19ba-5961-aab2-e183128da989', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 8, 8, 'የከለዳውያንም ሠራዊት ንጉሡን ተከታተሉት፤ በኢያሪኮም ሜዳ ሴዴቅያስን ያዙ፤ ሠራዊቱም ሁሉ ከእርሱ ዘንድ ተበትነው ነበር።'),
  ('ce4cafa7-a613-523b-ae92-6cb98a091664', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 9, 9, 'ንጉሡንም ይዘው የባቢሎን ንጉሥ ወዳለባት በኤማት ምድር ወዳለችው ወደ ዴብላታ አመጡት፤ እርሱም ፍርድን በእርሱ ላይ ተናገረ።'),
  ('d8e93b01-835c-5d02-a2ee-d978136a2a06', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 10, 10, 'የባቢሎንም ንጉሥ የሴዴቅያስን ልጆች በፊቱ ገደላቸው፤ የይሁዳንም አለቆች ሁሉ ደግሞ በዴብላታ ገደላቸው።'),
  ('c25f2b50-faeb-5021-a278-e6f5a141944a', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 11, 11, 'የሴዴቅያስንም ዐይኖች አወጣ፤ የባቢሎንም ንጉሥ በሰንሰለት አሰረው፤ ወደ ባቢሎንም ወሰደው፤ እስኪሞትም ድረስ በግዞት ቤት አኖረው።'),
  ('f3d2ae1f-1f26-561d-acbe-ead817506a4f', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 12, 12, 'በባቢሎን ንጉሥ በናቡከደነፆር በዐሥራ ዘጠነኛው ዓመተ መንግሥት በአምስተኛው ወር ከወሩም በዐሥረኛው ቀን በባቢሎን ንጉሥ ፊት የሚቆመው የአዛዦች አለቃ ናቡዛርዳን ወደ ኢየሩሳሌም መጣ።'),
  ('fba912ee-5903-5947-ac8d-b9bb97909bf2', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 13, 13, 'የእግዚአብሔርን ቤትና የንጉሡን ቤት አቃጠለ፤ የኢየሩሳሌምንም ቤቶች ሁሉ ፥ ታላላቆችን ቤቶች ሁሉ፥ በእሳት አቃጠለ።'),
  ('35c29021-a719-5f3b-a418-11565c2991f1', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 14, 14, 'ከአዛዦችም አለቃ ጋር የነበረው የከለዳውያን ሠራዊት ሁሉ የኢየሩሳሌምን ቅጥር ሁሉ ዙሪያዋን አፈረሱ።'),
  ('7460e77b-03e0-5cd6-a914-c13d92dcc3ad', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 15, 15, 'የአዛዦቹም አለቃ ናቡዛርዳን የሕዝቡን ድኆች፥ በከተማም ውስጥ የቀረውን ሕዝብ፥ ሸሽተውም ወደ ባቢሎን ንጉሥ የተጠጉትን፥ የሕዝቡንም ቅሬታ አመጣ።'),
  ('5fc5e11c-96ba-5d6a-a354-2d5b7e6800c5', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 16, 16, 'የአዛዦቹም አለቃ ናቡዛርዳን ከሀገሩ ድኆች ወይን ተካዮችና አራሾች እንዲሆኑ አስቀረ።'),
  ('0193dfed-33cc-5c13-ae85-ccd6f0e31dab', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 17, 17, 'ከለዳውያንም በእግዚአብሔር ቤት የነበሩትን የናስ ዐምዶች በእግዚአብሔርም ቤት የነበሩትን መቀመጫዎችና የናሱን ኩሬ ሰባበሩ፤ ናሱንም ወደ ባቢሎን ወሰዱ።'),
  ('34d763c9-8a0f-53fb-a4e0-b235b8daca3a', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 18, 18, 'ምንቸቶቹንና መጫሪያዎችን፥ መኰስተሪያዎችንና ድስቶችን፥ ጭልፋዎችንም፥ የሚያገለግሉበትንም የናስ ዕቃ ሁሉ ወሰዱ።'),
  ('6f3077c8-97ea-546a-a7c5-07aa4eaa9aff', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 19, 19, 'የአዛዦችም አለቃ ጽዋዎቹን፥ ማንደጃዎቹን፥ ድስቶቹንና ምንቸቶቹን፥ መቅረዞቹንና ጭልፋዎቹን፥ መንቀሎችንም፥ የወርቁን ዕቃ በወርቅ፥ የብሩንም ዕቃ በብር አድርጎ፥ ወሰደ።'),
  ('4adb680a-3732-567b-a97c-5d92cc2d2804', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 20, 20, 'ንጉሡ ሰሎሞን ለእግዚአብሔር ቤት ያሠራቸውን ሁለቱን ዐምዶች፥ አንዱንም ኵሬ፥ ከመቀመጫዎቹም በታች የነበሩትን ዐሥራ ሁለቱን የናስ በሬዎች ወሰደ፤ ለእነዚህ የናስ ዕቃዎች ሁሉ ሚዛን አልነበራቸውም።'),
  ('922fb14d-f4db-5285-a035-453e5b539baa', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 21, 21, 'ዐምዶቹም፥ የአንዱ ዓምድ ቁመት ዐሥራ ስምንት ክንድ ነበረ፥ የዙሪያውም መጠን ዐሥራ ሁለት ክንድ ነበረ፤ ውፍረቱም ጋት ያህል ነበረ፤ ባዶም ነበረ።'),
  ('ce7b0515-284c-5c08-ab64-baf883c339e7', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 22, 22, 'የናሱም ጕልላት በላዩ ነበረ፤ የአንዱም ጕልላት ቁመት አምስት ክንድ ነበረ፤ በጕልላቱም ላይ በዙሪያው ሁሉ ከናስ የተሠሩ መርበብና ሮማኖች ነበሩበት፤ በሁለተኛውም ዐምድ ደግሞ እንደዚህ ያለ ነገርና ሮማኖች ነበሩበት።'),
  ('6a68f37a-bb47-5aca-a091-c349e05331c2', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 23, 23, 'በስተ ውጭም ዘጠና ስድስት ሮማኖች ነበሩ፤ በመርበቡም ዙሪያ የነበሩ ሮማኖች ሁሉ አንድ መቶ ነበሩ።'),
  ('529d3c69-6343-5642-accd-8ed169b6f869', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 24, 24, 'የአዛዦቹም አለቃ ታላቅን ካህን ሠራያን፥ ሁለተኛውንም ካህን ሶፎንያስን፥ ሦስቱንም በረኞች ወሰደ፤'),
  ('ff59d5ae-c610-566b-a27e-2bb05fd66d3f', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 25, 25, 'ከከተማዪቱም በሰልፈኞች ላይ ተሾመው ከነበሩት አንዱን ጃንደረባ፥ በከተማዪቱም ከሚገኙት በንጉሡ ፊት ከሚቆሙት ሰባቱን ሰዎች፥ የሀገሩን ሕዝብ የሚያሰልፈውን የሠራዊቱን አለቃ ጸሐፊ፥ በከተማዪቱም ከተገኙት የሀገሩ ሕዝብ ስድሳ ሰዎችን ወሰደ።'),
  ('dd5f5452-d3d4-5f9f-ac36-d004876f6959', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 26, 26, 'የአዛዦቹም አለቃ ናቡዛርዳን ወስዶ የባቢሎን ንጉሥ ወዳለበት ወደ ዴብላታ ወሰዳቸው።'),
  ('59799de1-e04d-5ea7-a6d6-8231af926877', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 27, 27, 'የባቢሎንም ንጉሥ መታቸው፤ በኤማትም ምድር ባለችው በዴብላታ ገደላቸው፤ እንዲሁ ይሁዳ ከሀገሩ ተማረከ።'),
  ('873c945d-d664-5a1c-af23-ef0df2429803', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 28, 28, 'ናቡከደነፆር የማረከው ሕዝብ ይህ ነው፤ በሰባተኛው ዓመት ሦስት ሺህ ሃያ ሦስት አይሁድ፤'),
  ('a6f96abf-c483-549a-a8e3-b42147be5513', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 29, 29, 'ናቡከደነፆርም በዐሥራ ስምንተኛው ዓመተ መንግሥት ስምንት መቶ ሠላሳ ሁለት ነፍስ ከኢየሩሳሌም ማርኮአል፤'),
  ('114e0acc-8ce7-54bf-a195-3bf204118f6c', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', '9a0f2cd3-8887-5ec2-ac8e-932fce37cc6e', 30, 30, 'በናቡከደነፆር በሃያ ሦስተኛው ዓመተ መንግሥት የአዛዦቹ አለቃ ናቡዛርዳን ከአይሁድ ሰባት መቶ አርባ አምስት ነፍስ ማርኮአል፤ ሰዎችም ሁሉ አራት ሺህ ስድስት መቶ ነበሩ።'),
  ('057adaed-33e6-5485-ac4e-d15f82de5589', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', 'bab68b47-d46d-543e-aecd-703be9edf821', 1, 31, 'እንዲህም ሆነ፤ የይሁዳ ንጉሥ ኢኮንያን በተማረከ በሠላሳ ሰባተኛው ዓመት፥ በዐሥራ ሁለተኛው ወር ከወሩም በሃያ አምስተኛው ቀን፥ የባቢሎን ንጉሥ ዮርማሮዴቅ በነገሠ በአንደኛው ዓመት የይሁዳን ንጉሥ የኢኮንያንን ራስ ከፍ ከፍ አደረገ፤ ከወህኒም አወጣው፤'),
  ('f078525b-0ded-5369-ad06-cee5b2a17277', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', 'bab68b47-d46d-543e-aecd-703be9edf821', 2, 32, 'በመልካምም ተናገረው፤ ዙፋኑንም ከእርሱ ጋር በባቢሎን ከነበሩት ነገሥታት ዙፋን በላይ አደረገለት።'),
  ('74f4d63f-566e-5b10-ace3-22e21f3162af', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', 'bab68b47-d46d-543e-aecd-703be9edf821', 3, 33, 'በወህኒም ውስጥ ለብሶት የነበረውን ልብስ ለወጠለት፥ ኢኮንያንም በሕይወቱ ዘመን ሁሉ በፊቱ ሁልጊዜ እንጀራ ይበላ ነበር።'),
  ('b482a73e-8238-5abc-a361-e53f2fb3790d', 'aef7d7d6-2ed1-5ed4-abc6-197834eecd05', 'bab68b47-d46d-543e-aecd-703be9edf821', 4, 34, 'የባቢሎንም ንጉሥ በሕይወቱ ዘመን ሁሉ እስኪሞት ድረስ የዘወትር ድርጎ ዕለት ዕለት ይሰጠው ነበር።'),
  ('2283927e-7eff-51cf-acb4-3768e47cdbe0', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 1, 1, 'የኬልቅዩ ልጅ የአሳድዩ ልጅ የሴዴቅያስ ልጅ የማሴው ልጅ የኔርዩ ልጅ ባሮክ ወደ ባቢሎን የጻፈው ነገር ይህ ነው፤'),
  ('c6e009ca-a07a-5513-ac41-50955db62836', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 2, 2, 'በአምስተኛው ዓመት ከወሩ በሰባተኛው ቀን ከለዳውያን ኢየሩሳሌምን በያዙአትና በእሳት በአቃጠሏት ጊዜ፥'),
  ('4208cbc4-ed70-5e4d-ad88-6b4643feeaac', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 3, 3, 'ባሮክ ይህን መጽሐፍ በይሁዳ ንጉሥ በኢዮአቄም ልጅ በኢኮንያን ጆሮና መጽሐፉን ለመስማት ከሕዝቡ ዘንድ ወደ እርሱ በመጣው ሕዝብ ሁሉ ጆሮ፥'),
  ('cbd0ce21-f212-5e52-a194-7953df16dc0b', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 4, 4, 'በኀያላኑና በልዑላኑ ጆሮ፥ በሽማግሌዎች ጆሮና ከታላቁ ጀምሮ እስከ ታናሹ ድረስ በባቢሎን በሶዲ ወንዝ አጠገብ በሚኖሩ ሕዝብ ሁሉ ጆሮ አነበበ።'),
  ('c6fcf66a-309d-5841-a845-7f88d4b9ec91', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 5, 5, 'እነርሱም በእግዚአብሔር ፊት አለቀሱ፤ ጾሙ፤ ጸለዩም።'),
  ('81468ddb-63da-5ee4-ae80-14b408c46496', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 6, 6, 'እያንዳንዳቸውም እንደ እየችሎታቸው ገንዘብ ሰበሰቡ፤'),
  ('626ca644-a1a4-5482-a407-719c36e54570', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 7, 7, 'እርሱንም ወደ ሰሉም ልጅ ወደ ኬልቅያ ልጅ ወደ ካህኑ ኢዮአቄም፥ በኢየሩሳሌም ከእርሱ ጋር ወደ ነበሩት ካህናትና ወደ ሕዝቡ ሁሉ ላኩት።'),
  ('1333280e-0c44-5e4b-ab21-e7c80ed6e479', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 8, 8, 'ከቤተ መቅደስ የተወሰደውን የእግዚአብሔርን ቤት ዕቃ ወደ ይሁዳ ምድር ይመልሱ ዘንድ በሲባን ወር በዐሥረኛው ቀን በወሰዱ ጊዜ ይህም ዕቃ የይሁዳ ንጉሥ የኢዮስያስ ልጅ ሴዴቅያስ ያሠራው የብር ዕቃ ነበር።'),
  ('0aa43684-1122-5f91-ad7d-ee962cd0c4a0', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', 'ebd02280-bcde-5758-a8e7-bca05d7a2b4e', 9, 9, 'ይኸውም የባቢሎን ንጉሥ ናቡከደነፆር ኢኮንያንንና መኳንንቱን፥ ምርኮኞቹንና ኀያላኑን የሀገሩንም ሕዝብ ይዞ ከኢየሩሳሌም ወደ ባቢሎን ከወሰዳቸው በኋላ ነበር።'),
  ('ecfe5137-12bf-5c9b-afe1-4e2266a6d50a', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '925ef6f3-219d-5b1a-aa13-3ce548e1db3e', 1, 10, 'እንዲህም አሉ፥ “እነሆ ገንዘብ ልከንላችኋል፤ በእርሱም የሚቃጠል መሥዋዕትና የኀጢአት መሥዋዕት፤ ዕጣንም ግዙበት፤ ኅብስትም አዘጋጁ፤ በአምላካችን በእግዚአብሔር መሠዊያም አቅርቡ።'),
  ('2bb7073d-089e-568e-ab6d-fa57d6851f53', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '925ef6f3-219d-5b1a-aa13-3ce548e1db3e', 2, 11, 'ዘመናቸው በምድር ላይ እንደ ሰማይ ዘመን ይሆን ዘንድ ስለ ባቢሎን ንጉሥ ስለ ናቡከደነፆር ሕይወትና ስለ ልጁ ስለ ብልጣሶር ሕይወት ጸልዩ።'),
  ('490920b3-5ac4-5769-ad72-8b9fa8414962', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '925ef6f3-219d-5b1a-aa13-3ce548e1db3e', 3, 12, 'ለእኛም እግዚአብሔር ኀይልን ይሰጠን ዘንድ፥ ዐይኖቻችንንም ያበራልን ዘንድ፥ በባቢሎን ንጉሥ በናቡከደነፆር ጥላ ሥርና በልጁ በብልጣሶር ጥላ ሥር በሕይወት እንኖር ዘንድ፥ ለብዙ ዘመንም እንገዛላቸው ዘንድ፥ በፊታቸውም ባለሟልነትን እናገኝ ዘንድ ጸልዩ።'),
  ('e8ec898b-d635-5d0e-af05-29d3de37e0a5', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '925ef6f3-219d-5b1a-aa13-3ce548e1db3e', 4, 13, 'አምላካችንን በድለናልና፤ የእግዚአብሔርም መዓቱ መቅሠፍቱም እስከዚች ቀን ድረስ ከእኛ አልተመለሰችምና ለእኛም ወደ አምላካችን ወደ እግዚአብሔር ጸልዩልን።'),
  ('1cab5fa1-8532-5f64-ab62-1f62a55617a0', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '925ef6f3-219d-5b1a-aa13-3ce548e1db3e', 5, 14, 'ወደ እናንተ የላክናትን ይህችንም ደብዳቤ አንብቡአት፤ በበዓል ቀንና በተወደደውም ዕለት በእግዚአብሔር ቤት ተናዘዙ።'),
  ('d5c347f2-6c76-574b-afe6-769b4b9a1ab6', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 1, 15, '“እንዲህም በሉ፤ ጽድቅ ለአምላካችን ለእግዚአብሔር ነው፤ ለእኛ ግን ለፊታችን ኀፍረት ነው፤ ይህች ቀን ለይሁዳ ሰዎችና በኢየሩሳሌም ለሚኖሩ፥'),
  ('b1d12307-0e16-5d3b-a631-636fd9af16c3', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 2, 16, 'ለንጉሦቻችንና ለአለቆቻችን፥ ለካህኖቻችንና ለነቢያቶቻችን፥ ለአባቶቻችንም ኀፍረት እንደ ሆነች።'),
  ('e3e69a55-e474-5fff-a018-d81029c844be', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 3, 17, 'በአምላካችን በእግዚአብሔር ፊት በድለናልና፤'),
  ('c0ab8601-7279-5272-a099-e91c3cd30179', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 4, 18, 'አልታዘዝነውምና የአምላካችን የእግዚአብሔርንም ቃል አልሰማንምና፤ በሰጠን በአምላካችን በእግዚአብሔር ትእዛዝ አልሄድንምና፤'),
  ('aefdf43a-fd29-588a-a0b4-c352914d884e', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 5, 19, 'አባቶቻችንን ከግብፅ ምድር ከአወጣበት ጊዜ ጀምሮ እስከዚች ቀን ድረስ አምላካችንን እግዚአብሔርን አልታዘዝነውም፤ ቃሉንም እንዳንሰማ ከእርሱ ራቅን።'),
  ('a5d0ba9a-6aff-5576-a2f1-cee8ce9f79ca', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 6, 20, 'ወተትና መዓር የምታፈስሰውን ምድር ይሰጠን ዘንድ አባቶቻችንን ከግብፅ ምድር በአወጣበት ቀን እግዚአብሔር ለባሪያው ለሙሴ ያዘዘው ይህ ክፉ ነገርና መርገም እንደ ዛሬው ዕለት አገኘን።'),
  ('503b8860-48ce-5acb-acbe-4819aa3a3ed0', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 7, 21, 'ወደ እኛ እንደ ላካቸው እንደ ነቢያት ቃል የአምላካችንን የእግዚአብሔርን ቃል አልሰማንም።'),
  ('82359056-577b-5883-ad50-73926074606b', '02a30e5d-6779-5ec2-a147-fdb7015d9c75', '466792a4-149a-58b5-ad56-a167c145186f', 8, 22, 'በአምላካችን በእግዚአብሔር ፊት ክፉ እናደርግ ዘንድ ለባዕዳን አማልክት እየተገዛን እያንዳንዳችን በክፉ ልባችን ፈቃድ ሄድን።'),
  ('d6a87064-eeed-5888-a438-be5d882ae415', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 1, 1, '“አምላካችን በእኛና እስራኤልን በገዙ መሳፍንቶቻችን ላይ፥ በነገሥታቶቻችን ላይና በመኳንንቶቻችን ላይ፥ በይሁዳና በእስራኤልም ሁሉ ላይ የተናገረውን ቃሉን አጸና።'),
  ('fbf9d2d8-7364-500e-aac8-dad98f79ff68', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 2, 2, 'በሙሴ ኦሪት እንደ ተጻፈው በኢየሩሳሌም እንደ አደረገው ከሰማይ በታች ያልሆነ ክፉ ነገርን በእኛ ላይ ያመጣ ዘንድ፥ ቃሉን አጸና።'),
  ('deb7055e-d704-555a-a6fe-f419151b7683', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 3, 3, 'በዚያ ወራት ሰው የወንዶች ልጆቹንና የሴቶች ልጆቹን ሥጋ በላ።'),
  ('c53cefc2-6c1c-5ccb-ad2a-e0dbb95863b1', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 4, 4, 'እግዚአብሔር እነርሱን በበተነበት በዙሪአችን በአሉ አሕዛብ ዘንድ ለውርደትና ለመከራ ይሆኑ ዘንድ በዙሪያችን በአሉ ነገሥት ሁሉ እጅ አሳልፎ ሰጣቸው።'),
  ('66a43a80-c4bf-59ab-afd1-e4cb2209069e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 5, 5, 'ወራዶች ሆንን፤ የከበርንም አልሆንም፤ ለቃሉ ሳንታዘዝ አምላካችንን እግዚአብሔርን በድለናልና።'),
  ('b51a4dd5-c111-5269-a80a-2313e01241eb', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 6, 6, 'ጽድቅ ለአምላካችን ለእግዚአብሔር ነው፤ ለእኛና ለአባቶቻችን ግን እንደ ዛሬው ዕለት የፊት ኀፍረት ነው።'),
  ('1b1642e8-2dc9-5706-a5e1-3633b7636dcf', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 7, 7, 'በእኛ ላይ የደረሰውን ክፉ ነገር ሁሉ እግዚአብሔር በእኛ ላይ ተናግሮ ነበርና።'),
  ('cbabb6d3-39a9-5fec-a589-705884f61725', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 8, 8, 'እያንዳንዳችንም ከክፉ ልባችን መንገድ እንመለስ ዘንድ በአምላካችን በእግዚአብሔር ፊት አልጸለይንም።'),
  ('b646cbeb-25b1-5aad-a5fd-63c2e9bd4bc4', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 9, 9, 'እግዚአብሔርም ለመከራ ተጋ፤ በእኛም ላይ አመጣው፤ እግዚአብሔር በእኛ ላይ ባዘዘው ሥራው ሁሉ ጻድቅ ነውና።'),
  ('a939b00c-72e3-54bd-a108-d85532b0cce9', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 10, 10, 'በፊታችን በሰጠን በእግዚአብሔርም ትእዛዝ እንሄድ ዘንድ ቃሉን አልሰማንም።'),
  ('915ca031-7a93-5b6f-a45b-920b4021ee6e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 11, 11, '“አሁንም በጸናች እጅ፥ በተአምርና በድንቅ ሥራ፤ በታላቅ ኀይልና በተዘጋጀች ክንድ ሕዝብህን ከግብፅ ምድር ያወጣህ፥ ዛሬም እንደ ሆነው ለራስህ ታላቅ ስምን ያደረግህ የእስራኤል አምላክ ሆይ!'),
  ('a1345b89-fc77-5623-a3f9-185a807b6a43', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 12, 12, 'በደልን፤ ክፉም አደረግን፤ አቤቱ አምላካችን ሆይ! በሥርዐትህ ሁሉ ላይ የማይገባ ሥራን ሠራን።'),
  ('f78098e0-4b29-5c00-a829-80407cb8132d', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 13, 13, 'ቍጣህን ከእኛ አብርድ፤ እኛን በዚያ በበተንህበት በአሕዛብ ዘንድ ጥቂት ቀርተናልና።'),
  ('b916b3f1-290c-52cf-ab00-9c5ed0fd8845', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 14, 14, 'ጌታ ሆይ! ልመናችንንና ጸሎታችንን ስማ፤ ስለ ስምህም ስትል አድነን፤ በማረኩንም ሰዎች ፊት ሞገስን እናገኝ ዘንድ ስጠን፤'),
  ('9e184a84-35bd-5cd5-a537-9c392747c7ed', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 15, 15, 'ምድር ሁሉ አንተ እግዚአብሔር አምላካችን እንደ ሆንህ ታውቅ ዘንድ፥ ስምህ በእስራኤል ላይና በወገኑ ላይ ተጠርቶአልና ።'),
  ('2636ab45-270f-51ee-a88d-7a291d798b3f', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 16, 16, 'አቤቱ ከቤተ መቅደስህ ሁነህ ተመልከት፤ አቤቱ ጆሮህን ወደ እኛ አዘንብለህ ስማን።'),
  ('0b1de500-5470-58d6-ad6a-26e0f564807e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 17, 17, '“ዐይኖችህን ገልጠህ ተመልከት፤ አቤቱ ነፍሳቸው ከሥጋቸው የተለየች በመቃብር የሚኖሩ ሙታን የሚያከብሩህና የሚያመሰግኑህ አይደሉምና።'),
  ('4826dfd4-93db-556c-aafa-e49a96930fe9', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 18, 18, 'ነገር ግን አዝናና ተጨንቃ የምትኖር፥ በብዙ መከራም ያዘነች ሰውነትና የፈዘዙ ዐይኖች፥ የተራበችም ነፍስ ያመሰግኑሃል፤ አቤቱ ለጽድቅህም ይገዛሉ።'),
  ('78039280-0869-5995-a31b-8633856b52e3', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 19, 19, 'አቤቱ አምላካችን በፊትህ ምሕረትን የለመንንህ እንደ አባቶቻችንና ነገሥታቶቻችን ጽድቅ አይደለምና።'),
  ('eb019ccf-8cdc-514a-a2ba-d3cf856ecba1', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 20, 20, 'በባሪያዎችህ በነቢያት እጅ እንደ ተናገርህ መዓትህንና መቅሠፍትህን በእኛ ላይ ሰድደሃልና።'),
  ('101e5758-4b9f-581e-a3ed-f177e913e170', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 21, 21, '“እግዚአብሔር እንዲህ ይላል፦ ትከሻችሁን ዝቅ አድርጉ ለባቢሎንም ንጉሥ ተገዙ፤ ለአባቶቻችሁ በሰጠኋት ምድርም ትኖራላችሁ፤'),
  ('e5e82c9b-5f00-54e3-aded-baf3d8dc1377', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 22, 22, 'የእግዚአብሔርን ቃል ባትሰሙ፥ ለባቢሎንም ንጉሥ ባትገዙ፥'),
  ('14e4364e-88a9-5fdf-af25-f053db226f18', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 23, 23, 'የደስታና የሐሤት ድምፅ፥ የወንድ ሙሽራና የሴት ሙሽራ ድምፅ ከይሁዳ ከተሞችና ከኢየሩሳሌም ውጭ ይጠፋል፤ ምድርም ሁሉ ከነዋሪዎች ምድረ በዳ ይሆናል።'),
  ('7acab5fd-f62c-5acb-ac24-a3e12578470e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 24, 24, 'ቃልህን አልሰማንም፤ ለባቢሎንም ንጉሥ አልተገዛንም፤ የንጉሦቻችን ዐፅሞችና የአባቶቻችን ዐፅሞች ከቦታቸው እንደሚወጡ በባሮችህ ነቢያት እጅ የተናገርኸውም ደረሰብን።'),
  ('05c00900-2b3b-592b-afd3-c563cf85505e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 25, 25, '“እነሆ በቀን ሐሩርና በሌሊት ቍር ጣሏቸው፤ ተማረክን፤ በቀጠናና በጦር፥ በቸነፈርም ክፉ ሞትን ሞትን።'),
  ('d92feda4-f95f-5704-a7e5-3b3f4e19f32e', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 26, 26, 'በእስራኤል ወገንና በይሁዳ ወገን ኀጢአት ምክንያት ስምህ የተጠራበትን መቅደስ እንደ ዛሬው ዕለት ጣልህ።'),
  ('33aa78c8-7c47-5436-a541-75fc004d9f6b', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 27, 27, 'ነገር ግን አቤቱ አምላካችን! እንደ ቸርነትህ ሁሉና እንደ ታላቁ ይቅርታህ ሁሉ አደረግህልን፤'),
  ('070bf72f-dc4b-570e-a2a9-ab89ff598165', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 28, 28, 'በእስራኤል ልጆች ፊት ሕግህን ይጽፍ ዘንድ ባዘዝህባት ዕለት በአገልጋይህ በሙሴ እጅ እንዲህ ስትል እንደ ተናገርህ፥'),
  ('50aa6d5f-1f34-5034-a852-d8e3dccfdd7c', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 29, 29, 'ቃሌን በእውነት ባትሰሙ ይህች ብዛታችሁ እናንተን በበተንሁባቸው በአሕዛብ መካከል ወደ ጥቂትነት ትመለሳለች።'),
  ('193c87c5-cffc-5844-a48c-13ac4d437857', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 30, 30, '“እንደማይሰሙኝም ዐወቅኋቸው፤ አንገተ ደንዳና ሕዝብ ናቸውና፤ በተሰደዱበትም ሀገር ወደ ፈቃዳቸው ይመለሳሉ።'),
  ('f7da212b-75f9-5400-aa00-9b812f94f48b', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 31, 31, 'እኔም አምላካቸው እግዚአብሔር እንደ ሆንሁ ያውቃሉ። ልብን፥ ለመስማትም ጆሮን እሰጣቸዋለሁ።'),
  ('fe716396-c143-58af-a59d-8aefb676570f', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 32, 32, 'ባስማረክኋቸውም ሀገር ያመሰግኑኛል፤ ስሜንም ያስባሉ።'),
  ('c90d479b-2ee1-50ee-ac12-2204e372d507', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 33, 33, 'ከደንዳና ልባቸውና ከክፉ ሥራቸው ይመለሳሉ፤ በእግዚአብሔር ፊት የበደሉ የአባቶቻቸውንም መንገድ ያስባሉ።'),
  ('05e8214f-1c63-587a-af57-a2a305eb40bc', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 34, 34, 'ለአባቶቻቸው ለአብርሃም፥ ለይስሐቅና ለያዕቆብም ወደ ማልሁላቸው ሀገር እመልሳቸዋለሁ፤ ይገዙአታልም፤ እኔም አበዛቸዋለሁ፤ እነርሱም አያንሱም።'),
  ('cfe7fdd1-e6fd-5a2d-a6a8-b8c0f01240e3', '94ece345-b268-5d5c-a76d-9af50d6594cb', '71f54e94-9888-5c33-a8f6-3fd85a75858d', 35, 35, 'አምላካቸው እሆናቸው ዘንድ የዘለዓለም ቃል ኪዳንን እሠራላቸዋለሁ፤ እነርሱም ሕዝቤ ይሆኑኛል፤ ከእንግዲህም ወዲህ ሕዝቤ እስራኤልን ከሰጠኋቸው ሀገራቸው አላወጣቸውም።'),
  ('6f59cfdf-9bf8-5f59-a36f-41300b87fe66', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 1, 1, '“አቤቱ! ነግሠህ የምትኖር የእስራኤል አምላክ ሆይ! የተራበች ነፍስ፥ ያዘነችም ነፍስ ወደ አንተ ጮኸች።'),
  ('ddd62702-3400-5587-ac00-3742457d2b85', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 2, 2, 'አቤቱ! ሰምተህ ይቅር በላት፤ በፊትህ በድለናልና።'),
  ('810a0af9-db2c-5097-a8fc-d598a0fbc9dd', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 3, 3, 'አንተ ለዘለዓለሙ የምትኖር ነህና፥ እኛ ግን ለዘለዓለሙ እንጠፋለንና።'),
  ('0700c6f8-f7bf-593f-a9dd-df0de7fd4d0c', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 4, 4, 'በሁሉ ላይ የምትነግሥ የእስራኤል አምላክ አቤቱ! የሙታን የእስራኤልን፥ በፊትህም የበደሉ፥ የአምላካቸውንም ቃል ያልሰሙ የልጆቻቸውን ጸሎት ስማ።'),
  ('fd681fca-847d-5eed-aef6-f239341b4f23', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 5, 5, 'ክፉ ነገርም ተከተለን፤ የአባቶቻችንንም ኀጢአት አላሰብንም፤ በዚህም ወራት እጅህንና ስምህን ዐስብ።'),
  ('de8c1ff0-cdc0-5efe-a1e3-5947aa29ec2a', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 6, 6, 'አንተ እግዚአብሔር አምላካችን ነህና አቤቱ! እናመሰግንሃለን።'),
  ('8dd25e47-0fed-5c8e-ac41-5ff7f9620473', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 7, 7, 'ስለዚህም ስምህን እንጠራ ዘንድ፥ ባስማረክኸንም ቦታ እናመሰግንህ ዘንድ መፈራትህን በልቡናችን አሳደርህ። በፊትህ የበደሉ የአባቶቻችንን ክፋት ሁሉ ከልባችን አርቀናልና።'),
  ('eb9cb60e-53d1-5612-ab81-66436bde0f4f', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 8, 8, 'አቤቱ አምላካችን! እነሆ ዛሬ፦ ከአንተ እንደ ራቁ አባቶቻችን ክፋት ሁሉ ለውርደት፥ ለርግማንና ለፍዳ በበተንኸን ምርኮ ውስጥ ነን።”'),
  ('3cbc2da6-58c6-5709-aaf8-74b36282367e', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 9, 9, 'እስራኤል ሆይ፥ የሕይወትን ትእዛዝ ስማ፥ የጥበብንም ምክር አድምጥ።'),
  ('fd8b9e3a-89e7-59ce-a910-b8ba08db5dc2', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 10, 10, 'እስራኤል ምንድን ነው? በጠላትስ ሀገር ለምን ይኖራል?'),
  ('9c727a3e-d536-508c-a3a3-85c63ecd6650', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 11, 11, 'በባዕድ ሀገርስ ለምን ጠፋ? ከሬሳዎችስ ጋር ለምን ረከሰ? ወደ መቃብር ከወረዱት ጋርስ ለምን ተቈጠረ?'),
  ('a47868b5-acd0-584d-a35c-3ec338d0e398', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 12, 12, 'የሕይወትን ምንጭ ተውህ?'),
  ('0f6fd56e-7b38-585b-a621-1047283e8f5f', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 13, 13, 'በእግዚአብሔርስ መንገድ ብትሄድ ለዘለዓለም በሰላም በኖርህ ነበር!'),
  ('ae64d0ab-e016-5f65-a92c-8eeb4a7eeeee', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 14, 14, 'ተማር፥ ጥበብ ከየት ነው? ኀይልስ ከየት ነው? ምክርና ዕውቀትስ ከየት ናቸው? ለብዙ ዘመናት መኖርስ ከየት ነው? የዐይኖች ብርሃንና ሰላም ከየት ናቸው?'),
  ('28199273-45af-50ef-afff-d818ae27d23c', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 15, 15, 'የጥበብ ሀገሯን ማን አገኘ? ወደ መዛግብትዋስ ማን ገባ?'),
  ('7512d413-71b1-50e5-aaef-d4afff41641d', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 16, 16, 'የምድረ በዳ አውሬዎችን የገዙ የአሕዛብ አለቆች ወዴት ናቸው?'),
  ('5b16393b-4a57-53f8-a0c6-783a7ffd3c95', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 17, 17, 'በሰማይ አዕዋፍም የሚጫወቱ ሰዎች የሚታመኑበት ብርና ወርቅን የሚሰበስቡ፤ ለመሰብሰባቸውም ወሰን የሌላቸው የአሕዛብ አለቆች ወዴት ናቸው?'),
  ('489a4db5-cccc-569c-a696-0d2cb3a83011', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 18, 18, 'ብርን የሚያነጥሩ ይተጋሉና፥ ለሥራቸውም ምርመራ የለውም።'),
  ('1a4bceac-9660-5ab7-a666-2691d6330375', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 19, 19, 'አለቁ፤ ወደ መቃብርም ወረዱ፤ ስለ እነርሱም ሌሎች ተተኩ።'),
  ('ebdf569c-6254-507a-ad32-ba9d26377f2d', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 20, 20, 'ታናናሾች ብርሃንን አዩ፤ በምድራቸውም ኖሩ፤ የጥበብን መንገድ ግን አላወቁም።'),
  ('29a78132-cea8-5abe-ab04-6431f69742e6', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 21, 21, 'ፍለጋውንም አላገኙም፤ አልተቀበሉአትም፤ ልጆቻቸውም ከመንገዳቸው ራቁ።'),
  ('3a8d2186-7240-5713-ad93-b3a36afaa84f', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 22, 22, 'የከነዓን ሰዎች አልሰሙም፤ የቴምናም ሰዎች አላዩም።'),
  ('6f135872-59ab-5e26-a0fa-b128a4131fe3', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 23, 23, 'በምድር ጥበብን የሚፈልጓት የአጋር ልጆችም የሚጫወቱባት፥ ዕውቀትንም የሚፈልጓት፥ የመርያንና የቴምና ነጋዴዎችም የጥበብን ጐዳና አላወቁም፤ ፍለጋዋንም አላስተዋሉም።'),
  ('6db46b96-c2b4-5f1c-a3a2-d88c37212247', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 24, 24, 'እስራኤል ሆይ! የእግዚአብሔር ቤት እንዴት ታላቅ ነው! ቦታውም እንዴት ሰፊ ነው! ፍጻሜ የለውም፤ መለኪያም የለውም።'),
  ('0abf27d8-c54c-517b-ac1d-a7f214b4af32', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 25, 25, 'ታላቅ ነው፤ ፍጻሜም የለውም፤ ላይኛውም መለኪያ የለውም።'),
  ('072f6ac2-3db7-57d0-a465-168f04421e41', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 26, 26, 'ከጥንት ጀምሮ ቁመታቸው ረዥም የሆነ፥ ጦርነትንም የሚያውቁ ረዐይት የሚባሉ በዚያ ነበሩ።'),
  ('99f2d182-f35d-5224-a7c7-e7098cca972c', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 27, 27, 'እነዚህን እግዚአብሔር አልመረጣቸውም፤ የዕውቀት መንገድንም አልሰጣቸውም።'),
  ('a26079b1-3d68-562c-aa66-c4080c73360e', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 28, 28, 'ጥበብ አልነበራቸውምና ጠፉ፤ በድፍረታቸውም ጠፉ።'),
  ('454b8fb6-167e-5ba6-a91d-da02a94eb628', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 29, 29, 'ወደ ሰማይ የወጣና የያዛት፤ ከደመናትም ያወረዳት ማነው?'),
  ('d42259f7-7c52-58df-aa06-0ae8f7c82210', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 30, 30, 'ባሕሩን ተሻግሮ ያገኛት፥ በቀይ ወርቅስ ያመጣት ማነው?'),
  ('97465ce6-a18a-5b2c-a6fb-fed1c719948f', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 31, 31, 'መንገድዋን የሚያውቅ፥ ፍለጋዋንም የሚያስብ የለም።'),
  ('c756b552-121c-5f9c-a733-cd1e073664f1', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 32, 32, 'ሁሉን የሚያውቅ ያውቃታል፤ በጥበቡም አገኛት። ምድርን የፈጠረ ለዘለዓለም በእንስሳት ሞላት።'),
  ('d600d229-0e1f-525e-a622-90607099a10f', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 33, 33, 'ብርሃኑን ይልካል፤ እርሱም ይሄዳል፤ እንደ ገናም ይጠራዋል፤ በፍርሃትም ይታዘዘዋል።'),
  ('51ee209e-1e38-5cc1-a613-0e7dedafb6cd', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 34, 34, 'ከዋክብትም በየጊዜያቸው ያበራሉ፤ ደስም ይላቸዋል።'),
  ('ba55a839-fceb-5686-a137-0eb507b6beec', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 35, 35, 'ይጠራቸዋል፤ እነርሱም፦ መጣን ይላሉ። ለፈጠራቸውም በደስታ ያበራሉ።'),
  ('4cf887fb-8c44-50b4-a04d-141f5928cf2c', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 36, 36, 'እርሱን የሚመስል ሌላ የለምና አምላካችን ነው ይላሉ።'),
  ('bc69b61f-ef08-50b8-ae04-2a126c2da971', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 37, 37, 'የጥበብን መንገድ ሁሉ እርሱ አገኛት፤ ለባለሟሉ ለያዕቆብ፥ ለወዳጁም ለእስራኤል ሰጠው።'),
  ('b0683a84-9dcf-5b45-ab3b-9cc85f3aabf7', '46855083-854d-55c0-a8ed-67d69fc97b65', '55d72f37-73ac-558f-a644-e11ccf01f6e4', 38, 38, 'ከዚህ በኋላ በምድር ተገለጠ፤ እንደ ሰውም ሆነ።'),
  ('3a0b3ffb-f033-573f-a04e-41a5e4f0a367', 'afcd5893-919d-56a0-a857-a44ae3c37348', '5408a419-99c3-5034-a423-2ee20f3018e2', 1, 1, 'የዘላለም ሕግ የሆነ የእግዚአብሔር የትእዛዙ መጽሐፍ ይህ ነው፤ የሚጠብቋትም ሁሉ ይኖራሉ፤ የሚተዉኣት ግን ይሞታሉ።'),
  ('82d52fde-b97a-5f39-ae38-57202cd0a92c', 'afcd5893-919d-56a0-a857-a44ae3c37348', '5408a419-99c3-5034-a423-2ee20f3018e2', 2, 2, 'ያዕቆብ! ተመልሰህ ያዛት፤ በብርሃንዋም ሂድ።'),
  ('913b019a-1820-5249-afe2-06cfaf08d4e8', 'afcd5893-919d-56a0-a857-a44ae3c37348', '5408a419-99c3-5034-a423-2ee20f3018e2', 3, 3, 'ክብርህን ለባዕድ አትስጥ፤ የሚሻልህንም ለሌላ ወገን አትስጥ።'),
  ('7b21b2df-dfc5-56ba-a253-414a2ad60c4f', 'afcd5893-919d-56a0-a857-a44ae3c37348', '5408a419-99c3-5034-a423-2ee20f3018e2', 4, 4, 'የአምላካችን የእግዚአብሔር ምሕረት በእኛ ታውቋልና እኛ እስራኤል ብፁዓን ነን።'),
  ('40a9dba4-e10b-55c3-a737-647b9d8a273c', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 1, 5, 'ወገኖች ተጽናኑ፤ እስራኤልም አስቡ።'),
  ('3791324a-cca6-5ad2-ae85-9d214397e149', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 2, 6, 'ለጥፋት ያይደለ ለሌላ ወገን ተሽጣችሁ ነበር፤ ነገር ግን እግዚአብሔርን ስላስቈጣችሁት ለጠላቶቻችሁ ተላልፋችሁ ተሰጥታችሁ ነበር።'),
  ('14ac66f1-faa0-5e6b-a3d3-f6fedfd11ccc', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 3, 7, 'ለእግዚአብሔር ያይደለ ለአጋንንት በመሠዋታችሁ ፈጣሪያችሁን ለመዓት አነሳሳችሁት።'),
  ('2f9243e6-94b4-5858-a366-8e47e4a7cfe4', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 4, 8, 'ያሳደጋችሁን የዘለዓለም አምላካችሁንም ረስታችሁታልና፥ ሞግዚታችሁን ኢየሩሳሌምንም አሳዝናችኋታልና።'),
  ('706860c7-3dad-5f8b-aafa-e9deee37dff9', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 5, 9, 'የመጣባችሁን የእግዚአብሔርን መቅሠፍት ባየች ጊዜ እንዲህ አለች፦ የጽዮን ስደተኞች ስሙ፤ እግዚአብሔር ጽኑፅ ልቅሶን አምጥቶብኛልና።'),
  ('247baebe-fa42-5011-a4af-a1a2bd0fba32', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 6, 10, 'ዘለዓለማዊ አምላክ ያመጣባቸውን የወንዶች ልጆችንና የሴቶች ልጆችን መማረክ አይቻለሁና'),
  ('7d07958e-02d1-5238-a1f3-342ca8563b05', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 7, 11, 'በደስታ አሳድጊያቸው ነበር፤ ነገር ግን በልቅሶና በኀዘን ሸኘኋቸው።'),
  ('bdae7716-0b65-5596-a009-a6c21f0dedf2', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 8, 12, 'በብዙዎች ዘንድ የተጣልሁ በሆንሁ በእኔ በመበለቲቱ ደስ የሚለው አይኑር፤ ከእግዚአብሔር ሕግ ርቀዋልና።'),
  ('6383383d-85a7-5bc3-a9ea-f67f4d05ddb9', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 9, 13, 'ትእዛዙንም አላወቋትም፤ በእግዚአብሔርም በትእዛዙ መንገድ አልተመላለሱም፤ በምክሩም ፍለጋ ወደ ጽድቁ አልገቡም።'),
  ('a24339d0-f804-55ea-a318-780ce528a777', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 10, 14, 'የጽዮን ስደተኞች ይምጡ፤ ዘለዓለማዊው አምላክ ያመጣባቸውን የወንዶች ልጆችንና የሴቶች ልጆችንም ምርኮ ያስቡ።'),
  ('010074ff-4732-5030-ab25-ccaf3f64cb20', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 11, 15, 'የማያፍርና ቋንቋው ልዩ የሆነ ሕዝብን ከሩቅ አምጥቶባቸዋልና፤ ሽማግሌውን አላከበሩምና፥ ለሕፃናቱም አልራሩምና።'),
  ('dd61c53e-06b2-5415-a70c-df1d2a4b3343', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 12, 16, 'የመበለትነቷንም የተወደዱ ልጆች ነጠቁ፤ ከሴቶች ልጆችዋም ለይተው ብቻዋን አስቀሩአት።'),
  ('54aa83b4-a0ce-5fd1-a0f5-764a6a83589b', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 13, 17, 'ነገር ግን እኔ ምን ረዳችኋለሁ?'),
  ('f9fe0893-5392-555e-aabc-6dac8816127a', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 14, 18, 'ክፉ ነገርን ያመጣባችሁ እርሱ ከጠላቶቻችሁ እጆች ያወጣችኋልና።'),
  ('6d07aa6b-8746-590a-acc6-9c35fc5c91b3', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 15, 19, 'ልጆች! መንገዳችሁን ሂዱ፤ መንገዳችሁን ሂዱ፤ እኔ የተፈታች ምድረ በዳ ሁኛለሁና።'),
  ('222c090a-07d6-56ad-a4de-1075a6a4bfcd', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 16, 20, 'የሰላም ልብሴን አወለቅሁ፤ የመከራዬንም ማቅ ለበስሁ፤ በዘመኔም ወደ ዘለዓለማዊው አምላክ እጮሃለሁ፤'),
  ('91d4f2ad-00a3-5294-adfa-b2cf9a073972', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 17, 21, 'ልጆች ተጽናኑ፤ ወደ አምላክም ጩኹ፤ ከጠላቶቻችሁ እጅና አገዛዝ ያወጣችኋል።'),
  ('7f0fc888-5265-5431-a2f5-12144611eb4d', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 18, 22, 'ከዘለዓለማዊው አምላክ ዘንድ ድኅነታችሁን ተስፋ አድርጌአለሁና። ከዘለዓለማዊው መድኀኒታችን ዘንድ ፈጥኖ ስለሚመጣላችሁ ምሕረትም ደስታ ከቅዱሱ መጣልኝ፤'),
  ('59cdaaa3-9d60-5570-a33e-7d06e48ac242', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 19, 23, 'ከኀዘንና ከልቅሶ ጋር ሸኝቻችኋለሁና፤ ነገር ግን እግዚአብሔር እናንተን በደስታና በሐሤት ለዘለዓለም ይመልስልኛል።'),
  ('5bcb0170-1ecb-5016-a7eb-ffd1b3e01b4f', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 20, 24, 'የጽዮን ጎረቤቶች መማረካችሁን እንዳዩ፥ እንዲሁም በታላቅ ክብርና በዘለዓለማዊው አምላክ ብርሃን ከእግዚአብሔር ዘንድ የምትመጣላችሁን ድኅነታችሁን ፈጥነው ያያሉ።'),
  ('c48aaaf2-a810-508c-a354-620347aa8ff9', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 21, 25, 'ልጆች! ከእግዚአብሔር ዘንድ የመጣባችሁን ቍጣ በትዕግሥት ተቀበሉ፤ ጠላቶቻችሁ አሳድደዋችኋልና ውድቀታቸውን ፈጥናችሁ ታያላችሁ፤ በራሳቸውም ላይ ትወጣላችሁ።'),
  ('e2f125c9-6aff-53d0-aa13-8863fe902366', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 22, 26, 'ቅምጥሎች በሻካረው መንገድ ሄዱ፤ ጠላቶችም እንደ ተዘረፉ በጎች ነጠቋቸው።'),
  ('a748d489-9def-5bba-a380-8818bb8c093f', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 23, 27, 'ልጆች! ተጽናኑ፤ ወደ አምላክም ጩኹ፤ የወሰዳችሁ እርሱ ያስባችኋል።'),
  ('5dd8a879-5799-5d93-a810-ba9bbc0ce667', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 24, 28, 'ከእግዚአብሔር ትርቁ ዘንድ ፈቃዳችሁ እንደ ሆነ እንዲሁ ዐሥር ጊዜ ወደኋላ ተመልሳችሁ ትፈልጉታላችሁ፤'),
  ('8cbbdbf4-cf0c-5a4d-aa44-6408b7e9c301', 'afcd5893-919d-56a0-a857-a44ae3c37348', '010e35ff-f4c4-585a-a8c8-661eec95a05e', 25, 29, 'ይህን መቅሠፍት ያመጣባችሁ እርሱ ዘለዓለማዊ ደስታን ከድኅነታችሁ ጋር ዳግመኛ ያመጣላችኋል።'),
  ('97e19443-0391-521c-aa27-28693e7399ec', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 1, 30, 'ኢየሩሳሌም ተጽናኚ፤ ስም ያወጣልሽ እርሱ ያጽናናሻል።'),
  ('9ea97a49-4278-5a02-adb9-ec7e11f9b6bf', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 2, 31, 'መከራ ያጸኑብሽና በውድቀትሽም ደስ ያላቸው ይጐሰቍላሉ።'),
  ('5b37857a-7e95-578d-a36c-0ac6f51d5201', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 3, 32, 'ልጆችሽን የገዙ፥ ልጆችሽንም ማርከው የወሰዱ ከተሞች ይጐሰቍላሉ።'),
  ('2376fa61-0c99-5e7b-a3c2-1fe36364d359', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 4, 33, 'በጥፋትሽ ደስ እንደ አላት፥ በውድቀትሽም ሐሤት እንደ አደረገች እንዲሁ በራስዋ ጥፋት ታዝናለች።'),
  ('b950b897-82bd-579d-a8b7-c5640eae3947', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 5, 34, 'ብዙ ደስታዋንም ከእርስዋ አስወግዳለሁ፤ ደስታዋም ወደ ኀዘን ይመለሳል።'),
  ('e9860891-18ad-5af7-a8d7-9b546db78943', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 6, 35, 'እሳት ከዘለዓለማዊው አምላክ ለረዥም ዘመን ይመጣባታልና ለብዙ ዘመንም የአጋንንት ማደሪያ ትሆናለችና።'),
  ('aea568de-e2d0-50b3-a328-9d3b6abd2bd8', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 7, 36, 'ኢየሩሳሌም ወደ ምሥራቅ ተመልከች ከአምላክሽ ከእግዚአብሔር የመጣልሽ ደስታንም እዪ።'),
  ('90749018-d18c-5b1c-a5c6-ae11a1a9b498', 'afcd5893-919d-56a0-a857-a44ae3c37348', 'fdb337d0-d3d3-5e20-a6a6-8619f584c132', 8, 37, 'እነሆ የላክሻቸው ልጆችሽ መጡ፤ በቅዱሱም ቃል ከምሥራቅና ምዕራብ ተሰበሰቡ፤ በእግዚአብሔርም ክብር ደስ ይላቸዋል።'),
  ('655d2c27-0be3-541f-a854-bb6740318692', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 1, 1, 'ኢየሩሳሌም ሆይ! የኀዘንሽንና የመከራሽን ልብስ ከአንቺ አውልቂው፤ ለዘለዓለም ከእግዚአብሔር ያገኘሽውን የክብር ጌጥሽንም ልበሺ።'),
  ('a9c18b4e-ff62-5d8a-a0c1-ff5b14221244', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 2, 2, 'ከእግዚአብሔር ዘንድ የጽድቅ መጐናጸፊያሽን ተጐናጸፊ፤ የዘለዓለማዊውን አምላክ የክብር ዘውድሽንም በራስሽ ላይ ተቀዳጂ።'),
  ('b7a0755c-1e34-54d4-a879-90358d827204', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 3, 3, 'እግዚአብሔር ከሰማይ በታች ላሉ ሁሉ ብርሃንሽን ገልጧልና።'),
  ('0d51e3bd-93e9-5471-ab8a-c9a1c7eb17e9', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 4, 4, 'ስምሽም በእግዚአብሔር ዘንድ ለዘለዓለም የጽድቅ ሰላምና እግዚአብሔርን የመፍራት ክብር ተብሎ ይጠራል።'),
  ('39004b21-b9ba-5286-aab9-a6c7590363c4', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 5, 5, 'ኢየሩሳሌም ሆይ! ተነሥተሽ፥ በላይኛውም ቦታ ቁሚ፤ ወደ ምሥራቅም ተመልከቺ፤ ከምዕራብና ከምሥራቅም በቅዱሱ ቃል ልጆችሽ እንደ ተሰበሰቡ እዪ፤ እግዚአብሔርንም በማሰብ ደስ ይላቸዋል።'),
  ('2a102188-44ed-5ff4-a937-21d36295d3a1', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 6, 6, 'ከአንቺም በእግር ወጡ፤ ጠላቶቻቸውም ወሰዷቸው፤ እግዚአብሔር ግን እንደ ንጉሥ ዙፋን በክብር ተሸክመው ወደ አንቺ እንዲያመጧቸው ያደርጋል።'),
  ('df515185-6c0a-5529-a4b9-9d172de77e43', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 7, 7, 'እግዚአብሔርም ረጃጅሞች ተራሮች ሁሉ ዝቅ ይሉ ዘንድ፥ ጐድጓዳውም ሁሉ ይሞላ ዘንድ፥ ምድርም ይስተካከል ዘንድ፥ እስራኤልም በእግዚአብሔር ክብር በጥርጊያው ጐዳና ይሄድ ዘንድ አዘዘ።'),
  ('1ada6936-3556-51e0-a2ff-398c1b919fcd', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 8, 8, 'እስራኤልን በእግዚአብሔር ትእዛዝ ዛፍ ሁሉ፥ በጎ መዓዛ ያለው ዕንጨትም ሁሉ ይጋርዳቸዋልና።'),
  ('93cc261d-8521-5765-a041-9d30b5d9f759', 'a9a414c5-5e40-5637-aaf8-1f9b3a949549', '56b5aba2-85b9-55bc-ac2a-6a29859f47c5', 9, 9, 'እግዚአብሔር እስራኤልን በደስታና፥ በክብሩ ብርሃን፥ በምሕረቱና ከእርሱ በሆነች በጽድቁም ያመጣቸዋልና።'),
  ('be30c0c1-819b-5f48-a0d8-1a0af8ca8827', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 1, 1, 'አሌፍ። ሕዝብ ሞልቶባት የነበረች ከተማ ብቻዋን እንዴት ተቀመጠች!'),
  ('c4a14cc9-2c25-541b-a71e-9de5f2f4d5d9', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 2, 2, 'ቤት። በሌሊት እጅግ ታለቅሳለች፤'),
  ('bbfd000d-4e46-5940-a9a4-b067ceffa9e4', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 3, 3, 'ጋሜል። ይሁዳ ስለ ውርደቷና ስለ ባርነቷ ብዛት ተሰደደች፤'),
  ('74ca8230-9260-5a5a-a9a7-f26440731424', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 4, 4, 'ዳሌጥ። ወደ ዓመት በዓል የሚመጣ የለምና የጽዮን መንገዶች አለቀሱ፤'),
  ('5c3c13c6-aa05-550c-a4c3-f2aa924ac7ab', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 5, 5, 'ሄ። ስለ ኀጢአቷ ብዛት እግዚአብሔር አዋርዶአታልና'),
  ('78afe327-40b5-52fc-aff0-66bbf1105699', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 6, 6, 'ዋው። ከጽዮን ሴት ልጅ ውበት ሁሉ ተወስዶአል፤'),
  ('87241c64-f9db-55c8-a62d-1f3065c73db0', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 7, 7, 'ዛይ። ኢየሩሳሌም ቀድሞ ወድዳ በሠራችው ሥራ ሁሉ የመከራዋን ወራት አሰበች፤'),
  ('eafa3a0d-5a72-5eb5-a725-3ac7d9f8aaf3', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 8, 8, 'ሔት። ኢየሩሳሌም እጅግ ኀጢአት ሠርታለች፤ ስለዚህ ረክሳለች፤'),
  ('812171f5-f46a-5ac0-a83d-564a61db7e95', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 9, 9, 'ጤት። ግዳጅዋ ከእግርዋ በታች ነበረ፤ ፍጻሜዋን አላሰበችም፤'),
  ('c534de23-ef0b-57eb-aa31-f98fb0e83c13', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 10, 10, 'ዮድ። አስጨናቂው በምኞቷ ሁሉ ላይ እጁን ዘረጋ፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f64d0d2f-3dc4-509e-a6fb-122c5b562490', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 11, 11, 'ካፍ። ሕዝብዋ ሁሉ እንጀራ አጥተው ያለቅሳሉ፤'),
  ('2759a85a-409d-59a3-ad55-d9d60f9291cc', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 12, 12, 'ላሜድ። እናንተ መንገድ ዐላፊዎች ሁሉ! በእናንተ ዘንድ ምንም የለምን?'),
  ('e890930c-061e-571f-a63e-49d3c4b3f024', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 13, 13, 'ሜም። ከላይ እሳትን ሰደደ፤ አጥንቶችንም አቃጠለ፤'),
  ('32e1e47e-1fce-5b68-a14d-2d552ba1abe4', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 14, 14, 'ኖን። በእጄ ስለተታቱ ኀጢአቶች ተጋ፤'),
  ('aea91440-eef8-5a83-a2c7-50db615afd97', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 15, 15, 'ሳምኬት። እግዚአብሔር ኀያላኖችን ሁሉ ከመካከሌ አስወገዳቸው፤'),
  ('069ec894-2943-5ded-a27c-2173fb6b3777', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 16, 16, 'ዔ። የሚያጽናናኝ፥ ነፍሴንም የሚመልሳት ከእኔ ርቆአልና ዐይኔ ውኃ ያፈስሳል።'),
  ('86285628-e640-5704-afb2-a4d75a81c63e', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 17, 17, 'ፌ። ጽዮን እጅዋን ዘረጋች፤ የሚያጽናናትም የለም፤'),
  ('4173e942-1f5b-5f4c-a101-adad709d8ff2', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 18, 18, 'ጻዴ። ቃሉን አማርሬአለሁና እግዚአብሔር ጻድቅ ነው።'),
  ('62c3023f-b83c-5016-ac03-40241a9e11d0', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 19, 19, 'ቆፍ። ወዳጆችን ጠራሁ፤ እነርሱም ቸል አሉኝ፤'),
  ('2d523c99-5a58-52bf-a7f6-8d80df02f8af', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 20, 20, 'ሬስ። አቤቱ! ተጨንቄአለሁና፥ አንጀቴም ታውኮብኛልና ተመልከት፤'),
  ('52cdc1ba-ae81-555b-a391-152d1d5436c5', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 21, 21, 'ሣን። እኔ እንደማለቅስ ሰምተዋል፤ የሚያጽናናኝ የለም፤'),
  ('77021260-fd16-5473-a9cd-33c706c289a4', '19f9a648-0d41-5979-ad53-f4234afe1372', '2dff78eb-42e2-5e5a-a434-951a081c5638', 22, 22, 'ታው። ልቅሶዬ እጅግ ነውና፥ ልቤም ደክሞአልና፥'),
  ('864e42dc-5d27-55fd-a74a-4fd10b65e09d', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 1, 1, 'አሌፍ። እግዚአብሔር በቍጣው መቅሠፍት የጽዮንን ሴት ልጅ ምንኛ አጠቈራት!'),
  ('b3536f18-c20b-552f-a3fe-41d869b2e0ce', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 2, 2, 'ቤት። እግዚአብሔር የያዕቆብን መልካም ነገር ሁሉ አሰጠመ፤ አልራራምም፤'),
  ('5a5cedad-d951-52d0-afb1-809f249870f1', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 3, 3, 'ጋሜል። በጽኑ ቍጣው የእስራኤልን ቀንድ ሁሉ ቀጠቀጠ፤'),
