  ('19d32210-1e99-5368-a7c0-703325d84c92', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 5, 5, 'ሄ። እግዚአብሔር እንደ ጠላት ሆነብኝ፤ እስራኤልን አሰጠመ።'),
  ('6e3b9a8d-1ae2-5e1f-abc9-25e23eccc60d', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 6, 6, 'ዋው። ማደሪያውን እንደ ወይን ጋረደ፤ በዓሉን ሁሉ አጠፋ፤'),
  ('a118d2d0-f311-50fe-a431-350c1fb115aa', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 7, 7, 'ዛይ። እግዚአብሔር መሠዊያውን ጣለ፤ መቅደሱንም ጠላው፤'),
  ('a236d0fa-21be-52c7-a572-92dd1dee1cff', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 8, 8, 'ሔት። እግዚአብሔር የጽዮንን ሴት ልጅ ቅጥር ያፈርስ ዘንድ ዐሰበ፤'),
