  ('f60f7e27-4037-5c03-afef-344668030274', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 10, 10, 'ዮድ። የጽዮን ሴት ልጅ ሽማግሌዎች ዝም ብለው በመሬት ላይ ተቀምጠዋል፤'),
  ('f95a4d6f-7f0f-5780-ac66-f86a1fce7882', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 11, 11, 'ካፍ። ሕፃኑና ጡት የሚጠባው በከተማዪቱ ጎዳና ላይ ሲዝሉ፥'),
