  ('31774a53-d041-58a8-a604-5dcf88b327ae', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 21, 21, 'ሣን። ብላቴናውና ሽማግሌው በመንገዶች ላይ ተጋደሙ፤'),
  ('c954c7f7-41a3-5e12-aa9c-c8bc0bcf7c7f', '9615b538-8d32-5541-a864-e9239de842b3', 'b3654825-4cbb-52ff-ad70-8cfeeaf62408', 22, 22, 'ታው። የሚያሳድዱኝን እንደ በዓል ቀን ከዙሪያዬ ጠራ፥'),
