  ('d47888e5-7401-5e6d-a2eb-024465799a9b', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 8, 8, 'በጠራሁና በጮኽሁ ጊዜ ጸሎቴ ተከለከለ።'),
