  ('7c0e859a-0ec7-56ec-ac9c-b6b9d9482c46', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 12, 12, 'ቀስቱን ገተረ፤ ለፍላጻውም እንደ ዒላማ አደረገኝ።'),
  ('0c199cd1-c771-5849-a1c6-86a83822d46d', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 13, 13, 'ሄ። የሰገባውን ፍላጻዎች በኵላሊቴ ውስጥ ተከለ።'),
  ('8cad7296-d192-5633-aef7-299180f40eeb', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 14, 14, 'ለወገኔ ሁሉ መሳቂያ ሆንሁ፤ ቀኑንም ሁሉ ዘፈኑብኝ።'),
  ('0ff51a8e-570c-5e04-a971-0186d14362b9', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 15, 15, 'ምሬትን አጠገበኝ፤ በሐሞትም አሰከረኝ።'),
  ('9676a8b7-e918-5b2a-a5be-88593c26acd5', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 16, 16, 'ዋው። ጥርሴን በጭንጫ ሰበረ፤ አመድም አቃመኝ።'),
  ('47f2fd46-abf9-55a7-a53e-46fb5f177345', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 17, 17, 'ነፍሴን ከሰላም አራቀ፤ በጎ ነገርን ረሳሁ።'),
  ('0731c5cf-6f2d-5241-ae61-041988caa223', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 18, 18, 'እኔም፦ ኀይሌን፥ ከእግዚአብሔርም ዘንድ ያለውን ተስፋዬን አጣሁ።'),
