  ('a3e42195-a0f7-5e54-aecb-7ae88d796751', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 20, 20, 'ነፍሴ እያሰበችው በውስጤ ፈዘዘች።'),
  ('b428d488-4a9b-57a0-a8e0-276af2ec05ec', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 21, 21, 'ይህችን በልቤ አኖራለሁ፤ ስለዚህ እታገሣለሁ።'),
