  ('bd2a9e87-8222-5503-ae7f-555d520a5841', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 23, 23, 'ማለዳ ማለዳ አዲስ ነው፤ ታማኝነትህ ብዙ ነው።'),
