  ('dd0576c4-feae-5737-af67-cff2d5348983', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 25, 25, 'ጤት። እግዚአብሔር ለሚታገሡት ቸር ነው፤'),
