  ('656daab8-36dd-5aa6-aecb-127eb0bca2b8', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 27, 27, 'ሰው በታናሽነቱ ቀንበር ቢሸከም መልካም ነው።'),
  ('ca8e332f-24fe-526b-a108-67a066b4b23f', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 28, 28, 'ዮድ። እርሱ አሸክሞታልና ዝም ብሎ ለብቻው ይቀመጥ።'),
  ('c679f730-41b4-57e5-a582-b7fcdc13ae87', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 29, 29, 'ተስፋ ይሆነው እንደ ሆነ አፉን በአፈር ውስጥ ያኑር።'),
  ('8e07f63c-dc08-5cb4-ae8e-b1b70be95e90', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 30, 30, 'ጕንጩን ለሚመታው ይሰጣል፤ ስድብንም ይጠግባል።'),
  ('68678209-32e7-540b-a612-668a9c1d58b7', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 31, 31, 'ካፍ። ጌታ ለዘለዓለም አይጥልምና፤'),
