  ('9314d8cd-197a-523d-a2a3-e3791bfffbf9', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 33, 33, 'ከልቡ አልተቈጣምና፥ የሰውንም ልጆች አላሳዘነምና፥'),
  ('e745526f-851b-5103-aa8f-78bdeaf133e5', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 34, 34, 'ላሜድ። በምድር የተጋዙትን ሁሉ ከእግሩ በታች ይረግጣቸው ዘንድ፥'),
