  ('a3a1f06b-5b39-5343-a82f-8b6d637817b4', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 37, 37, 'ሜም። “እግዚአብሔር ያላዘዘው ይመጣል፥'),
