  ('9a965e1f-2264-547a-af96-c334ee4e6f4b', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 39, 39, 'ሰው ሕያው ሲሆን ስለ ኀጢአቱ ለምን ያጕረመርማል?'),
