  ('3534f98a-6a5a-577c-a896-5ec1116837f8', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 41, 41, 'ልባችንን ከእጃችን ጋር ወደ እግዚአብሔር ወደ ሰማይ እናንሣ።'),
  ('e7d3a93c-df46-5a24-a288-34d20501cc40', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 42, 42, 'በድለናል፤ ዐምፀናልም፤ አንተም አልራራህልንም።'),
  ('4941acb9-51a4-5177-ae53-21937511b596', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 43, 43, 'ሳምኬት። በቍጣህ ከደንኸን፤ አሳደድኸንም፤ ገደልኸን፤ አልራራህልንም።'),
  ('231cd4aa-9ef9-5e22-ab50-d1fabe701163', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 44, 44, 'ጸሎታችን እንዳያርግ ራስህን በደመና ከደንህ።'),
  ('61933477-1dc9-54f0-ae04-91d0620ef018', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 45, 45, 'እንድናዝንና እንዳናይም በአሕዛብ መካከል አስቀመጥኸን።'),
  ('282acfc0-c8b2-54fd-a224-8ddcdb5d92eb', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 46, 46, 'ዔ። ጠላቶቻችን ሁሉ በእኛ ላይ አፋቸውን ከፈቱ።'),
  ('57efa5e4-0f50-5e3b-a820-1e6caed92958', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 47, 47, 'ፍርሀትና ቍጣ፥ ጥፋትና ቅጥቃጤ ያዘን።'),
