  ('9a4073f7-b40c-554c-a58e-6b478996e0f0', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 49, 49, 'ፌ። ዐይኔ ተደፈነች፤ እንግዲህ ከማንጋጠጥ ዝም አልልም።'),
  ('2d815943-bc2e-5e33-ad11-02620fac8f64', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 50, 50, 'እግዚአብሔር ከሰማይ ሆኖ እስኪመለከት ድረስ።'),
  ('863ca35d-b4c5-5969-a2f1-c1efdc5121a2', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 51, 51, 'ስለ ከተማዬ ቈነጃጅት ሁሉ ዐይኔ ነፍሴን አሳዘነች።'),
  ('c219cdb3-5f09-526f-a58f-5d31254b43bb', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 52, 52, 'ጻዴ። በከንቱ ነገር ጠላቶች ሁሉ እንደ ወፍ ማደንን አደኑኝ።'),
  ('cc41b846-6dd8-54c3-a147-7373f88e967e', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 53, 53, 'ጠላቶች ሕይወቴን በጕድጓድ አጠፉ፤ በላዬም ድንጋይ ገጠሙ።'),
  ('f6565582-32ab-5f30-a5f7-39d8e17e76d8', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 54, 54, 'በራሴ ላይ ውኃ ተከነበለ፤ እኔም፥ “ጠፋሁ” ብዬ ነበር።'),
  ('30d129e1-2eaf-5310-acb5-c9ca4de8e74f', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 55, 55, 'ቆፍ። አቤቱ፥ በጥልቅ ጕድጓድ ውስጥ ሆኜ ስምህን ጠራሁ።'),
  ('7617a54b-e1ef-5afc-a91c-3783b5c35046', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 56, 56, 'አንተ ድምፄን ሰማህ፤ ጆሮህንም ከልመናዬ አትመልስ።'),
  ('db7c4f59-7889-53ac-abc0-2c08a73802d8', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 57, 57, 'በጠራሁህ ቀን ወደ እኔ ቅረብ፤ “አትፍራም” በለኝ።'),
  ('ee7729cf-e70e-5b4d-a3b9-d69a3b578d51', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 58, 58, 'ሬስ። አቤቱ፥ የነፍሴን ፍርድ ፈረድህ፤ ሕይወቴንም ተቤዥህ።'),
  ('be95f14f-2091-5426-a046-801657f6ba3b', '45d5d0ea-1cf0-5bd2-ae77-2b673d97f4aa', '6d55cc19-610c-5dbf-a6cb-5801162fd189', 59, 59, 'አቤቱ፥ ጭንቀቴን አይተሃል፤ ፍርዴን ፍረድልኝ።'),
