  ('bde4dcfc-85b0-50ab-ace1-85dba1acc721', '175177e7-3e4b-50fe-acac-7b2bd2654743', '85c389a7-23de-5f1b-ade1-4a9ac6be7b3b', 18, 18, 'የጽዮን ተራራ ባድማ ሆናለችና፥'),
  ('f51b6fbf-0747-5d33-a613-3e4c5173513f', '175177e7-3e4b-50fe-acac-7b2bd2654743', '85c389a7-23de-5f1b-ade1-4a9ac6be7b3b', 19, 19, 'አቤቱ፥ አንተ ለዘለዓለም ትኖራለህ፤'),
  ('7e21bb71-32f4-5212-a095-cb430859dc24', '175177e7-3e4b-50fe-acac-7b2bd2654743', '85c389a7-23de-5f1b-ade1-4a9ac6be7b3b', 20, 20, 'ስለ ምን ለዘለዓለም ትረሳናለህ?'),
  ('1a198bd8-6e7f-5c79-a798-b4f088d45b0b', '175177e7-3e4b-50fe-acac-7b2bd2654743', '85c389a7-23de-5f1b-ade1-4a9ac6be7b3b', 21, 21, 'አቤቱ፥ ወደ አንተ መልሰን፤ እኛም እንመለሳለን፤'),
  ('027be9c9-62e8-5e57-afde-851edec875d7', '175177e7-3e4b-50fe-acac-7b2bd2654743', '85c389a7-23de-5f1b-ade1-4a9ac6be7b3b', 22, 22, 'ፈጽመህ ጥለኸናልና፤'),
  ('48cd4a8c-7461-542d-ac61-533cadb4815b', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 1, 1, 'እግዚአብሔር ያዘዘውን ይነግሯቸው ዘንድ የባቢሎን ንጉሥ ማርኮ ወደ ባቢሎን ወደ ወሰዳቸው ሰዎች ኤርምያስ የላከው መጽሐፍ ግልባጭ ይህ ነው።'),
  ('1a68510b-9f51-5007-a124-c546e995d8fc', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 2, 2, 'እግዚአብሔርን ስለ በደላችሁበት ኀጢአታችሁ የባቢሎን ንጉሥ ናቡከደነፆር ምርኮኞች አድርጎ ወደ ባቢሎን ይወስዳችኋል።'),
  ('e0727741-0105-510d-afbe-b6343fa35b5a', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 3, 3, 'እንዲሁም ወደ ባቢሎን ገብታችሁ እስከ ሰባተኛ ትውልድ ለብዙ ዓመታት፥ ለረዥም ወራትም በዚያ ትኖራላችሁ። ከዚህ በኋላ ግን ከዚያ ቦታ በሰላም አወጣችኋለሁ።'),
  ('6b6fb2b3-7bf2-5e34-ae95-a7a6b7b686d2', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 4, 4, 'አሁን ግን የብርና የወርቅ፥ የእንጨትም የሆኑ ጣዖቶችን በባቢሎን ታያላችሁ ፤ በጫንቃቸውም ይሸከሟቸዋል፤ አሕዛብንም ያስፈሯቸዋል።'),
  ('54056cfa-2b6e-59d3-a152-c2e7664a4831', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 5, 5, 'እንግዲህ እንደ ሌሎች እንዳትሆኑ ተጠንቀቁ፤ ስለ እነርሱም ፍርሀት አይደርባችሁ።'),
  ('ed0a70b8-1df3-5b04-ad2a-a39f8199d47d', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 6, 6, 'በፊታቸውና በኋላቸው ሆነው ሲሰግዱላቸው አሕዛብን ብታዩ፥ በልባችሁ፥ “አቤቱ ስግደት ለአንተ ይገባል” በሉ።'),
  ('a225064c-9511-5f9a-af0c-b402216eea19', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 7, 7, 'መልአኬ ከእናንተ ጋር ይኖራልና፥ ለሰውነታችሁም ይጠነቀቃልና።'),
  ('21a4a16b-1e8a-50e5-a76a-1ddec8b52c3d', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 8, 8, 'ጃንሸላሚ የሠራው አንደበት አላቸው፤ ይኸውም የወርቅና የብር ነው፤ እነርሱም ሐሰት ናቸው፤ መናገርም አይችሉም።'),
  ('d7a89d34-5664-5b83-a84c-1212388c529e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 9, 9, 'ጌጥ ለምትወድ ድንግል እንደሚያደርጉ ወርቅን ወስደው፥ በጣዖቶቻቸው ራስ ላይ አክሊል አደረጉ።'),
  ('e9eafff2-5c6b-52e8-a41a-a8a61a043972', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 10, 10, 'ከእነርሱም ካህናቱ ወርቁንና ብሩን እየወሰዱ ለመፍቅዳቸው የሚያውሉበት ጊዜ ነበረ።'),
  ('ad832ab6-7b83-5a09-a1f7-5ed901251511', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 11, 11, 'ከእርሱም በቤታቸው ለነበሩ አመንዝራዎች ይሰጧቸው ነበር። የብር፥ የወርቅና የእንጨት ጣዖቶቻቸውንም እንደ ሰው በልብስ ያስጌጧቸው ነበር።'),
  ('25080400-cfff-5b9f-a316-b5f4e1e6bab8', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 12, 12, 'ዝገታቸውንም ከራሳቸው አያርቁም ነበር።'),
  ('df13271b-a527-51d1-a679-2c583792d161', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 13, 13, 'በነጭ ሐር ይሸፍኗቸው ነበር፤ በላያቸውም እጅግ ብዙ ከሆነው የቤት ትቢያ የተነሣ ይወለውሏቸው ነበር።'),
  ('beed14f6-6a88-5163-adb3-e5ff8e9b0f62', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 14, 14, 'እንደ ፈራጅ ሰውም በትር ያስይዟቸዋል፤ ነገር ግን የሚገፋቸውን አይበቀሉትም።'),
  ('6edd3678-3f7d-586b-a222-b29f8cbb42db', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 15, 15, 'በእጁ ሰይፍና ምሳር አለ፤ ራሱንም ከጦርነትና ከሌቦች አያድንም፤'),
  ('b0cc1819-70b0-52fa-a8d4-4092f4aea66e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 16, 16, 'አማልክትም እንዳይደሉ በዚህ ይታወቃሉ፤ እንግዲህ አትፍሩአቸው።'),
  ('79a094d2-9200-598e-a888-715210e94d69', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 17, 17, 'የተሰበረ የሸክላ ዕቃ እንደማይጠቅም ጣዖቶቻቸው እንዲሁ ናቸው። በቤትም ይቸነክሯቸዋል፤ ከሚገባውም የሰው እግር የተነሣ ትቢያ በዐይናቸው ይሞላል።'),
  ('908da0dd-0e63-5a79-aa7d-d773480965d4', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 18, 18, 'ንጉሥን በበደለ ሰው ላይ በሮች እንደሚዘጉበት፥ በመቃብር ውስጥ ያለ ሟችም እንደሚዘጋበት እንዲሁ ሌቦች እንዳይሠርቋቸው ካህናቶቻቸው በመዝጊያና በቅWልፍ ይጠብቋቸዋል።'),
  ('092d8c70-1325-5a86-a813-6cedc9f4c412', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 19, 19, 'መብራት ያበሩላቸዋል፤ የሚያዩትም የለም።'),
  ('859847d1-00d1-5836-aaf3-222ada11dbf1', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 20, 20, 'በቤት ውስጥ እንዳለ ምሰሶ ናቸው፤ የሆድ ዕቃቸውን የምድር አራዊት እንደሚበሏቸው ይናገራሉ፤ እነርሱንና ልብሳቸውን ሲበሏቸው እነርሱ አያውቁም።'),
  ('59e50392-28f8-52df-ab28-b7f61836c18e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 21, 21, 'በቤተ ጣዖቱ ከሚጤሰው ጢስ የተነሣ ፊታቸው ይጠቍራል።'),
  ('0d904761-f110-5be9-a606-64a47fb46d40', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 22, 22, 'በአካላቸውና በራሳቸውም ላይ የሌሊት ወፍ፥ ወፎችና ድመት ይቀመጣሉ።'),
  ('9e3e0b23-d6fe-5e0f-a075-26efe2f7ab82', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 23, 23, 'በዚህም እነርሱ አማልክት እንዳይደሉ ታውቃላችሁ፤ እንግዲህ ወዲህ አትፍሩአቸው።'),
  ('1b0b2f01-2d29-5be0-a27e-438a76e1e0ea', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 24, 24, 'ወርቅ ቢያስቀምጡት ካልወለወሉት እንደማያበራ አያበሩም፤ ቀጥቅጠው ሲሠሯቸውም አያውቁም።'),
  ('24cfa365-f883-5343-a5d3-fb5658dd72b2', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 25, 25, 'በከፍተኛ ዋጋ ገዟቸው፤ ነገር ግን እስትንፋስ የላቸውም።'),
  ('c7c3447c-122e-5126-aa2e-0d57bd4c56fe', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 26, 26, 'እግር የላቸውም፤ ድካማቸውም ይታወቅ ዘንድ በትከሻቸው ይሸከሟቸዋል፤'),
  ('e642097a-e0b5-56ff-ad41-772bbc1d0f4a', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 27, 27, 'የሚያመልኳቸው ያፍራሉ፤ በምድርም ላይ ቢወድቁ ራሳቸው አይነሡም፤ ቢያነሡአቸውም ራሳቸው አይቆሙም፤ ቢያዘነብሉም ራሳቸው በራሳቸው ቀጥ አይሉም፤ ለእነርሱም መሥዋዕት ማቅረብ ለሞተ ሰው ምግብ እንደ ማቅረብ ነው።'),
  ('d483f3aa-bd05-5ded-a2c7-78087808fe88', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 28, 28, 'ካህናቶቻቸውም መሥዋዕታቸውን እየሸጡ ያቃልሏቸዋል። እንደዚሁም ሚስቶቻቸው መሥዋዕቱን ያጣፍጣሉ፤ ነገር ግን ከእርሱ ለበሽተኛና ለድሃ አይሰጡም።'),
  ('21987a84-7424-503c-af5e-ca1d5a9f50f8', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 29, 29, 'አራሶችና የተዳደፉ ሴቶችም ከመሥዋዕቱ ይነካሉ፤ በዚህም አማልክት እንዳይደሉ ዕወቁ፤ እንግዲህ አትፍሩአቸው።'),
  ('25c34619-669b-5857-adc1-6afbeb632ee0', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 30, 30, 'ሴቶች ከብር ከወርቅና ከእንጨት ለተሠሩ አማልክት መሥዋዕት ካቀረቡላቸው በምን አማልክት ይባላሉ?'),
  ('55263f2c-2c51-58fa-a465-f99546f3a15d', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 31, 31, 'ካህናቶቻቸውም በጣዖታቱ ቤት ያድራሉ፤ ልብሳቸው የተቀደደ ነው፤ ራሳቸውም ጢማቸውም የተላጨ ነው፤ ራሳቸውም ግልጥ ነው።'),
  ('f130c77d-8baf-5293-a7ae-e5c498a3eb60', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 32, 32, 'በሙት መታሰቢያ ላይ እንደሚደረግ በአማልክቶቻቸው ፊት እየጮኹ ያለቅሳሉ።'),
  ('275251ed-b978-52a4-a2cc-ac215227c193', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 33, 33, 'ካህናቶቻቸውም ልብሶቻቸውን ገፍፈው ለሚስቶቻቸውና ለልጆቻቸው ያለብሳሉ።'),
  ('602104e8-d735-5cc5-a013-6fad2e2d416c', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 34, 34, 'ክፉ ያደረገባቸው፥ ወይም መልካምን ያደረገላቸው ሰው ቢኖር ብድራቱን አይከፍሉትም፤ አያነግሡም፤ አይሽሩምም።'),
  ('22828b16-7c94-5eff-afc3-f2f07678cf63', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 35, 35, 'እንዲሁም አያበለጽጉም፤ አያደኸዩምም፤ ስእለት ተስሎ ያልሰጠ ቢኖርም አይፈላለጉትም።'),
  ('bed715a8-ce92-52f5-a25f-86b33f1bd5e5', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 36, 36, 'ሰውን ከሞት አያድኑም፤ ደካማውንም ከኀይለኛው አያድኑም።'),
  ('5f7513f2-5f47-524a-a1d2-dbe7c9bdc32a', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 37, 37, 'ዕውር አያበሩም፤ ሰውን ከችግሩ አያነሡትም።'),
  ('1368d316-6ab9-507a-aa5b-fa7fd0009950', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 38, 38, 'ለመበለቶች አይራሩም፤ ለድሃ-አደጉም በጎ አያደርጉም።'),
  ('cf963993-14ec-57df-a6d6-b212c60203f4', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 39, 39, 'አማልክቶቻቸው ከተራራ የተፈነቀሉ ድንጋዮችን ይመስላሉ፤ ከእንጨት፥ ከወርቅና ከብር የተቀረፁ ናቸው። የሚያመልኳቸውም ያፍራሉ።'),
  ('7431d7b2-f7d7-5c60-a8f1-60fc6bbeca48', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 40, 40, 'በምን ይመሰላሉ? ከለዳውያን ራሳቸው ሲንቋቸው እንግዲህ እንዴት አማልክት ይባላሉ?'),
  ('7a057528-d2a4-5bb6-a521-7307f489294b', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 41, 41, 'እነዚህ መናገር የማይችል ዲዳን ባዩ ጊዜ እርሱ መስማት እንደሚችል ይናገር ዘንድ እየለመኑት ወደ ቤል ያመጡታል።'),
  ('beeec7b6-f5ae-51ae-a63d-673f871bd12d', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 42, 42, 'መስማትን እንደማይችሉ የሚያውቁ እነዚያም ሊያርቋቸው አይችሉም።'),
  ('a5941ce4-d192-5d3c-ade7-68f6cf33a136', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 43, 43, 'ሴቶችም ወገባቸውን በመቀነት ታጥቀው በመንገድ ይቀመጣሉ፤ የእህል ቍርባንም ያቀርባሉ።'),
  ('67236dcb-e32c-5721-a1d8-d2557a9f3384', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 44, 44, 'ከእነርሱም አንዲቱ መንገድ ዐላፊውን ብታስተውና አብራው ብትተኛ፥ እንደ እርስዋ ዝግጁ ሆና አልተገኘችምና፥ መቀነቷም አልተፈታላትምና ይህችኛዋ ሌላዋን ትነቅፋታለች። ለእነርሱ የሚደረገው ሁሉ ሐሰት ነው፤ እንደ አማልክት ሊቈጥሯቸው፥ አማልክትም ሊሉአቸው እንዴት ይቻላል?'),
  ('a2e5e56c-c816-5560-a900-b264eec79a1f', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 45, 45, 'ጠራቢዎችና አንጥረኞች ሠርተዋቸዋል፤ እነዚህም ጠራቢዎች ከፈቀዱት ውጭ አልሆኑም።'),
  ('7257c83c-187a-5e94-a7a2-9a89b12e8ffd', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 46, 46, 'የሠሯቸው አንጥረኞች ራሳቸውም ለብዙ ዘመን አይኖሩም። እንግዲህ በእነርሱ የተሠሩ እነዚህ እንዴት ለዘለዓለም ይኖራሉ?'),
  ('6b41e895-e479-5e4d-a16e-4254d64b029f', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 47, 47, 'በኋላ ለሚመጡም ከንቱነትንና ስድብን ተዉ።'),
  ('903111ed-ea68-5074-a71b-3b42904d70fb', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 48, 48, 'ጦርነትና ጥፋት በመጣባቸው ጊዜ ካህናቶቻቸው ከእነርሱ ጋር ይሸሸጉ ዘንድ እርስ በርሳቸው ይመካከራሉ።'),
  ('abaaccd8-69e4-51ab-ab01-80fde8b4972e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 49, 49, 'እንግዲህ ራሳቸውን ከጦርነትና ከጥፋት የማያድኑ እንዴት አማልክት ናቸው?'),
  ('2e9d858c-8a82-55aa-a06a-801726de6220', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 50, 50, 'እነርሱ በወርቅና በብር የተለበጡ እንጨቶች ናቸውና፤ በኋላም ከንቱ መሆናቸው ይታወቃል።'),
  ('14e13a87-0796-5fba-a3d5-495d0c33ee31', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 51, 51, 'እነርሱም የሰው እጅ ሥራ እንጂ አማልክት እንዳልሆኑ፥ የአምላክነት ሥራም እንደሌላቸው ለአሕዛብና ለነገሥታት ሁሉ በግልጥ ይታወቃሉ።'),
  ('0c02c9c4-e68c-51d9-ae02-f4f50c3c50e6', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 52, 52, 'አማልክት እንዳይደሉ የማያውቅ ማን ነው?'),
  ('94d29d62-2f68-58d0-a802-5a521b7d5a29', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 53, 53, 'በሀገር ላይ ንጉሥን አያስነሡም፤ ለሰውም ዝናምን አይሰጡም።'),
  ('01f38de7-2d14-5b05-a9bc-aa0c1b03221d', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 54, 54, 'ለራሳቸው ፍርድን አይፈርዱም፤ ግፍንም አያርቁም፤ ምንም ማድረግ አይችሉምና፥ በሰማይና በምድር መካከል እንደሚበርሩ ቍራዎች ናቸው።'),
  ('104457bd-cfee-5fb5-a9b9-b613cf6ea8ba', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 55, 55, 'ከእንጨት፥ ወይም ከወርቅ፥ ወይም ከብር የተሠሩ ጣዖታት ቤት ቢቃጠል፥ ካህናቶቻቸው ሸሽተው ራሳቸውን ያድናሉ፤ እነርሱ ግን እንደ ምሰሶ በመካከል ይቃጠላሉ።'),
  ('8518fce5-ce3b-5cbd-a080-930fba8fe76e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 56, 56, 'ንጉሥንም ቢሆን፥ ጠላትንም ቢሆን አይቃወሙም፤ እንግዲህ እንዴት አማልክት ናቸው?'),
  ('68757690-756e-56dd-a499-7267f9d21cfb', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 57, 57, 'ከእንጨት፥ ከብርና ከወርቅ የተሠሩት ጣዖታት ከሌቦችና ከቀማኞች ራሳቸውን አያድኑም።'),
  ('c5547f89-940a-5f50-a4d6-4681a59ad4e9', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 58, 58, 'የሚበረታቱባቸውም ወርቃቸውንና ብራቸውን፥ የተሸፈኑበትንም ልብሶች ይገፉአቸዋል፤ ይዘውም ይሄዳሉ፤ እነርሱ ግን ራሳቸውን እንኳ አይረዱም።'),
  ('3d813ff4-7fa8-54fd-a8ea-4f536986f856', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 59, 59, 'ስለዚህ ከሐሰት አማልክት ይልቅ በኀይሉ የሚመካ ንጉሥ፥ ወይም በቤት ውስጥ የሚጠቅም፥ የገዛውም የሚገለገልበት ሸክላ ይሻላል፤ ወይም በቤት ውስጥ ያለውን ሁሉ የሚያድን መዝጊያ ከሐሰት አማልክት ይልቅ ይሻላል፤ በነገሥታት አዳራሽ ውስጥ ያሉ የእንጨት ምሰሶዎችም ከሐሰት አማልክት ይልቅ ይሻላሉ።'),
  ('f70fb84b-2d50-584f-ac52-aa9c8c2ce457', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 60, 60, 'ፀሐይና ጨረቃ፥ ከዋክብትም ብርሃን ናቸውና፥ ለጥቅምም ይላካሉና ይታዘዛሉ።'),
  ('f0960080-af17-5204-ac9d-0bc6d6deddf7', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 61, 61, 'እንደዚሁም መብረቅ በሚበርቅበት ጊዜ ከሩቅ ይታያል፤ እንደዚሁም ነፋስ በሀገሩ ሁሉ ይነፍሳል።'),
  ('ad2fb56c-7301-58a6-a477-4394877d2540', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 62, 62, 'ደማናትም በዓለሙ ሁሉ ይገለባበጡ ዘንድ ከእግዚአብሔር ታዝዘዋልና ትእዛዛቸውን ይፈጽማሉ።'),
  ('76ec8bd1-05fb-519b-a646-bcbb22f13bee', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 63, 63, 'ተራሮችንና ዛፎችን ያቃጥል ዘንድ ከላይ የተላከ እሳትም የታዘዘውን ይፈጽማል፤ እነዚያ ግን በመልካቸውም፥ በኀይላቸውም እነዚህን አይመሳሰሉአቸውም።'),
  ('878ab2ef-f09e-5a27-a80c-c6b6443156e1', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 64, 64, 'ስለዚህ እንደ አማልክት አይቈጠሩም፤ አማልክትም አይባሉም፤ ለሰው ፍርድ ማድረግን ወይም መልካም ማድረግን አይችሉምና።'),
  ('0e62f800-2f99-509d-a4a7-60beb283199f', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 65, 65, 'አማልክት እንዳይደሉ እንዲህ ዐውቃችኋቸዋልና አትፍሯቸው።'),
  ('253f09ce-a4a3-549a-a8d9-464137a00cde', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 66, 66, 'ነገሥታትን አይረግሙም፤ አይመርቁምም።'),
  ('09c9af53-2920-576d-a11f-5861a40e0e2c', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 67, 67, 'በሰማይም ለአሕዛብ ምልክትን አያሳዩም፤ እንደ ፀሐይና ጨረቃም አያበሩም።'),
  ('bb55cd72-bc14-56a8-a377-d9ac36bc3f53', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 68, 68, 'ከእነዚህ ይልቅ ወደ መጠጊያ መሸሽ የሚችሉና ራሳቸውን የሚያድኑ አራዊት ይሻላሉ።'),
  ('6e604b32-dabe-58c7-a47f-b528f0e20610', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 69, 69, 'አማልክት እንደ ሆኑ በማናቸውም መንገድ እንደዚህ አልተገለጠልንምና ስለዚህ አትፍሩአቸው።'),
  ('5f21d873-f0da-59a6-ac87-85f262dfa8bd', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 70, 70, 'በዱባ እርሻ ውስጥ ከአለ ማስፈራሪያ ምንም ምን እንደማይጠበቅ ከእንጨት የተሠሩና በወርቅና በብር የተለበጡ ጣዖቶቻቸው እንደዚሁ ናቸው።'),
  ('341fcd4d-b98f-5afb-ab61-345d826962ac', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 71, 71, 'እንዲሁም በላዩ አዕዋፍ የሚቀመጡበትን፥ በአትክልት ቦታ ውስጥ ያለ ነጭ እሾህን ይመስላሉ፤ ከእንጨት የተሠሩ፥ በብርና በወርቅ የተለበጡ ጣዖቶቻቸው እንዲሁ በጨለማ ውስጥ እንደ ተጣለ በድን ናቸው።'),
  ('a89fa00f-9d06-5521-a491-b3cdca9f22bf', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 72, 72, 'በላያቸው ከሚያረጁት ከቀይ ሐር ልብስና ከቀጭን ልብስ የተነሣ አማልክት እንዳይደሉ ታውቃላችሁ፤ በኋላም እነርሱ ራሳቸው ይጠፋሉ፤ ለሀገርም መሰደቢያ ይሆናሉ፤'),
  ('732e7747-032f-5204-ab1a-c5fff7c6283e', '080684a0-e372-518e-aa74-d74dd4e8cdfd', '87b340ae-ec0c-5f35-adf0-c8b6bb48a70b', 73, 73, 'ስለዚህ ጣዖት የሌለው፥ ከስድብም የራቀ ሰው ይሻላል።'),
  ('ddb1b953-af66-5216-a6c9-c9c8ff59507e', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 1, 1, 'ኤርምያስም ጳስኮርን እንዲህ አለው፥ “እናንተስ በዘመናችሁ ሁሉ ከአባቶቻችሁና ከእናንተ በኋላ ከሚመጡ ልጆቻችሁ ጋር ጽድቅን ትቃረኗታላችሁ።'),
  ('ab97ef02-2227-58e4-a227-acc2c6c0f2ce', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 2, 2, 'እነርሱስ ከአባቶቻችሁ ይልቅ እጅግ የተናቀች ኀጢአትን ሠሩ። እነርሱም ዋጋ የማይገኝለትን ይሸጡታል፤ ሕማማትን የሚያስወግደውን እንዲታመም ያደርጉታል፤ ኀጢአትን የሚያስተሰርየውንም ይፈርዱበታል።'),
  ('401ea341-c955-589e-a010-1c7747434f37', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 3, 3, 'የእስራኤል ልጆች የተስማሙበትን የክቡሩን ዋጋ ሠላሳ ብር ይቀበላሉ፤ ያንም ብር ለሸክላ ሠሪ ቦታ ዋጋ አድርገው ይሰጡታል።'),
  ('baebbfda-1380-5fad-afd1-dc328fb66b1a', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 4, 4, 'እዚአብሔርም እንዳዘዘኝ እንዲሁ እናገራለሁ።'),
  ('56b8ccea-ac1c-54cc-a29c-b389a5754b4a', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 5, 5, 'ስለዚህ ንጹሕ ደምን ፈርደው አፍስሰዋልና ፍርድና ጥፋት በእነርሱ ላይ፥ ከእነርሱም በኋላ በልጆቻቸው ላይ ይወርድባቸዋል፤”'),
  ('57d3c740-2689-5422-a8f7-4218d062067c', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 6, 6, 'ወደ ባቢሎን በተማረኩ ጊዜ ስውር ያልሆነ ባሮክ ከተናገረው ነገር የቀረ ይህ ነው።'),
  ('afd48e4f-9fbb-567e-a7e3-d12418f3e0d7', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 7, 7, 'እንዲህም ሆነ፤ የከለዳውያን ንጉሥ የእስራኤልን ልጆች በማረካቸው ጊዜ እግዚአብሔር ኤርምያስን ተናገረው።'),
  ('c155fadc-bdb0-5356-a477-f6a82432e2d0', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 8, 8, 'እንዲህም አለው፥ “ወዳጄ ኤርምያስ ሆይ፥ ከዚህች ከተማ ውጣ፤ ከሚኖሩባት ሰዎች ኀጢአት ብዛት የተነሣ አጠፋታለሁና አንተና ባሮክ ውጡ።'),
  ('4c096e84-104e-5f6f-a46c-1727cc536fbb', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 9, 9, 'ልመናህ በከተማዪቱ መካከል እንደ ጽኑ ምሰሶ፥ በዙሪያዋም እንደ አድማስ ቅጥር ነውና፤ አሁንም የከለዳውያን ሠራዊት ሳይመጣና ሀገሪቱን ሳይከባት ተነሥታችሁ ሂዱ፥ ውጡም።”'),
  ('3bd91378-201d-5aed-a66b-82c8bc638485', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 10, 10, 'ኤርምያስም እንዲህ ሲል ተናገረ፥ “ጌታዬ ሆይ፥ እለምንሃለሁ፤ በፊትህ ይናገር ዘንድ ባሪያህን እዘዘው።”'),
  ('54cc6108-0b70-55e7-a355-a70fdf630ebf', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 11, 11, 'እግዚአብሔርም፥ “ወዳጄ ኤርምያስ ሆይ! ተናገር” አለው።'),
  ('e26f81a5-0664-5522-ae04-228e28885e24', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 12, 12, 'ኤርምያስም እንዲህ ሲል ተናገረ፥ “ሁሉን የምትገዛ አቤቱ፥ ንጉሡ ከሠራዊቱ ጋር ይታበይና በአምላክ ከተማ በረታሁባት ይል ዘንድ የመረጥኻትን ይህቺን ከተማ በከለዳውያን እጅ አሳልፈህ ትሰጣለህን?'),
  ('89a763f3-d649-5e9a-a165-d3a4cd7d2b16', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 13, 13, 'አቤቱ፥ ይህ አይሁን፤ ከወደድህም በእጅህ አጥፋት።”'),
  ('d63b8ea9-2121-54f4-a25e-9998ef63c05c', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 14, 14, 'እግዚአብሔርም ኤርምያስን አለው፥ “በሚኖሩባት ሰዎች ኀጢአት አጠፋታለሁና አንተ ወዳጄ ስለ ሆንህ ባሮክና አንተ ተነሥታችሁ ውጡ።'),
  ('7ce365f6-dbc0-5872-ab9e-1531e8acf7e3', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 15, 15, 'እኔ አስቀድሜ በሮችዋን ካልከፈትሁ ንጉሡና ሠራዊቱ ወደ ሀገሪቱ መግባት አይቻላቸውም።'),
  ('26acc7f7-fac3-5554-ae44-f1a583b584cd', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 16, 16, 'አሁንም ተነሥተህ ወደ ባሮክ ሂድ፤ ይህንም ነገር ሁሉ ንገረው፤ ከሌሊቱ ስድስት ሰዓት በሆነ ጊዜ ተነሥታችሁ ወደ ከተማዪቱ ቅጥር ኑ።'),
  ('0b32546a-2297-5412-a95d-72119f02d5d9', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 17, 17, 'እኔ አሳያችኋለሁ፤ እኔም አስቀድሜ ከተማዪቱን ካላጠፋኋት ወደ እርስዋ መግባት አይችሉም።”'),
  ('2332c6d5-af32-5da9-a1b8-7ff3c5449202', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 18, 18, 'ጌታም ይህን ተናግሮ ከኤርምያስ ዘንድ ሄደ።'),
  ('cd356e48-3d5a-5c6d-a3d0-0991c9b59ee4', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 19, 19, 'ያንጊዜም ኤርምያስ ልብሱን ቀደደ፤ በራሱም ላይ ትቢያ ነሰነሰ፤ ወደ ቤተ መቅደስም ገባ።'),
  ('30f78890-8623-5f79-a385-cbc7e46f2d45', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 20, 20, 'ባሮክም ኤርምያስን በራሱ ላይ ትቢያ ነስንሶ፥ ልብሶቹንም ቀድዶ ባየው ጊዜ፥ “አባቴ ኤርምያስ ሆይ፥ ምን ሆንህ? ሕዝቡስ ምን ኀጢአት ሠሩ?” ብሎ ቃሉን አሰምቶ ጮኸ።'),
  ('899af7ce-9220-58a1-adf4-178d31bf52c0', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 21, 21, 'ሕዝቡ በሳቱ ጊዜ ኤርምያስ ያዝን ነበርና፥ በራሱም ትቢያ ይነሰንስ ነበርና፥ የሕዝቡም በደላቸው እስኪሰረይላቸው ድረስ ለሕዝቡ ይጸልይላቸው ነበርና።'),
  ('c6ddfa9b-8759-57ce-a2ed-2b0acb5958c2', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 22, 22, 'ባሮክም፥ “አባቴ ኤርምያስ ሆይ፥ ምን ሆንህ?” ብሎ ጠየቀው። ኤርምያስም እንዲህ አለው፥ “ልቡናችንን እንቅደድ እንጂ ልብሶቻችንን እንዳንቀድ ተጠበቅ” አለው።'),
  ('ba79c157-70e1-56e9-acb1-75310adae3b3', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 23, 23, '“ከዛሬ ጀምሮ እነዚህን ወገኖች ይቅር አይሏቸውምና እንባን እስክንመላቸው ድረስ በሚገባ እናለቅስ ዘንድ ወደ ጕድጓዶች ውኃን አንጨምር” አለው።'),
  ('677521e4-8417-511a-ab83-c1382e5ffe86', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 24, 24, 'ባሮክም፥ “አባቴ ኤርምያስ ሆይ፥ ምን ሆንህ?” አለ።'),
  ('e91f2615-76b9-5009-a062-56feff750cb5', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 25, 25, 'ኤርምያስም፥ “አምላክ ከተማዋን በከላውዴዎን ንጉሥ እጅ አሳልፎ ይሰጣታልና፥ ሕዝቡንም በክፉ ነገር ይማርካቸዋልና ነው፤” አለው።'),
  ('a2bbc583-639f-594b-a4ef-de0f191188cf', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 26, 26, 'ባሮክም ይህን ሁሉ ነገር ሰምቶ ልብሶቹን ቀደደና፥ “አባቴ ኤርምያስ ሆይ፥ ምን ላኩብህ?” አለው።'),
  ('8c1141df-f9e0-5b6d-af19-70f1f893cf76', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 27, 27, 'ኤርምያስም፥ “ነገሩን በእውነት ታውቅ ዘንድ ከሌሊቱ እስከ ስድስት ሰዓት ድረስ ከእኔ ጋር ቈይ” አለው።'),
  ('162b7986-fd79-5730-a525-b6ad9eaea482', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 28, 28, 'በቤተ መቅደስም እያለቀሱ ተቀመጡ፤ ከሌሊቱም ስድስት ሰዓት በሆነ ጊዜ እግዚአብሔር ኤርምያስን ይወጣ ዘንድ ነገረው።'),
  ('f8caff78-4855-564f-a898-a75fd2791ea0', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 29, 29, 'ከባሮክም ጋር ወጣ፤ ወደ ቅጽሩም ደረሱ፤ እየጸለዩም ተቀመጡ።'),
  ('a514386c-511b-5725-a9ca-05f959d7d050', 'b5a2aed1-4e53-5e73-a01e-64c288d4d171', 'bae32114-4159-5b6c-ae06-c6047e79bca5', 30, 30, 'የመለከት ድምፅም ተሰማ፤ መላእክትም ከሰማያት መጡ፤ በእጃቸውም የእሳት መብራት ይዘው በቅጥሯ ቆመው ነበር።'),
  ('a4308ba4-33c6-5bd2-a29e-fb8a0c5b2ad0', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 1, 1, 'ያንጊዜም ኤርምያስና ባሮክ፥ “የዚህ ነገር ምልክት በእውነት እንደ ተገኘ ዛሬ ዐወቅን” ብለው አለቀሱ።'),
  ('5d43a0a6-281d-5a91-a5cb-d67677aa70d6', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 2, 2, 'ኤርምያስም፥ “እግዚአብሔርን አንዲት ነገርን እስክለምነው ድረስ ከተማዋን ሁሉ እንዳታጠፉ እለምናችኋለሁ” ብሎ መላእክትን ማለዳቸው።'),
  ('36753070-a316-5f4e-aaaa-055f11b8eece', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 3, 3, 'ጌታም፥ “ከወዳጄ ከኤርምያስ ጋራ እስክነጋገር ድረስ ከተማዪቱን አታጥፉ” ብሎ ለመላእክት ነገራቸው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('36d02ef3-9976-5add-aa7b-728a1249c654', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 4, 4, 'ኤርምያስም ያንጊዜ፥ “ጌታዬ ሆይ፥ እለምንሃለሁ፤ ከአንተ ጋር እናገር ዘንድ እዘዘኝ” ብሎ ተናገረ፤ ጌታም፥ “ወዳጄ ኤርምያስ ሆይ፥ የምትወድደውን ተናገር” አለው።'),
  ('cf77bd26-0467-585e-a215-3d0f096cf64b', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 5, 5, 'ኤርምያስም እንዲህ አለው፥ “አቤቱ ጌታዬ፥ ይቺን ከተማ በጠላትዋ እጅ አሳልፈህ እንደምትሰጣት የባቢሎንም ሕዝብ እንደሚይዟት እነሆ፥ ዛሬ ዐወቅሁ።'),
  ('929876bd-19c8-52c1-a757-e42c776b1357', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 6, 6, 'ተሰውረን ስለምናገለግልባቸው ንዋያተ ቅድሳት ምን አደርግ ዘንድ ትወድዳለህ? በላያቸውስ ምን አደርግ ዘንድ ትወድዳለህ?”'),
  ('45b90b10-f128-5493-a031-a35299665eac', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 7, 7, 'ጌታም አለው፥ “እነርሱን ወስደህ ለምድር አደራ ስጣት፤ አንቺ ምድር በውኆች ላይ የፈጠረሽ፥ በሰባቱም ማኅተም ያተመሽ የፈጣሪሽ የእግዚአብሔርን ቃል ሰምተሽ ጌጥሽን ተቀበዪ፤ ተወዳጁም እስኪመጣ ድረስ ገንዘብሽን ጠብቂ በላት።”'),
  ('35967799-1bc1-53ba-acdc-0d52cb8280b4', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 8, 8, 'ኤርምያስም እንዲህ ሲል ተናገረ፥ “ጌታዬ ሆይ፥ እለምንሃለሁ፤ ሕዝቡን ብዙ ዘመን ለጠበቃቸው፥ እኔን ባሪያህ ኤርምያስንም ከሀገሩ ሰው ሁሉ ይልቅ ለጠበቀኝ ለኢትዮጵያዊው ለአቤሜሌክ የማደርገውን ግለጥልኝ።'),
  ('512e4e3c-f7e2-50b2-a010-3192f65b9e88', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 9, 9, 'እርሱ ከረግረግ ጕድጓድ አወጣኝ፤ እንዳያዝን የከተማዋን ጥፋት ያይ ዘንድ አልወድለትም።”'),
  ('abf077bd-08a8-5c7a-abef-623255e121e2', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 10, 10, 'ጌታም ለኤርምያስ እንዲህ አለው፥ “ወደ አግሪጳስ ወይን ቦታ በዚህ ተራራ ጎዳና አቤሜሌክን ላከው፤ ሕዝቡን ወደ ሀገራቸው እስክመልሳቸው ድረስ እኔ እሰውረዋለሁ።'),
  ('e8e48075-a433-5804-afbe-f0c830e63fcc', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 11, 11, 'አንተም ኤርምያስ ወደ ባቢሎን ሀገር እስክትደርስ ድረስ ከሕዝቡ ጋራ ወደ ግብፅ ሂድ፤ ወደ ሀገራቸውም እስክመልሳቸው ድረስ ስታስተምራቸው ኑር።'),
  ('6f7e8635-d961-5fad-ace7-122478b8eb73', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 12, 12, 'ባሮክን ግን በዚያ በኢየሩሳሌም ተወው፤” ጌታም ይህን ሁሉ ነገር ለኤርምያስ ነግሮት ከኤርምያስ ዘንድ ወደ ሰማይ አልፎ ወጣ።'),
  ('b4eae6d0-ccce-5157-a99c-24ed390aed5f', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 13, 13, 'ባሮክና ኤርምያስም ወደ ቤተ መቅደስ ገቡ፤ የሚያገለግሉበትንም ዕቃ ሁሉ ጌታ እንዳዘዛቸው ለምድር ሰጧት፤ ምድርም ያንጊዜ ተቀብላ ዋጠችው።'),
  ('7b2249ba-f9e0-5b38-a4c8-c40413f9486f', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 14, 14, 'ሁለቱም ሁሉ ተቀምጠው አለቀሱ፤ በማግሥቱም በነጋ ጊዜ ኤርምያስ አቤሜሌክን፥ “ሙዳዩን ይዘህ ወደ አግሪጳስ የወይን ቦታ በተራራው ጎዳና ሂድ፤ የእግዚአብሔር ረድኤት፥ ጌትነቱም በአንተ ራስ አድሯልና ለታመሙ ወገኖች ጥቂት በለስን አምጣ” ብሎ ላከው።'),
  ('b540646e-6f7c-5981-acdd-5d5e1566c224', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 15, 15, 'እርሱም እንዳዘዘው ሄደ፤ በማግሥቱም በነጋ ጊዜ የከለዳውያን ሠራዊት ከተማዪቱን ከበቧት፤ ታላቁም መልአክ መለከቱን ነፋ።'),
  ('69895445-04d9-5cc5-a806-36b7b9cb6ce9', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 16, 16, 'እርሱም፥ “የከለዳውያን ሠራዊት፥ ግቡ፤ እነሆ፥ በሮቹ ይከፈቱላችኋል” አለ።'),
  ('6e0efaf5-617e-5c6b-a49c-b15bf7004b0d', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 17, 17, 'ያንጊዜም ንጉሡ ከሠራዊቱ ጋር ገብቶ ሕዝቡን ሁሉ ማረከ።'),
  ('c01de737-ffef-56c6-aa94-f9b24312e9d7', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 18, 18, 'ያንጊዜም ኤርምያስ የቤተ መቅደሱን መክፈቻ ይዞ ከከተማ ወደ ውጭ ወጣ።'),
  ('7a328c54-0827-52cb-a98d-79a1859fa2f9', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 19, 19, 'ይህንም መክፈቻ “ፀሐይ፥ የእግዚአብሔርን ቤት መክፈቻ ተቀበል” ብሎ በፀሐይ ፊት ጣለው።'),
  ('1f557daa-7b83-58ec-affa-463758ee0fb8', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 20, 20, '“ኀጢአታችንን እኛ እየተከባከብናት ስለ ተገኘን ከተወለድን ጀምሮ እርሱን ለመጠበቅ አይገባንምና እግዚአብሔር የእርሱን ነገር እስከሚነግርህ እስከ ብዙ ዘመን ድረስ ጠብቀው” አለው።'),
  ('d36698cb-1edc-57bf-a954-f58d887c89dd', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 21, 21, 'ኤርምያስም ለወገኖቹ ሲያለቅስ እያዳፉ አወጡት፤ ከሕዝቡም ጋር እስከ ባቢሎን ድረስ ወሰዱት።'),
  ('f8490333-59d7-532a-a567-aeef4cb13428', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 22, 22, 'ባሮክ ግን አመድ ዘግኖ በራሱ ላይ ነሰነሰ፤ ተቀምጦም አለቀሰ፤ ይህንም ሙሾ አሞሸ። እንዲህም አለ፦'),
  ('2f8285d4-70ba-5c40-a9eb-d5268fb4a28e', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 23, 23, '“ስለ ተወደደ ስለ ሕዝቡ ኀጢአት ነው እንጂ ኢየሩሳሌም ስለ ምን ጠፋች?'),
  ('8c74ba46-f489-5c82-a2dc-b6a416003474', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 24, 24, 'ኃጥኣን እንዳይታበዩ፥ የአምላክንም ከተማ በኀይላችን መያዝ ተቻለን እንዳይሉ በሕዝቡ ኀጢአትና በእኛ ኀጢአት በጠላቶችዋ እጅ ወደቀች እንጂ በእነርሱ ኀይል አይደለም።'),
  ('96f0f22c-3e0a-5522-a6a7-7e2d555ee5bf', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 25, 25, 'በእኛ ኀጢአት ለእናንተ ተሰጠቻችሁ እንጂ ይቺን ከተማ መያዝ የተቻላችሁ በእናንተ ጽናት አይደለም።'),
  ('fdcde8b4-66b6-5fe4-ab35-806fedc4835e', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 26, 26, 'አምላካችንም ያዝንልናል፤ ወደ ሀገራችንም ይመልሰናል፤ ለእናንተ ግን ድኅነት የላችሁም።'),
  ('846b5268-9d4b-596b-ac84-51a6d6bda1a4', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 27, 27, 'ከዚህ ዓለም ተለይተው ሄደዋልና፥ የዚችንም ከተማ ጥፋት አላዩምና አባቶቻችን አብርሃምና ይስሐቅ ያዕቆብም ብፁዓን ናቸው።”'),
  ('9d7ce2a4-88d5-5c54-af0c-0873f3ae6dea', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 28, 28, 'ይህንም ከተናገረ በኋላ እያለቀሰ ወጣ፤ “ኢየሩሳሌም ሆይ፥ ስለ አንቺ ኀዘንን አዝናለሁ” አለ።'),
  ('2a131844-2bc6-5a22-a3eb-8e5ffd8df0de', 'e3887ee3-744d-5a0d-a46f-0d78fb6f2825', '2e0fc21e-77f8-53e9-aa44-78caa95df709', 29, 29, 'ከከተማውም ወጥቶ በመቃብር ቤት አደረ፤ መላእክትም እየመጡ ሁሉን ይነግሩት ነበር።'),
  ('0737296f-dfbb-559a-abbf-9f7b218c4139', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 1, 1, 'አቤሜሌክም ኤርምያስ ከላከው ቦታ በቀትር ጊዜ በለሱን አመጣ፤ ጽፍቅ ያለች ዱርንም አገኘ፤ ጥቂትም ያርፍ ዘንድ በጥላዋ ስር ተቀመጠ፤ በለስ ያለባትንም ሙዳይ ተንተርሶ ስድሳ ስድስት ዓመት ተኛ፤ ከመኝታውም አልነቃም።'),
  ('50c08343-abe4-58fb-a144-cfe32bb010e3', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 2, 2, 'ከዚያም ዘመን በኋላ ከመኝታው ነቅቶ ተነሣ፤ “ገና ራሴን ይከብደኛልና፥ እንቅልፌንም አልጨረስሁምና ዳግመኛ ጥቂት ልተኛ” አለ።'),
  ('6b036361-7dce-55a4-a485-c4d4b4ce0368', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 3, 3, 'ያንም የበለሱን ሙዳይ ከፈተ፤ በለሶችም አዲስ ሆነው፥ ወተታቸውም ሲፈስስ አገኘ፤ ራሱንም ከብዶት ነበርና እንቅልፉንም አልጨረሰምና ይተኛ ዘንድ ወደደ።'),
  ('113e69f3-d64f-54d8-abdf-0eb11888b515', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 4, 4, 'እንዲህም አለ፥ “ተመልሼ እንዳልተኛ እንዳልዘገይም እፈራለሁ፤ አባቴ ኤርምያስ ተግቶ በጧት ልኮኛልና እንዳይቈጣኝ እፈራለሁ።'),
  ('db0391b4-e726-56c8-a1c2-1ef1d6604e81', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 5, 5, 'ሙቀት ሆኗልና፥ በሁሉም የሚተውበት ጊዜ የለምና አሁን ተነሥቼ እሄዳለሁ።”'),
  ('1c495391-0649-5b81-a1b1-ed8133de9f6e', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 6, 6, 'ተነሥቶም የበለሱን ሙዳይ ይዞ ወደ ኢየሩሳሌም ከተማ ገባ። ከተማውንም ቤቱንም አላወቀም።'),
  ('76f7ff4c-92b0-5df0-a80f-d9815d6d9287', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 7, 7, 'ጽኑ ድንጋጤ መጥቶበታልና “አቤቱ፥ አንተ የተመሰገንህ ነህ” አለ።'),
  ('e0c3039f-a4da-56e5-a58f-3e9b8275e880', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 8, 8, 'እንዲህም አለ፥ “ይህቺ ከተማ ኢየሩሳሌም አይደለችምን? በተራራው ጎዳና መጥቻለሁና፥ ራሴንም ከብዶኛልና፥ እንቅልፌንም አልጨረስሁምና አእምሮዬን ዘንግቼ ምናልባት ተስቶኝ ይሆን?'),
  ('c0ddbdae-cc2d-5adb-a72f-c1ebbd603920', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 9, 9, 'ከተማዪቱ ባዕድ እንደ ሆነችብኝ በኤርምያስ ዘንድ ይህን ነገር እንዴት እናገራለሁ?” ኢየሩሳሌምም እንደ ሆነች በከተማው ያለውን ምልክት ሁሉ ፈለገ።'),
  ('d4c2b360-c87b-5246-a27d-b982bc592c1e', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 10, 10, 'ዳግመኛም ወደ ከተማ ተመለሰ፤ የሚያውቀውም እንዳለ ፈለገ፤ ነገር ግን አላገኘም፤ “ታላቅ ድንጋጤ በእኔ መጥቶብኛልና አቤቱ፥ አንተ የተመሰገንህ ነህ” አለ።'),
  ('79685fc4-a422-5b2b-a337-688ff92a129d', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 11, 11, 'ሁለተኛም ከከተማ ርቆ ወጣ፤ እያዘነም ተቀመጠ፤ ሲሄድም አያውቅም ነበር፤ የበለሱንም ሙዳይ አኖረ፤ “ይህን ድንቁርና እግዚአብሔር ከእኔ እስኪያርቅልኝ ድረስ በዚህ እቀመጣለሁ” አለ።'),
  ('1752d9d3-095a-50e7-a9eb-dc615651a999', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 12, 12, 'ከዚህ በኋላ ተቀምጦ ሳለ አንድ ሽማግሌ ሰው ከምድረ በዳ ሲመለስ አየ።'),
  ('e8c3c289-b051-57d3-aeb7-91fe52496f28', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 13, 13, 'አቤሜሌክም እንዲህ አለ፥ “አንተ ሽማግሌ፥ ይቺ ከተማ ማን ናት? ብዬ እጠይቅሃለሁ።”'),
  ('cd8769e9-067f-5d62-a1b5-3e11d2f3fe21', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 14, 14, 'ያም ሽማግሌ፥ “ኢየሩሳሌም ናት” አለው፤ “ያገኘሁት ሰው የለምና የእግዚአብሔር ካህን ኤርምያስ ወዴት አለ? ሌዋዊው ባሮክና የከተማው ሕዝብ ሁሉስ ወዴት አሉ?” አለው፤'),
  ('9702eb7d-06c8-5957-a86e-4a28530300d6', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 15, 15, 'ሽማግሌውም እንዲህ አለው፥ “አንተ ከዚች ከተማ አይደለህምን? ይህን ያህል ዘመን ኖረህ የእርሱን ነገር ትጠይቅ ዘንድ ኤርምያስን ዛሬ ማን ዐሰበው?'),
  ('063d3294-4b5a-5bad-a153-5435290cc2ff', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 16, 16, 'ተማርኮ በባቢሎን ንጉሥ በናቡከደነፆር እጅ ተሰጥቶአልና፤ እስራኤልንም ያስተምር ዘንድ ወደ ባቢሎን ሄዶአልና ኤርምያስስ ከሕዝቡ ጋር በባቢሎን አለ።”'),
  ('25503f55-534a-5bd5-aa53-d6e1f873c97e', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 17, 17, 'አቤሜሌክም ያንጊዜ ከዚያ ከሽማግሌው ይህን ቃል ሰማ።'),
  ('97a25f47-64bd-5b6a-a946-bf83aa0e0a55', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 18, 18, 'አቤሜሌክም እንዲህ አለው፥ “ሰውን፥ ይልቁንም ሽማግሌውን ሰው ሊንቁት አይገባም እንጂ አንተ ሽማግሌ ሰው ባትሆን በሰደብሁህ ነበር፤ በአንተም በዘበትሁብህ ነበር፤ ያም ባይሆን አእምሮውን ያጣ ሽማግሌ ብዬ በሰደብሁህ ነበር።'),
  ('fac95272-0fda-5414-a730-abb4f4254a95', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 19, 19, 'ሕዝቡ ተማርከው ወደ ባቢሎን ሄዱ፤ ስለምትለውስ ነገር የሰማይ ሻሻቴ እንኳ በእነርሱ ላይ ቢወርድ ወደ ባቢሎን ተማርከው ይሄዱ ዘንድ ጊዜው አይደለም።'),
  ('643b000a-bf29-5460-a9c0-49d3e9e879fa', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 20, 20, 'አንተ ግን ተማርከው ወደ ባቢሎን ሄዱ ትላለህ፤ በሕዝቡ ዘንድ ላሉ ለበሽተኞች እንሰጥ ዘንድ አባቴ ኤርምያስ እኔን እንደ ላከኝ ጥቂት በለስ ላመጣ ወደ አግሪጳስ ወይን ቦታ ሄድሁ።'),
  ('4e50fae6-683d-5305-aafa-518ceacab4a5', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 21, 21, 'ሄጄም ከዚያ ደረስሁ፤ ያዘዘኝንም ይዤ ተመለስሁ፤ ስሄድም አንዲት ዛፍ አገኘሁ፤ የቀትር ጊዜ ነበርና በበታችዋ ዐርፍ ዘንድ ተቀመጥሁ።'),
  ('43ba9d2f-7163-5245-af16-cbbba5f3fbf1', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 22, 22, 'ከዚያም የበለሱን ሙዳይ ተንተርሼ ተኛሁ፤ ከእንቅልፌም በነቃሁ ጊዜ የዘገየሁ መሰለኝ፤ የበለሱንም ሙዳይ ከፍቼ አየሁ፤ መርጬ እንደለቀምኋቸው ወተቱ ሲፈስስ አገኘሁት።'),
  ('27857935-a8db-5fab-ab82-ee0ad8796a49', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 23, 23, 'እነሆ፥ አንተ ሕዝቡ ተማርከው ወደ ባቢሎን ሄዱ ትላለህ፤ እነሆ፥ በለሱ እንዳልጠወለገ እይ” ብሎ የበለሱን ሙዳይ ከፍቶ አሳየው።'),
  ('74d02284-6c21-5000-a4cf-c7deec9459dc', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 24, 24, 'ሽማግሌውም በለሱ አዲስ እንደ ሆነ፥ ወተቱም እንደሚፈስስ አየ፤ ያንጊዜም ሽማግሌው አደነቀ።'),
  ('d6683ef6-1ea7-5e68-a3f2-c623bea35025', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 25, 25, 'አቤሜሌክንም እንዲህ አለው፥ “ልጄ፥ አንተ ደግ ሰው ነህ፤ ፈጣሪህ የዚህችን ከተማ ጥፋት ሊያሳይህ አልወደደምና አምላክ ለአንተ መረጋጋትን አምጥቶ አድኖሃል።'),
  ('8a01b4c7-9606-5ae3-af5c-07dfd7a57bb5', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 26, 26, 'እነሆ፥ ሕዝቡ ወደ ባቢሎን ተማርከው ከሄዱ ዛሬ ስድሳ ስድስት ዓመት ሆነ።'),
  ('df63bcb1-79d6-53e3-a4f3-c0e906e6f971', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 27, 27, 'ልጄ፥ ፈጽመህ ልታውቅስ ከወደድህ ዘሮችዋ እንደ በቀሉ ወደ እርሻዎች ፈጽመህ ተመልከት፤ የበለስም ጊዜው አይደለም፤” ያንጊዜ አቤሜሌክ የዚህ ሁሉ ጊዜው እንዳልሆነ ዐወቀ።'),
  ('dd1890ce-0778-5ce9-a0e2-3b530d26b418', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 28, 28, 'ቃሉንም አሰምቶ፥ “የሰማይና የምድር አምላክ፥ በሀገሩ ሁሉ ያሉ የጻድቃን ነፍሳት ዕረፍታቸው የሆንህ ጌታዬና አምላኬ ሆይ፥ አመሰግንሃለሁ፥” አለ።'),
  ('4423779b-4da7-5feb-ad70-892efe9683d5', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 29, 29, 'ሽማግሌውንም፥ “ይህ ወር ምንድን ነው?” አለው፤ እርሱም፦ የኔሳን ወር ዐሥራ ሁለተኛው ቀን፥ ይኸውም ሚያዝያ ነው” አለው።'),
  ('02906a69-f755-551c-a670-3fc7672180ff', 'bb589758-af5d-5f60-a3bb-2626e6d79f50', '244ed84d-67d0-5b6d-acca-33ee8cd901da', 30, 30, 'ከዚህም በኋላ አቤሜሌክ ለዚህ ሽማግሌ ከበለሶቹ ሰጠው፤ እርሱም፥ “አምላክ ወደ ሰማያዊት ሀገር ወደ ኢየሩሳሌም ይምራህ” አለው።'),
  ('65615da5-2b18-5d5b-af07-9be140fbf0de', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 1, 1, 'አቤሜሌክም ተነሥቶ ከከተማ ወደ ውጭ ከወጣ በኋላ ወደ እግዚአብሔር ጸለየ።'),
  ('c58c4d83-776d-51cd-a895-4d4dbb5cb573', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 2, 2, 'እነሆም፥ መልአክ መጥቶ ወደ ባሮክ መራው፤ በመቃብር ቤትም ተቀምጦ አገኘው።'),
  ('1ecb23a6-f081-5730-ac35-b055e3304198', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 3, 3, 'ሰላምታም በተሰጣጡ ጊዜ እርስ በርሳቸው ተለቃቅሰው ተሳሳሙ፤ በሙዳዩም ውስጥ በለሱን አይቶ ዐይኖቹን ወደ ሰማይ አቀና።'),
  ('03f37541-d68c-50e2-a45c-6c5a53fc291c', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 4, 4, 'እንዲህም ብሎ ጸለየ፤ “ለወዳጆቹ ለጻድቃን ዋጋቸውን የሚሰጣቸው አምላክ ገናና ነው፤ ነፍሴ ሆይ፥ ተዘጋጂ፤ ለቅዱስ ማደሪያሽ ለሥጋ ይህን እየነገርሽ ደስ ይበልሽ፤ ልቅሶሽም ወደ ደስታ ይመለስልሻል።'),
  ('048124f1-7417-5970-a573-e34fff366211', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 5, 5, 'ከዚያም በኋላ የታመነው ይመጣል፤ ወደ ሬሳሽም ይመልስሻል፤ ድንግል ወደ ሆነው ወደ ሃይማኖትሽም ተመልከች።'),
  ('9a57a070-ba8b-5b86-a332-051dc204b7ff', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 6, 6, 'እንደምትነሺም ወደ እነዚህ በለሶች ተመልከች፤ ከተለቀሙ ስድሳ ስድስት ዓመት ነው፤ አልደረቁም፤ አልተሉምም፤ ነገር ግን ወተታቸው እስከ ዛሬ ገና ይፈስሳል።'),
  ('27120274-e657-5785-abfe-fc32c2c554de', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 7, 7, 'ኀጢአት የለብሽምና፥ የበለሱን ሙዳይ ከጠበቀ ከእውነተኛው መልአክም ዘንድ የታዘዝሺውን ትእዛዝ ጠብቀሻልና ሥጋዬ በአንቺ እንዲህ ያደርጋል፤ እርሱም ዳግመኛ በኀይሉ ይጠብቅሻል።”'),
  ('4e19f3c2-4449-5410-a5bc-094573f4fcce', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 8, 8, 'ባሮክም እንዲህ ብሎ ከጸለየ በኋላ አቤሜሌክ መለሰ፤ “እኔን የሰወረ እግዚአብሔር ለኤርምያስ ወደ ባቢሎን የምንጽፋቸውን ቃሎች ይገልጥልን ዘንድ ዳግመኛ ተነሥተህ ጸልይ” አለው።'),
  ('4ebf47f4-e447-5a25-ab0f-5137641be626', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 9, 9, 'ባሮክም ጸለየ፤ እንዲህም አለ፥ “ኀያል አምላክ፥ ብርሃንም ከአፍህ የሚወጣ ጌታ ሆይ፥ እለምንህ ዘንድ እወድዳለሁ፤'),
  ('2a56e127-4c34-55c5-ac77-ca3aed8f858a', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 10, 10, 'ለቸርነትህም እገዛለሁ፤ ስምህም ገናና ነው፤ እርሱንም መርምሮ ማወቅ የሚቻለው የለም።'),
  ('14dbd04d-ef4f-5ba1-a247-b171d2f86e51', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 11, 11, 'በልቡናዬ ፈቃድህን ለማድረግ በደግነት የታወቅሁ እሆን ዘንድ፥ ለአገልጋይህ ለኤርምያስም ወደ ባቢሎን ጽፌ እልክ ዘንድ የኔን የባሪያህን ልመና ስማ።”'),
  ('cc0fd047-7870-52cb-aee1-69cc4ca69e41', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 12, 12, 'ይህንም ሲጸልይ መልአኩ መጥቶ ለባሮክ እንዲህ አለው፥ “ብሩህ ነገርን የምትመክር ባሮክ ሆይ፥ አንተ ወደ ኤርምያስ ትልክ ዘንድ ማንን እልካለሁ? ብለህ አታስብ።'),
  ('e5bd6da7-4161-5c05-a199-7b6abe8a58c2', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 13, 13, 'ነገ ፀሐይ ሲወጣ ንስር ወደ አንተ ይመጣል፤ ወደ ኤርምያስም የምትልከውን ነገር አንተ መርምር፤ በመጽሐፍም ጻፍ።”'),
  ('9d018b44-6d71-592b-aa4d-8092eb8ec4e1', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 14, 14, 'የእስራኤልን ልጆች እንዲህ በላቸው፥ “በእናንተ ዘንድ እንግዳ ሰው ቢኖር እስከ ዐሥራ አምስት ቀን ድረስ ከእናንተ ይለይ።'),
  ('8adba904-0db3-59fe-a300-768851a93d65', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 15, 15, 'ከዚህም በኋላ ወደ ሀገራችሁ አገባችኋለሁ ይላል እግዚአብሔር፤ እስከ ዐሥራ አምስት ቀንም ድረስ ከባቢሎን ያልተለየ ሰው ቢኖር ኤርምያስ ወደ ከተማ ገብቶ በባቢሎን ያሉ እስራኤልን ይዝለፋቸው፤ ይላል እግዚአብሔር።”'),
  ('ad25f4f9-6da1-55e1-a20a-678e8367a257', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 16, 16, 'ይህንም ከተናገረ በኋላ መልአኩ ከባሮክ ዘንድ ሄደ። ባሮክም እስከ አደባባዩ ድረስ ሸኘው፤ ወረቀትና ጥቁር ቀለምም አመጣ።'),
  ('1a195f23-ec30-5c88-a617-c4a43d40b30e', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 17, 17, 'የእግዚአብሔር አገልጋዩ ባሮክ እንዲህ ብሎ ደብዳቤ ጻፈ፥ “ስለ ስድባችንና ስለ ጥፋታችን ያዘንን ሆነን እንወጣ ዘንድ ፈጣሪያችን አልተወንምና ወደ ባቢሎን ለተማረከው ለኤርምያስ ደስታና ሐሤት ይሁን።'),
  ('d34df6af-8b76-52dc-aa58-15203bea465e', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 18, 18, 'ስለዚህ ነገር ጌታችን እንባችንን አይቶ አዘነልን፤ አስቀድሞ ለአባቶቻችን ለአብርሃምና ለይስሐቅ፥ ለያዕቆብም ያጸናውን ቃል ኪዳን ዐሰበ።'),
  ('f63b55d0-85d2-5ee0-abf3-989085bc722a', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 19, 19, 'መልአኩንም ወደ እኔ ልኮ ወደ አንተ የላክሁብህን ነገሮች ነገረኝ።'),
  ('fe248349-9932-5731-a482-e0a3a434acfc', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 20, 20, '“ከግብፅ ምድርና ከእሳት ቤቶች ያወጣን የእስራኤል አምላክ እግዚአብሔር ያደረጋቸው ነገሮች እኒህ ናቸው፤ ልቡናችሁን ከፍ ከፍ አደረጋችሁ፤ በፊቱም አንገታችሁን አደነደናችሁ እንጂ ሕጉን ሁሉ አልጠበቃችሁምና።'),
  ('38ae580f-4e50-5786-a83b-ed2850c468fc', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 21, 21, 'እግዚአብሔር ከወዳጄ ከኤርምያስ አፍ ቃሌን አልሰማችሁም ብሏልና ለባቢሎን አገዛዝ አሳልፎ ሰጣችሁ፤ ቃሌን የሰሙ ሰዎችን ግን ከባቢሎን አወጣቸዋለሁ፤ ከባቢሎንም ወጥተው በኢየሩሳሌም እንግዳ አይሆኑም።'),
  ('5f5e971a-4193-5631-ac5b-09215f0b81e9', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 22, 22, 'መንገዳቸውንም ልታውቅባቸው ብትወድድ በዮርዳኖስ ውኃ ፈትናቸው፤ የዚህን ደብዳቤ ምልክት ያልሰማ ሰው ግን የበለጠ ምልክት ማኅተም አለ።”'),
  ('6ac297e0-a566-5b75-a43d-9a3d437d4e49', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 23, 23, 'ባሮክም እንዲህ ጽፎ ከመቃብር ቤት ወጣ፤ ንስሩም፥ “ሃይማኖትን የምታስተምር ባሮክ ሆይ፥ ቸር አለህን?” አለው።'),
  ('83bfb3ed-d978-5add-a101-6f295f32f87a', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 24, 24, 'ባሮክም፥ “ከሰማይ አዕዋፍ ሁሉ የተመረጥህ ነህና፥ በዐይኖችህም ብርሃን የታወቅህ ነህና ትናገራለህ።'),
  ('3956a0e4-196d-5dd0-a757-d8d198d204f7', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 25, 25, 'አሁንም በዚህ ምን ልታደርግ መጣህ? ንገረኝ” አለው። ንስሩም፥ “የወደድኸውን ሁሉ ልትልከኝ ወደዚህ መጣሁ” አለው።'),
  ('3147909d-f988-5c87-a857-6ea397525c65', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 26, 26, 'ባሮክም፥ “እነዚህን ነገሮች ለኤርምያስ ወደ ባቢሎን ማድረስ ትችላለህን?” አለው፤ ንስሩም፥ “ስለዚህ ተላክሁ” አለው።'),
  ('f53c6aed-a754-5071-a4ec-871a40111406', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 27, 27, 'ባሮክም ደብዳቤውን ያዘ፤ ከዚያ አቤሜሌክ ከሰጠው ከበለሱ ሙዳይም ዐሥራ አምስቱን በለስ አምጥቶ በንስሩ አንገት አሰረ።'),
  ('e8a66a98-8058-5f13-a20c-7d6652b3c5e7', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 28, 28, '“የአዕዋፍ ሁሉ ንጉሣቸው ንስር ሆይ፥ በሰላምና በደኅና ሂደህ ወሬያቸውን አምጣልን እልሃለሁ አለው።'),
  ('f267a558-62a1-5de5-a302-2e42d687db65', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 29, 29, 'ኖኅ የላከውን፥ ዳግመኛም ወደ እርሱ መመለስን እንቢ ያለውን ቁራ አትምሰለው። ነገር ግን ለኖኅ ቃሏን ሦስት ጊዜ የመለሰች ርግብን ምሰላት።'),
  ('66cd704e-9bf1-5991-a7ed-50ae68b7f7bf', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 30, 30, 'እንደዚሁም ሁሉ ለአንተ በጎ ነገር ይሆንህ ዘንድ እኒህን ያማሩ ነገሮች ለኤርምያስና ከእርሱ ጋራ ላሉ እስራኤል ውሰድ፤ አምላክ ለመረጣቸው ወገኖች ይህን ደስታ ንገራቸው።'),
  ('d5db1d32-783b-56bb-a7b7-e964048025cd', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 31, 31, 'አዕዋፍም ሁሉ ቢከብቡህ፥ ይገድሉህም ዘንድ ወድደው የጽድቅ ጠላቶች ሁሉ ቢከብቡህ ስለ እውነት ቀድመሃቸው ሂድ።'),
  ('bd5c4d3b-6a25-538c-a729-cfc0cb2196d9', '483fdd1f-4f08-58c9-a3c4-ee595404d0fb', 'd83fb930-1e17-504c-ae24-9d65f63b8978', 32, 32, 'ጌታም ኀይልን ይሰጥሃል፤ የተወረወረ ፍላጻ ቀንቶ እንዲሄድ አንተም በፈጣሪህ ኀይል ቀንተህ ሂድ እንጂ ወደ ቀኝም ወደ ግራም አትበል” አለው።'),
  ('0ea6664d-d3b8-551f-a2a5-9949a666a465', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 1, 1, 'ባሮክም ይህን ከተናገረ በኋላ ንስሩ ደብዳቤውን ይዞ በረረ፤ ወደ ባቢሎንም ሄዶ በምድረ በዳ ባለው ቦታ ከከተማ ውጭ ባለ ዛፍ ላይ ዐረፈ።'),
  ('7cb190a8-2cc3-5048-af12-479042ba0480', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 2, 2, 'ኤርምያስ እስኪያልፍ ድረስ ሌሎችም ወገኖች እስኪያልፉ ድረስ በዚያው ቈየ፤ ኤርምያስም ናቡከደነፆርን ከወገኖች የሞተውን የምቀብርበት ቦታ ስጠኝ ብሎ ለምኗልና፥ እርሱም ሰጥቶታልና ሕዝቡ የሞተውን ሰው ሊቀብሩ በዚያ በኩል ዐለፉ።'),
  ('6d40c2bf-6867-50d7-a93f-7d84a00549b1', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 3, 3, 'ለሞተውም ሰው እያለቀሱ ሲሄዱ ከንስሩ ፊት ደረሱ።'),
  ('a578ab1d-c656-5344-afb4-4b69bdc7b265', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 4, 4, 'ንስሩም በዚያ ቦታ ሆኖ በታላቅ ቃል አሰምቶ ጮኸ፤ “አምላክ የመረጠህ ኤርምያስ ሆይ፥ ለአንተ እነግርሃለሁ፤ ሄደህ ሕዝቡን ሁሉ ሰብስባቸው፤ እኔ ያመጣሁትን መልካም የምሥራች እስኪሰሙ ድረስ ወደዚህ ይምጡ” አለው።'),
  ('66987124-0e7c-5299-a219-f96f647a7389', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 5, 5, 'ኤርምያስም ይህን ሰምቶ እግዚአብሔርን አመሰገነው፤ ያንጊዜም ሕዝቡን ሁሉ ሚስቶቻቸውንም፥ ልጆቻቸውንም ሰበሰበ፤ እነርሱም ንስሩ ወዳለበት ደረሱ።'),
  ('e944bd06-9413-5bb1-a283-5873d2aa84a2', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 6, 6, 'ንስሩም ሬሳው ወዳለበት ወርዶ ረገጠው፤ ሙቱም ተነሣ፤ ይህንም ያደረገ ስለ ተደረገላቸው ተአምራት ሕዝቡ ሁሉ ያምኑና ያደንቁ ዘንድ ነው።'),
  ('51ee3e5b-99ed-5624-a975-01bffbe4681c', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 7, 7, 'እነርሱም፥ “ከሙሴ ጋር በምድረ በዳ ሳሉ ለአባቶቻችን የታያቸው አምላካችን እነሆ፥ ይህ ነው፤ ዛሬም በታላቅ ንስር አምሳል ለእኛ የታየን እርሱ ነው” አሉ።'),
  ('470fb66a-5470-5145-a210-5f829a3f63b2', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 8, 8, 'ንስሩም ኤርምያስን እንዲህ አለው፥ “መጥተህ ይህን ደብዳቤ ከፍተህ ለሕዝቡ አንብብላቸው።” እርሱም ለሕዝቡ አነበበላቸው።'),
  ('eeac1440-6be0-511a-ac5f-d93e80c1bd78', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 9, 9, 'ሕዝቡም በሰሙ ጊዜ ሁሉም አንድ ሆነው አለቀሱ፤ በራሳቸውም ላይ አመድ ነሰነሱ፤ ኤርምያስንም፥ “ወደ ሀገራችን እንገባ ዘንድ ምን እናድርግ? ንገረን” አሉት።'),
  ('fc01d305-b1e0-5e3b-a447-710e96fc230e', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 10, 10, 'ኤርምያስም ተነሥቶ፥ “በደብዳቤ የሰማችሁትን ሁሉ እንደዚሁ አድርጉ ወደ ሀገራችሁም ይመልሳችኋል” አላቸው።'),
  ('74d02d35-4b7e-58f8-ab11-6818c19689cb', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 11, 11, 'ኤርምያስም ለባሮክ እንዲህ ብሎ ደብዳቤ ጻፈ፥ “ልጄ ወዳጄ፥ በኀጢአተኛ ንጉሥ ትእዛዝ እስክንወጣ ድረስ ይቅር ይለን ዘንድ፥ ወደ ጎዳናችንም ይመራን ዘንድ ለአምላካችን እየተገዛህ ስለ እኛ መጸለይን ቸል አትበል።'),
  ('6f7749a3-9c48-5979-a9c1-b161043c7bbe', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 12, 12, 'አንተ ግን ወደ ባቢሎን ተማርከው ከመጡ ወገኖች ጋር ልትመጣ ባልተወህ በአምላክ ፊት ባለሟልነትን አገኘህ።'),
  ('240c1fa3-09d1-54ba-ab83-267cc6e6d190', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 13, 13, 'አንድ ልጅ እንዳለው አባት፥ ልጁም ይፈረድበት ዘንድ እንደ ተሰጠ፥ የሚያረጋጉት በአባቱ ዘንድ ያሉት ሰዎችም አባቱ በኀዘን ሲጐሰቍል እንዳያዩት ፊታቸውን እንደሚሸፍኑ፥'),
  ('43a7136f-8d87-57c2-aedd-2c3cfd7fcbb4', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 14, 14, 'እንደዚሁ አምላክህ አንተን ይቅር አለህ፤ እኛም ወደዚህ ሀገር ከደረስን ጀምሮ እስከ ዛሬ ከኀዘን አላረፍንምና የሕዝቡን መከራ እንዳታይ ወደ ባቢሎን ትመጣ ዘንድ አልተወህም። ወደዚህ ሀገር ከመጣን ጀምሮ ለስድሳ ስድስት ዓመታት ከኀዘን አላረፍንም።'),
  ('be448527-565c-50f1-abdb-c02bfe6d86fc', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 15, 15, 'ወደ ንጉሡ ወደ ናቡከደነፆርም አንጋጠው እያለቀሱ “አቤቱ፥ የሶሮት አምላክ ሆይ፥ ይቅር በለን” የሚሉ ከሕዝቡ አገኘን።'),
  ('e532f36a-6ade-5353-ad4c-577fb5aa1574', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 16, 16, 'እኒህ ያዘኑ ሰዎች ሌላውን አምላክ ሲጠሩ “ይቅር በለንም” ሲሉ ይህን ነገር በሰማሁ ጊዜ አዝኜ አለቀስሁ።'),
  ('6e3a535b-668c-5792-a436-1d63339695bb', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 17, 17, 'ዳግመኛም እኔ ሳንማረክ በኢየሩሳሌም ያደረግነውን በዓል ዐሰብሁ፤ ይህንም ዐስቤ እየተጨነቅሁና እያለቀስሁ ወደ ቤቴ እመለስ ነበር።'),
  ('4285d32e-5488-54cb-a585-20e265516cc1', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 18, 18, 'አሁንም ከፋርስ ሀገር እንዲወጡ ቃሌን ይሰሙ ዘንድ፥ ከአፌ የወጣውንም ነገር ይቀበሉ ዘንድ ስለ ወገኖቻችን አቤሜሌክና አንተ ባላችሁበት ቦታ ፈጣሪያችንን ለምኑ።'),
  ('7c221e06-ea12-5da5-aee6-c2b50408dde8', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 19, 19, 'አሁንም በኖርንበት ዘመን ሁሉ “ፈጣሪያችሁ በጽዮን ከሚመሰገንበት ምስጋና ወገን አዲስ ምስጋናን ንገሩን” ብለው ያዙን ብዬ እነግርሃለሁ።'),
  ('8e5e2faf-ebcd-5dd4-a9e0-602dc3a7ab71', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 20, 20, 'እኛም፥ “በባዕድ ሀገር ሳለን እንደ ምን እንዘምርላችኋለን?” አልናቸው።'),
  ('3eb5a63e-6d69-51c7-a548-2e30bad59a1e', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 21, 21, 'ኤርምያስም እንደዚሁ አድርጎ ጽፎ ደብዳቤውን በንስሩ አንገት አስሮ “በሰላም ሂድ፤ ጌታም አንተን ይጐብኝህ” አለው።'),
  ('25a4ddc5-f325-5756-ac21-627913845b04', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 22, 22, 'ንስሩም ደብዳቤውን ይዞ በርሮ ሄደ፤ ደብዳቤውንም ወደ ባሮክ አደረሰ፤ ባሮክም ደብዳቤውን ከፍቶ አነበበው፤ የሕዝቡንም ኀዘንና መከራ በሰማ ጊዜ አለቀሰ።'),
  ('889fd0a3-1ee3-58be-a7e4-c156d9c01188', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 23, 23, 'ኤርምያስ ግን ያን በለስ ተቀብሎ በሕዝቡ ዘንድ ላሉ በሽተኞች ሰጣቸው።'),
  ('018b7faf-8d2f-5c5d-ab17-6b777266f6d2', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 24, 24, 'የባቢሎንንም አሕዛብ ርኵሰት እንዳይሠሩ እያስተማራቸው ተቀመጠ።'),
  ('1bd4dc39-4abb-5da9-acd5-6599bb8e8f2c', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 25, 25, 'እግዚአብሔርም ሕዝቡን ከባቢሎን የሚያወጣባት ቀን በደረሰች ጊዜ፥'),
  ('37353550-2092-5cbd-a19e-2c4d994a352a', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 26, 26, 'ጌታ ኤርምያስን እንዲህ አለው፥ “አንተ ተነሥ፤ ወገኖችህም ይነሡ፤ ወደ ዮርዳኖስም ኑ፤ ለሕዝቡም የባቢሎንን ሕዝብ ሥራ ይተዉ ዘንድ ጌታ ይወዳል በላቸው።'),
  ('1165c29c-59a3-5fbb-aaa8-b407a8620a8d', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 27, 27, 'ከእናንተ ሴቶችን ያገባ ወንድን፥ ወንዶችን ያገቡ ሴቶችንም ፈትናቸው፤ ቃልህን የሰሙ ሰዎችን ወደ ኢየሩሳሌም መልሳቸው፤ ያልሰሙህን ሰዎች ግን ወደ እርሷ ይገቡ ዘንድ አትተዋቸው።”'),
  ('d27c8866-ac18-5a47-a1c3-c3c46a7cacdb', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 28, 28, 'ኤርምያስም እንዲሁ ይህን ሁሉ አነበበላቸው፤ ሊፈትናቸውም ወደ ዮርዳኖስ አመጣቸው፤ ጌታም ያላቸውን ይህን ነገር ሲነግራቸው ያገቡ ሰዎች ተለያዩ፤ ሊፋቱም አልወደዱም፤ ኤርምያስንም አልሰሙትም።'),
  ('66b8d9b2-108f-55eb-a9d3-a4afed06eb2c', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 29, 29, '“ሚስቶቻችንን ለዘለዓለሙ አንተውም፤ ከእኛ ጋራ ወደ ሀገራችን እንወስዳቸዋለን” ያሉ ሰዎችም ነበሩ፤ ከዮርዳኖስም ተሻግረው ወደ ኢየሩሳሌም ደረሱ።'),
  ('b26e9d8a-cc71-5379-a64a-f058355726a8', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 30, 30, 'ኤርምያስና ባሮክ፥ አቤሜሌክም “ከባቢሎን ሴት ያገባ ሰው ሁሉ ወደ ሀገራችን አይገባም” ብለው ተነሡ።'),
  ('db5aca2f-9f9c-57b4-a1e0-db61a803db01', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 31, 31, 'ሚስት ያገቡ ሰዎችም ባልንጀሮቻቸውን፥ “ተነሡ፤ ወደ ባቢሎን እንመለስ” አሏቸው ወደ ባቢሎንም ተመልሰው ሄዱ።'),
  ('99b44f2a-6bf8-595b-aabf-01acdda78b1c', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 32, 32, 'የባቢሎንም ሰዎች ባዩአቸው ጊዜ ሊቀበሏቸው ወጡ፤ “እናንተ አስቀድማችሁ እኛን ጠልታችሁናልና ከእኛ ተሰውራችሁ ወጣችሁ” ብለው ወደ ባቢሎን ይገቡ ዘንድ አልተዉአቸውም።'),
  ('706d0dfe-38bf-56f6-adbb-a847fec6c316', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 33, 33, '“ከእኛ ተሰውራችሁ ስለ ወጣችሁ እናንተንና ሴቶች ልጆቻችሁን እንዳንቀበላችሁ በአምላካችን ስም ምለናልና ስለዚህ ነገር በደላችሁ፤ ወደ ሀገራችንም አትገቡም” አሏቸው።'),
  ('04780796-b310-5316-aae4-b83b68241c4c', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 34, 34, 'እንደዚያም ያለውን ቃል ሰምተው ወደ ኢየሩሳሌም ተመለሱ፤ በኢየሩሳሌምም አውራጃ ከተማ አቀኑ፤ ያንም ከተማ ሰማርያ አሉት።'),
  ('3bf0c731-cd41-554e-a4c1-c90ed57103f4', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 35, 35, 'ኤርምያስም “ንስሓ ግቡ፤ እነሆ፥ የጽድቅ መልአክ ይመጣል፤ ለብዙ ዘመንም ወደምትኖሩበት ቦታችሁ ይመልሳችኋል” ብሎ ወደ እነርሱ ላከ። እነርሱም ደስ ብሏቸው ስለ ሕዝቡ መሥዋዕት እየሠዉ ሰባት ቀን ተቀመጡ።'),
  ('bf03677d-7ae0-53b8-aa30-d473eb98e980', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 36, 36, 'ይህም ከተደረገ በኋላ በዐሥረኛው ቀን ኤርምያስ ብቻውን ወጣ።'),
  ('84110102-2a68-5344-a536-90e5b6e69af5', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 37, 37, 'ኤርምያስም እንዲህ ብሎ ጸለየ፥ “ለሰው በጎ መዓዛ የምትሆን አንተ ቅዱስ፥ ቅዱስ፥ ቅዱስ ወደ አንተ እስክደርስ ድረስ ዕውቀትን የምትገልጥልኝ እውነተኛ ዐዋቂ አንተ ነህ።'),
  ('89604fba-f91a-5d0f-a705-26cbe723ac4a', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 38, 38, 'ስለ ወገኖችህ ስለ እስራኤልም እለምንሃለሁ፤ ስለ ተወደደው ስለ ሱራፌል ምስጋና፥ በጎ መዓዛ ስላለው ስለ ኪሩቤልም ዕጣን እለምንሃለሁ፤ የጽድቅ ሊቀ መላእክት ሚካኤልም በእውነት አመስጋኝ ነው፤ የሚያበራልኝ፥ ጻድቃንም እስከ ገቡባቸው ድረስ የጽድቅ በሮችን የሚከፍትልኝ እርሱ ነው።'),
  ('afd4be71-d94b-5df9-ae89-b185f8de9c02', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 39, 39, 'የሁሉ ጌታ አቤቱ፥ እለምንሃለሁ፤ ሁሉን የምትገዛ ጌታ አንተ ነህ፤ የሚታየውንና የማይታየውን ሁሉ ፈጥረህ የጨረስህ፥ የተሰወረው ሁሉ፥ ሳይፈጠርም ተሰውሮ የነበረው ሁሉ በአንተ ዘንድ አለ።”'),
  ('7ed37b7c-cdad-5cca-a165-6b6efbc8e28a', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 40, 40, 'ይኽንም ጸለየ፤ ጸሎቱንም ከፈጸመ በኋላ ኤርምያስ ወደ ቤተ መቅደስ ገብቶ ቆመ፤ ባሮክና አቤሜሌክም ከእርሱ ጋር ነበሩ፤ ኤርምያስም ነፍሱ ከሥጋው እንደ ተለየች እንደ አንድ ሰው ሆነ።'),
  ('a97832db-08d4-59ae-a470-885a391107b7', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 41, 41, 'ያንጊዜም ባሮክና አቤሜሌክ ወድቀው በታላቅ ድምፅ ጮሁ፤ “ወዮልን! የአምላክ ካህን አባታችን ኤርምያስ ከእኛ ተለየ” አሉ።'),
  ('0ba8b46c-3418-529a-a773-b2168c5ecd55', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 42, 42, 'ሕዝቡም እንዲህ ሰምተው ወደ እርሱ ሮጡ፤ ኤርምያስንም ወድቆ እንደ ሞተም ሆኖ አገኙትና አለቀሱ፤ ልብሶቻቸውንም ቀደዱ፤ በራሳቸውም ላይ ትቢያ ነሰነሱ፤ መራራ ልቅሶንም አለቀሱ።'),
  ('2385e279-c29c-5094-a368-ebdb7929976f', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 43, 43, 'የሚቀብሩበትንም ካዘጋጁ በኋላ “ደኅና ነውና ነፍሱም ዳግመኛ ወደ ሥጋው ትመለሳለችና አትገንዙት” የሚል ቃል መጣ።'),
  ('9055be12-2d72-5586-a25c-7945a1e8bef1', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 44, 44, 'ይህንም ቃል በሰሙ ጊዜ ዳግመኛ ነፍሱ ወደ ሥጋው እስክትመለስ ድረስ እየጠበቁት ሦስት ቀን በዙሪያው ተቀመጡ እንጂ አልገነዙትም።'),
  ('9068c71b-e13a-5ad7-a675-8c7d3d8d7f36', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 45, 45, 'በሁሉም መካከል እንዲህ የሚል ቃል ተሰማ፤ “በአንድ ቃል አመስግኑት፤ አምላካችንን አመስግኑት፤ ሁላችሁም የአምላክን ልጅ መሢሑን አመስግኑት።'),
  ('cae7998b-4c42-50d0-a885-e62765812571', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 46, 46, 'የዓለሙ ሁሉ ብርሃን የአምላክ ልጅ ኢየሱስም ይፈርድባችኋል።'),
  ('0f43e60d-2835-5275-aa8e-6b283a172c77', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 47, 47, 'የማይጠፋ ብርሃን፥ የሃይማኖትም ሕይወት ነው።'),
  ('b3c722f8-c2a7-592d-ab1c-cd563380f6e1', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 48, 48, 'ከዚህ ዘመን በኋላም ወደ ምድር ለመምጣቱ ሦስት መቶ ሠላሳ ሦስት የቀን ሱባዔ ይሆናል።'),
  ('387dd19c-0643-5640-a4d8-afe06c6facbe', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 49, 49, '“በገነት መካከል ያለ ያልተተከለ የሕይወት ዛፍ፥ ዛፎችን ሁሉ ፍሬ እንዲያፈሩ፥ የደረቁትም ወደ እርሱ እንዲመጡ ያደርጋቸዋል።'),
  ('69383416-663f-51a1-a96a-bcf73a4a78d5', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 50, 50, 'ፍሬ እንዲያፈሩ፥ እንዲለመልሙና እንዲያድጉም ያደርጋቸዋል፤ ሥሩ ምድርን እንዳልያዘ ተክል ሥራቸው እንዳይደርቅ ለሰማያዊ አምላክ ግብርን እንስጥ፤ ቀይ መልክ ያለው ቀለምም እንደ ባዘቶ ይነጣል።'),
  ('71d555c1-317c-5aee-ab4f-a91b975fdfe9', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 51, 51, 'የጣፈጠው ውኃ መራራ ይሆናል፤ መራራውም የጣፈጠ ይሆናል፤ በልጁም አንደበት ፍሬን ያፈሩ ዘንድ እግዚአብሔር በታላቅ ሐሤትና ደስታ ደሴቶችን ይመርቃቸዋል።'),
  ('a298c1e6-26bc-5eb4-af72-5d64a348389f', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 52, 52, 'እርሱም ራሱ ሰው ሆኖ ወደዚህ ዓለም ይመጣል፤ እኔ ሰው ሆኖ ያየሁት፥ ከአባቱም ወደዚህ ዓለም የሚላከው፥ ሰው ሆኖም ወደዚህ ዓለም የሚመጣው፥ እርሱ አብሯቸው ይታይ ዘንድ፥ ይገለጥላቸውም ዘንድ ዐሥራ ሁለት ሐዋርያትን ለእርሱ ይመርጣል፤ ወደ ደብረ ዘይትም ይሄዳል፤ የተራበችንም ነፍስ ሁሉ ያጠግባል።”'),
  ('dae59d14-d68b-5d87-a961-5f3500fd5530', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 53, 53, 'ወደዚህ ዓለም እንደሚመጣ ኤርምያስ የአምላክን ልጅ ነገር እንዲህ ተናገረ።'),
  ('d194c1b2-69f8-5d61-abbe-c580ca0c2b25', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 54, 54, 'ሕዝቡም ይህን ነገር በሰሙ ጊዜ ኤርምያስ፥ “የአምላክን ልጅ አምላክን አየሁት” ብሎ ስለ ተናገረው ስለዚህ ነገር ተቈጡ፤ እነሆም፥ “በኢሳይያስ እንዳደረግን በእርሱም እናድርግበት፤ ተነሡ” አሉ። እኩሌቶቹ፥ “በደንጊያ ወግረን እንግደለው እንጂ አይሆንም” አሉ።'),
  ('241063b8-db90-52a3-aa13-ba19e99b3ca0', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 55, 55, 'ባሮክና አቤሜሌክም፥ “በዚች ሞት አትግደሉት” ብለው ጮሁላቸው፤ ባሮክና አቤሜሌክም ስለ ኤርምያስ አዘኑ።'),
  ('bc9ee1a6-9193-5c33-aa13-682010e963e3', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 56, 56, 'ዳግመኛም ያያቸውን የተሰወሩ ምሥጢሮችን ይነግራቸው ዘንድ አልተዉትም፤ ኤርምያስም፥ “ያየሁትን ሁሉ እስካስተምራችሁ ድረስ እኔን መግደል አይችሉምና አታልቅሱ” አላቸው።'),
  ('ca52f785-67fe-5efe-a7e3-97f8dc7aa105', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 57, 57, '“አሁንም አንዲት ድንጋይ አምጡልኝ፤” አላቸው፥ እነርሱም አንዲት ድንጋይ አመጡለት፤ እርሱም አቆማት፤ “የዘለዓለም ብርሃን ሆይ፥ ይህቺን ድንጋይ እንደ እኔ ትሆን ዘንድ አድርግልኝ” አለ።'),
  ('20574e0f-fd83-55e8-a0a4-7c8653541bd0', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 58, 58, 'ያንጊዜም ድንጋዩ ኤርምያስን በመልክ የሚመስለው ሆነ፤ ኤርምያስንም መሰላቸውና ድንጋዩን በድንጋይ ይደበድቡ ጀመር፤ ወንጀልንም ጨረሱ።'),
  ('34d6e3aa-5ac6-5b39-a139-824f8704787a', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 59, 59, 'ኤርምያስ ግን ያያቸውን ምሥጢሮች ሁሉ ለባሮክና ለአቤሜሌክ ነገራቸው፤ ይህንም ነግሯቸው ከጨረሰ በኋላ ምግብናውን ይፈጽም ዘንድ ወደደ፤ ሄዶም በሕዝቡ መካከል ቆመ።'),
  ('19aba92e-baea-51ad-adec-17fbfd47e3c0', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 60, 60, 'ያንጊዜም ያ ድንጋይ፥ “እናንት ሰነፎች የእስራኤል ልጆች፥ ኤርምያስን መስያችሁ በድንጋይ ስለ ምን ትደበድቡኛላችሁ? ኤርምያስስ እነሆ በመካከላችሁ ቁሟል” ብሎ ጮኸ።'),
  ('a2df36eb-c75c-5c35-affc-5b097e961103', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 61, 61, 'ኤርምያስንም ባዩት ጊዜ ብዙ ድንጋይ ይዘው ወደ እርሱ ሮጡ፤ እርሱም ምስክርነቱን ጨረሰ፤ ባሮክና አቤሜሌክም መጥተው ቀበሩት፤ ያንም ድንጋይ አምጥተው በመቃብሩ አፍ እንደ መዝጊያ አድርገው አኖሩት።'),
  ('311d5303-048d-5822-a70b-460790985c4a', '0a0997bd-e6fe-5c10-a6bb-be707f7e50e6', 'f7cfaaaf-4307-5b26-ab7c-6e6994daae9e', 62, 62, '“የኤርምያስ ረዳቱ እነሆ፥ ይህ ድንጋይ ነው” ብለው በውስጡ ጻፉ፤ የኤርምያስም የቀረች ነገሩ እነሆ፥ በባሮክ መጽሐፍ ተጽፋለች።'),
  ('9ef66c3b-4037-5af0-a58a-6d872273c3ff', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 1, 1, 'በሠላሳኛው ዓመት በአራተኛው ወር ከወሩም በአምስተኛው ቀን በኮቦር ወንዝ በምርኮኞች መካከል ሳለሁ ሰማያት ተከፈቱ፤ የእግዚአብሔርንም ራእይ አየሁ።'),
  ('e785d031-3939-5921-a3f4-929d4cb93cd4', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 2, 2, 'ንጉሡ ዮአኪን በተማረከ በአምስተኛው ዓመት፥ ከወሩም በአምስተኛው ቀን፥'),
  ('500d0b90-0ba4-5ce2-aa31-95578b33b65f', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 3, 3, 'የእግዚአብሔር ቃል በከለዳውያን ሀገር በኮቦር ወንዝ ላይ ወደ ቡዝ ልጅ ወደ ካህኑ ወደ ሕዝቅኤል መጣ። የእግዚአብሔርም እጅ በዚያ በእኔ ላይ ሆነች፤'),
  ('3224e568-1691-5a60-ac91-5c2d0ebe7eaf', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 4, 4, 'እኔም አየሁ፤ እነሆም ከሰሜን በኩል ዐውሎ ነፋስና ታላቅ ደመና፥ የሚበርቅም እሳት መጣ፤ በዙሪያውም ፀዳል ነበረ፤ በመካከልም በእሳቱ ውስጥ የሚብለጨለጭ ነገር ነበረ።'),
  ('15ce25d9-7a40-58fb-a6aa-cf3189b98259', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 5, 5, 'ከመካከልም የአራት እንስሶች አምሳያ ወጣ። መልካቸውም እንደዚህ ነበረ፤ ሰውም ይመስሉ ነበረ።'),
  ('96c0a8c2-317e-5d03-a684-434c54f25b41', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 6, 6, 'ለእያንዳንዱም አራት አራት ፊት፥ ለእያንዳንዱም አራት አራት ክንፍ ነበሩት።'),
  ('3bd5486b-c1b6-5d36-ae9f-705f70b672e6', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 7, 7, 'እግሮቻቸውም ቀጥ ያሉ ነበሩ፤ የእግራቸው ሰኰና እንደ ላም እግር ሰኰና ነበረ፤ እንደ ተወለወለ ናስም ይብለጨለጭ ነበር።'),
  ('c35e7802-e527-5ed7-a80c-e38dc96bf725', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 8, 8, 'በክንፎቻቸውም በታች በእየአራቱ ጐድናቸው የሰው እጅ ነበረ፤ ለአራቱም እንደዚህ ያሉ ፊትና ክንፍ ነበሩአቸው።'),
  ('d1a025ea-2cc3-54bb-a9e3-ed9a7b76083b', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 9, 9, 'የሁሉም ክንፎቻቸው አንዱ ከአንዱ ጋር የተያያዘ ነው፤ ሲሄዱም ወዲያና ወዲህ ሳይሉ አቅንተው ይሄዳሉ፤ አንዱም አንዱም ወደፊቱ ይሄዳል።'),
  ('3e506290-dc3e-5e4e-a1ac-ebf73f610209', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 10, 10, 'የፊታቸው አምሳያ እንደዚህ ነው፦ ለአራቱ ሁሉ በቀኛቸው የሰው ፊትና የአንበሳ ፊት አላቸው፤ ለአራቱም ሁሉ በግራቸው የእንስሳ ፊትና የንስር ፊት አላቸው።'),
  ('cdce8b0c-1b68-5329-a1f8-75994535bf88', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 11, 11, 'ክንፋቸውም በላይ ተዘርግቶ ነበር፤ የእያንዳንዱም ሁለት ሁለት ክንፋቸው የተያያዙ ነበሩ፤ ሁለት ሁለቱም ገላቸውን ይከድኑ ነበር።'),
  ('f1370c59-685e-5902-a4bf-3e4abcb7b07e', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 12, 12, 'እያንዳንዱም ወደ ፊት ቀጥ ብሎ ይሄድ ነበር፤ መንፈስም ወደሚሄድበት ሁሉ ይሄዱ ነበር፤ ሲሄዱም ወዲያና ወዲህ አይሉም ነበር።'),
  ('6a281d72-0d02-54c6-acf4-444d6f95473d', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 13, 13, 'በእንስሶቹም መካከል እንደሚነድድ የእሳት ፍም ያለ አምሳያ ነበረ፤ በእንስሶቹ መካከል ወዲህና ወዲያ የሚሄድ እንደ ፋና ያለ አምሳያ ነበረ፤ ለእሳቱም ፀዳል ነበረው፤ ከእሳቱም መብረቅ ይወጣ ነበር።'),
  ('7cea7992-4088-57fd-a513-4159405b2e99', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 14, 14, 'እንስሶቹም እንደ መብረቅ አምሳያ ይሮጡና ይመለሱ ነበር።'),
  ('54e95253-319b-5237-a3a7-ba7816c9584c', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 15, 15, 'ስመለከትም፥ እነሆ በአራቱ እንስሶች አጠገብ በምድር ላይ አንድ መንኰራኵር አየሁ።'),
  ('61ba6995-8648-5ab1-a4aa-68338877e799', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 16, 16, 'የመንኰራኵሩም መልክ እንደ ቢረሌ ነበረ፤ አራቱም አንድ አምሳያ ነበሩ፤ ሥራቸውም በመንኰራኵር ውስጥ እንዳለ መንኰራኵር ነበረ።'),
  ('0151ed39-3865-5546-a8ae-8ca16695e091', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 17, 17, 'በእየአራቱም ጐድናቸው ይሄዱ ነበር፤ ሲሄዱም ጀርባቸውን አይመልሱም ነበር። ከፍ ከፍ ያሉም ነበሩ።'),
  ('dc16dd73-c112-538c-a8d9-82717c1ef616', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 18, 18, 'በአራቱ ዙሪያ ሁሉ ዐይኖችን የተመላ ጀርባቸውን አየሁ፤'),
  ('bad45944-c5c6-5f0c-a8af-0d3ad824a40e', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 19, 19, 'በሄዱም ጊዜ ሠረገላዎች ከእነርሱ ጋር ይሄዳሉ። እንስሶቹም ከምድር ሲነሡ መንኰራኵሮቹም ከእነርሱ ጋር ይነሣሉ።'),
  ('9c4b119d-9ef9-583a-aa72-07d75f433343', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 20, 20, 'ደመና ባለበት በዚያ መንፈስ አለ፤ እንስሶቹ ይሄዳሉ፤ ከእነርሱም ጋር መንኰራኵሮቹ ይነሣሉ፤ የሕይወት መንፈስ በመንኰራኵሮች አለና።'),
  ('c9bc136d-8270-5676-a685-12b46c8deed9', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 21, 21, 'በሄዱም ጊዜ ይሄዳሉ፤ በቆሙም ጊዜ ይቆማሉ፤ በእነዚያ መንኰራኵሮች ውስጥ የሕይወት መንፈስ አለና ከምድር በተነሡ ጊዜ መንኰራኵሮቹ ከእነርሱ ጋር ይነሣሉ።'),
  ('372bcf58-a8a2-5bd9-a590-51e750a5f208', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 22, 22, 'በእነዚያ እንስሶች ራስ ላይ ያለው መልክ ከላይ በክንፎቻቸው ላይ የተዘረጋ የበረድ መልክ እንዳለበት ጠፈር ነው፤'),
  ('5209f0dd-36ca-5ee0-a9d3-4f7e7598a05c', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 23, 23, 'ከጠፈሩም በታች ክንፎቻቸው እርስ በርሳቸው ተቃንተው ነበር፤ ለእያንዳንዱም ገላውን የሚከድኑ ሁለት ሁለት ክንፎች ነበሩት።'),
  ('c7b1617d-0735-578e-adf0-9dbe3525f7c6', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 24, 24, 'ሲሄዱም የክንፎቻቸው ድምፅ እንደ ብዙ ውኃ ድምፅ፥ ሁሉን እንደሚችል የአምላክም ድምፅ፥ እንደ ታላቅ ሠራዊትም ድምፅ ሆኖ ሰማሁ፤ ሲቆሙም ክንፎቻቸውን ይሰበስቡ ነበር።'),
  ('1c019a27-f968-5186-a7d3-d963bb1a0f06', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 25, 25, 'በራሳቸውም ላይ ካለው ጠፈር በላይ ድምፅ ተሰማ፤ ሲቆሙም ክንፎቻቸውን ይሰበስቡ ነበር።'),
  ('4f0b9539-6954-5c5d-ae61-8b09b8d04103', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 26, 26, 'በራሳቸውም በላይ ከአለው ጠፈር በላይ የሰንፔር ድንጋይ የሚመስል የዙፋን አምሳያ ነበረ፤ በዙፋኑም አምሳያ ላይ እንደ ሰው መልክ አምሳያ ነበረ።'),
  ('0aabc9bf-42a5-5da3-ac3c-7e8f8d68adce', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 27, 27, 'ከወገቡም አምሳያ ወደ ላይ የሚብለጨለጭ የወርቅ አምሳያ አየሁ፤ ከወገቡም አምሳያ ወደ ታች እንደ እሳት አምሳያ አየሁ፤ በዙሪያውም ፀዳል ነበረ።'),
  ('d95c0fa2-c735-509e-a6b7-874af2c078c0', '65623fc3-56ba-51fb-af6e-49eaa52891e6', '9f888431-6e4c-5dd2-a941-fb2dd0d825a8', 28, 28, 'በዝናብ ቀን በደመና ውስጥ እንደ አለ ቀስተ ደመና አምሳያ፥ እንዲሁ በዙሪያው ያለ ፀዳል አምሳያ ነበረ። የእግዚአብሔር ክብር ምሳሌ መልክ ይህ ነበረ። በአየሁም ጊዜ በግንባሬ ተደፋሁ። የሚናገርንም ድምፅ ሰማሁ።'),
  ('745c5b6b-4a0e-5b20-adaf-26de8f3c57ae', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 1, 1, 'እርሱም፥ “የሰው ልጅ ሆይ! በእግርህ ቁም፤ እኔም እናገርሃለሁ” አለኝ።'),
  ('29e2d03c-a217-5579-a41e-a57b81b40f0d', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 2, 2, 'በተናገረኝም ጊዜ መንፈስ በእኔ ላይ መጣ፤ አነሣኝም፤ በእግሬም አቆመኝ፤ የሚናገረኝንም ሰማሁ።'),
  ('082bca84-0a1c-56fb-a58f-7636e4e37eb4', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 3, 3, 'እርሱም እንዲህ አለኝ፥ “የሰው ልጅ ሆይ! እኔን ወደ አስመረሩኝ ወደ እስራኤል ቤት እልክሃለሁ። እነርሱና አባቶቻቸው እስከ ዛሬ ድረስ ዐመፁብኝ።'),
  ('2b267493-f3b1-5dff-a2f5-3af05032c67f', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 4, 4, 'እነርሱ ፊታቸው የከፋ፥ ልባቸው የደነደነ ልጆች ናቸው። እኔ ወደ እነርሱ እልክሃለሁ፤ አንተም፦ ጌታ እግዚአብሔር እንዲህ ይላል በላቸው።'),
  ('f8c1ebc2-79dd-5b8a-a925-645097637b75', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 5, 5, '“እነርሱ ዐመፀኛ ቤት ናቸውና ቢሰሙ ወይም ቢፈሩ አንተ በመካከላቸው ነቢይ እንደ ሆንህ ያውቃሉ።'),
  ('4512ef08-d597-535b-ac97-eca58501bfb0', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 6, 6, 'አንተ የሰው ልጅ ሆይ! ኩርንችትና እሾህ ከአንተ ጋር ቢኖሩም፥ አንተም በጊንጦች መካከል ብትቀመጥ፥ አትፍራቸው፤ ቃላቸውንም አትፍራ፤ አንተ ቃላቸውን አትፍራ፤ ከፊታቸውም የተነሣ አትደንግጥ፤ እነርሱ ዐመፀኛ ቤት ናቸውና።'),
  ('982b59f2-6e7a-548f-a2b9-4c4aec0f89d5', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 7, 7, 'እነርሱ ዐመፀኛ ቤት ስለሆኑ ቢሰሙ ወይም ቢደነግጡ ቃሌን ትነግራቸዋለህ።'),
  ('c24b7d52-7678-53e4-a708-43ff07c163a7', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 8, 8, '“አንተ የሰው ልጅ ሆይ! የምነግርህን ስማ፤ እንደእዚያ ዐመፀኛ ቤት ዐመፀኛ አትሁን፤ አፍህን ክፈት፤ የምሰጥህንም ብላ።”'),
  ('04ff2f9e-43c9-5544-a853-136c02e90d2c', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 9, 9, 'በአየሁም ጊዜ፥ እነሆ እጅ ወደ እኔ ተዘርግታ ነበር፤ እነሆም የመጽሐፍ ጥቅልል ነበረባት።'),
  ('9fdd849b-60d3-5b85-adb3-6c1b0e890b09', 'dfe7bbf9-f022-5617-a862-7a581fc035d3', '7352e752-3af6-5caf-aeef-4eac385f8219', 10, 10, 'በፊቴም ዘረጋው፤ በውስጥና በውጭም ተጽፎበት ነበረ፤ ጽሑፉም “ልቅሶና ኀዘን፥ ዋይታም” ይል ነበር።'),
  ('e1115af4-1596-51e3-a3d1-b4b8b093c2af', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 1, 1, 'እርሱም፥ “የሰው ልጅ ሆይ! ያገኘኸውን ብላ፤ ይህን መጽሐፍ ብላ፤ ሄደህም ለእስራኤል ልጆች ተናገር” አለኝ።'),
  ('86a755f1-a026-5d16-a8cb-e114fd476411', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 2, 2, 'አፌንም ከፈትሁ፤ መጽሐፉንም አበላኝ።'),
  ('7d7ca16d-fce8-5234-a52c-e04cc89aa155', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 3, 3, 'እርሱም፥ “የሰው ልጅ ሆይ! አፍህ ይብላ፤ በምሰጥህም በዚህ መጽሐፍ ሆድህን ሙላ” አለኝ። እኔም በላሁት፤ በአፌም ውስጥ እንደ ማር ጣፈጠ።'),
  ('4e89f9c5-5d48-5ead-a3de-e830313c13f9', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 4, 4, 'እንዲህም አለኝ፥ “የሰው ልጅ ሆይ! ተነሥተህ ወደ እስራኤል ቤት ሂድና ግባ፥ ቃሌንም ንገራቸው።'),
  ('49eeaf9e-81da-54c4-a585-9fde7650fa88', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 5, 5, 'ወደ እስራኤል ቤት እንጂ ንግግራቸው ልዩ ወደ ሆነ፥ ቋንቋቸውም ወደማይታወቅ ሕዝብ አልተላክህምና፤'),
  ('13a3a882-8e94-522f-a99d-fc3d1e9de616', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 6, 6, 'ንግግራቸው ልዩ ወደ ሆነ፥ ቋንቋቸውም ሌላ ወደ ሆነ፥ ቃላቸውንም ታውቅ ዘንድ ወደማይቻልህ ሕዝብ አልላክሁህም። ወደ እነዚያስ ልኬህ ቢሆን ኖሮ በሰሙህ ነበር።'),
  ('032a0620-60fe-5de0-ad88-a1f3be5a5386', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 7, 7, 'ነገር ግን የእስራኤል ቤት ሁሉ ክፉዎችና ልበ ደንዳኖች ናቸውና፥ እኔንም መስማት እንቢ ብለዋልና የእስራኤል ቤት አንተን አይሰሙህም።'),
  ('2343e7b7-a8b0-51d8-a56b-3f5df9ba6217', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 8, 8, 'እነሆ ፊትህን በፊታቸው አጸናሁት፤ ኀይልህንም ከኀይላቸው ይልቅ አጸናለሁ።'),
  ('dd0d4882-7851-5aa4-aad5-49f8dbcdf135', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 9, 9, 'ሁልጊዜ ከዓለት ይልቅ ትጸናለህ፤ አትፍራቸው፤ ከፊታቸውም አትደንግጥ፤ ዐመፀኛ ቤት ናቸውና።”'),
  ('499947da-978a-554e-a0d8-8924c2135639', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 10, 10, 'እርሱም፥ “የሰው ልጅ ሆይ! የነገርሁህን ቃሌን ሁሉ በልብህ ጠብቀው፤ በጆሮህም ስማው።'),
  ('b082d492-c6c5-5910-a7c5-da4fb58d2519', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 11, 11, 'ተነሥተህም ወደ ተማረኩ ወደ ወገንህ ልጆች ሂድ፤ እነርሱም ቢሰሙ ወይም ቢፈሩ፦ ጌታ እግዚአብሔር እንዲህ ይላል ብለህ ንገራቸው” አለኝ።'),
  ('b91b80ac-b9ae-502a-a28e-c2ca2ca85b92', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 12, 12, 'መንፈስም ወደ ላይ ወሰደኝ፤ በኋላዬም፥ “የእግዚአብሔር ክብር ከቦታው ይባረክ” የሚል የታላቅ ንውጽውጽታ ድምፅ ሰማሁ።'),
  ('a6c5d2de-6d29-5619-a3e8-c34fcd7600de', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 13, 13, 'የእነዚያም እንስሳ ክንፎች እርስ በርሳቸው ሲማቱ፥ በአጠገባቸውም የመንኰራኵሮችን ድምፅ፥ የታላቁንም ንውጽውጽታ ድምፅ ሰማሁ።'),
  ('983b4c53-79b2-58ad-ad5a-80ac620c5d29', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 14, 14, 'መንፈስም አንሥቶ ወሰደኝ፤ እኔም በምሬትና በመንፈሴ ሙቀት ሄድሁ፤ የእግዚአብሔርም እጅ በላዬ በርትታ ነበር።'),
  ('7197af3e-8d9f-54ad-a0ed-c42793210c1e', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', 'cc40c074-da53-55c9-ac8e-546bae8b68ea', 15, 15, 'በቴልአቢብም ወደ አሉ፥ በኮቦርም ወንዝ አጠገብ ወደ ተቀመጡ ምርኮኞች መጣሁ፤ በተቀመጡበትም ቦታ ተቀመጥሁ፤ በዚያም በመካከላቸው እየተመላለስሁ ሰባት ቀን ተቀመጥሁ።'),
  ('e0eea70a-8bfe-5547-af73-8729b0d16661', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 1, 16, 'ከሰባቱም ቀን በኋላ የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e5316082-3eb4-5299-adb9-9ddd34271cdc', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 2, 17, '“የሰው ልጅ ሆይ! ለእስራኤል ቤት ጕበኛ አድርጌሃለሁ፤ ስለዚህ የአፌን ቃል ስማ፤ በቃሌም ገሥጻቸው።'),
  ('3248c331-813e-5bcf-ad7b-5f27a5fd7a28', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 3, 18, 'እኔ ኀጢአተኛውን፥ “በእርግጥ ትሞታለህ ባልሁት ጊዜ አንተም ባትነግረው፥ ነፍሱም እንድትድን ከክፉ መንገዱ ይመለስ ዘንድ ለኀጢአተኛው ባትነግረው፥ ያ ኀጢአተኛ በኀጢአቱ ይሞታል፤ ደሙን ግን ከእጅህ እፈልጋለሁ።'),
  ('9c44b6d4-048b-52aa-ab5c-fb0c57bf6a62', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 4, 19, 'ነገር ግን አንተ ኀጢአተኛውን ብትገሥጸው እርሱም ከኀጢአቱና ከክፉ መንገዱ ባይመለስ፥ በኀጢአቱ ይሞታል፤ አንተ ግን ነፍስህን ታድናለህ።'),
  ('53c3c284-ba4f-5dc8-acd0-31da9ab6016f', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 5, 20, 'ደግሞ ጻድቁ ከጽድቁ ተመልሶ ኀጢአት በሠራ ጊዜ እኔ በፊቱ ዕንቅፋት ባደርግ፥ እርሱ ይሞታል፤ አንተም አልነገርኸውምና በኀጢአቱ ይሞታል፤ ያደረጋትም የጽድቅ ነገር አትታሰብለትም፤ ደሙን ግን ከእጅህ እፈልጋለሁ።'),
  ('47e217f7-c1f9-5ca4-a5c6-b813373300a7', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 6, 21, 'ነገር ግን ኀጢአት እንዳይሠራ ጻድቁን ብትገሥጸው፥ እርሱም ኀጢአት ባይሠራ፥ ጻድቅ ነውና በሕይወት ይኖራል፤ አንተም ነፍስህን አድነሃል።”'),
  ('7b9657cb-7d22-53b2-aa91-52b86890d3c3', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 7, 22, 'በዚያም የእግዚአብሔር እጅ በእኔ ላይ ነበረች፤ እርሱም፥ “ተነሥተህ ወደ ሜዳ ሂድ፤ በዚያም እነግርሃለሁ” አለኝ።'),
  ('03bfbe00-fe35-539b-abf1-02a5e0f3e4ae', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 8, 23, 'እኔም ተነሥቼ ወደ ሜዳው ሄድሁ፤ እነሆም በኮቦር ወንዝ እንዳየሁት ክብር ያለ የእግዚአብሔር ክብር በዚያ ቆሞ ነበር፤ በግምባሬም ተደፋሁ።'),
  ('0bc4b4e7-8113-529c-a193-bb40266ac9b0', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 9, 24, 'መንፈስም ወደ እኔ መጣ፤ በእግሬም አቆመኝ፤ ተናገረኝም እንዲህም አለኝ፥ “ሂድ ገብተህ ቤትህን ዝጋ።'),
  ('feadf4cb-0b79-546e-a903-54b364e1f6df', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 10, 25, 'አንተም፥ የሰው ልጅ ሆይ! እነሆ ገመድ ያደርጉብሃል፤ ያስሩህማል፤ አንተም ከመካከላቸው አትወጣም፤'),
  ('b73d6d30-df28-5884-a347-6f867f962dde', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 11, 26, 'እኔም ምላስህን ከትናጋህ ጋር አጣብቃታለሁ፤ አንተም ዲዳ ትሆናለህ፤ እነርሱም ዐመፀኛ ቤት ናቸውና የሚዘልፍ ሰው አትሆንባቸውም።'),
  ('14b33fc1-0ab1-5c11-a589-db1ca1906d44', '85bbfac4-9eef-5314-ac0b-9055df04a0a6', '25a3ee76-ce6c-53a9-a3aa-cd5ec6eef05c', 12, 27, 'ነገር ግን በተናገርሁህ ጊዜ አፍህን እከፍታለሁ፤ እነርሱም ዐመፀኛ ቤት ናቸውና አንተ፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ የሚሰማ ይስማ፤ እንቢ የሚልም እንቢ ይበል” ትላቸዋለህ።'),
  ('7d42ac50-cd45-5519-af70-efb493943079', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 1, 1, '“አንተም የሰው ልጅ ሆይ! ጡብን ወስደህ በፊትህ አኑራት፤ የኢየሩሳሌምንም ከተማ ሥዕል ሣልባት፤'),
  ('5f9950fe-26f6-5399-a1a1-8c08ab97ea0b', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 2, 2, 'በውስጧም የሚዋጉበት ግንብን ሥራ፤ በሠራዊትም ክበባት፤ በዙሪያዋም ጦር አስፍር፤ የሚዋጋ ጦርንም ወደ አደባባይዋ ላክ።'),
  ('4a12afb5-2242-5911-a1fb-1026d75f663d', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 3, 3, 'የብረት ምጣድም ወስደህ በአንተና በከተማዪቱ መካከል ለብረት ቅጥር አድርገው፤ ፊትህንም ወደ እርስዋ አቅና፤ የተከበበችም ትሆናለች፤ አንተም ትከብባታለህ። ይህም ለእስራኤል ልጆች ምልክት ይሆናል።'),
  ('21cea01e-0dd3-5ddf-ad25-17d4a376de06', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 4, 4, '“አንተም በግራ ጎንህ ተኛ፤ በምትተኛበትም ቀን ቍጥር የእስራኤልን ቤት ኀጢአት አኑርባት፤ ኀጢአታቸውንም ትሸከማለህ።'),
  ('ceb4305b-f83d-5917-a80c-e7243737125a', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 5, 5, 'እኔም የኀጢአታቸውን ዓመታት ለአንተ የቀን ቍጥር እንዲሆንልህ ሦስት መቶ ዘጠና ቀን ሰጥቼሃለሁ፤ የእስራኤልንም ቤት ኃጢአት ትሸከማለህ፤'),
  ('b742f356-3487-5b29-a20b-f4a15c0d7cd3', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 6, 6, 'እነዚህንም በፈጸምህ ጊዜ በቀኝ ጎንህ ትተኛለህ፤ የይሁዳንም ቤት ኀጢአት አርባ ቀን ትሸከማለህ፤ አንዱን ቀን አንድ ዓመት አደረግሁልህ።'),
  ('d8d229d3-1f11-5951-a87e-18146e46a18b', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 7, 7, 'ወደ ኢየሩሳሌም ከበባ ፊትህን ታቀናለህ፤ ክንድህንም ታጸናለህ፤ በእርሷም ትንቢትን ትናገራለህ።'),
  ('4a5505d7-c0ff-54e4-ad96-e1dcf333adb3', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 8, 8, 'እነሆም ገመድ አደርግብሃለሁ፤ የምትከበብበትንም ወራት እስክትፈጽም ድረስ ከጎን ወደ ጎንህ አትገላበጥም።'),
  ('1b96a747-d159-51e1-aa7a-9037cb8ba52c', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 9, 9, '“አንተም ስንዴንና ገብስን፥ አተርንና ባቄላን፥ ምስርንና አጃን ወደ አንተ ውሰድ፤ በአንድ ዕቃም ውስጥ አድርገህ እንጀራ ጋግር፤ በጎንህ እንደ ተኛህባት ቀን ቍጥር ሦስት መቶ ዘጠና ቀን ትበላዋለህ።'),
  ('e7b6c3ed-5aaf-52c5-a267-23b2f3d8db8d', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 10, 10, 'የምትበላውም በሚዛን በየቀኑ ሃያ ሃያ ሰቅል ይሁን፤ በየጊዜው ትበላዋለህ።'),
  ('3f600df7-245a-5ad4-a07a-08dc8f068e16', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 11, 11, 'ውኃውንም በልክ የኢን መስፈሪያ ከስድስት እጅ አንድ እጅ ትጠጣለህ፤ በየጊዜው ትጠጣዋለህ።'),
  ('99871ae7-f05e-5191-aabc-46ebe284a400', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 12, 12, 'የገብስ እንጎቻንም ትበላለህ፤ በሰው ኵስም ታበስለዋለህ፤ በፊታቸውም ታዳፍነዋለህ።”'),
  ('3ddd0b3e-c04c-5089-a1a0-98d05f6bd6d3', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 13, 13, 'እግዚአብሔርም፥ “እንዲሁ የእስራኤል ልጆች እነርሱን በምበትንባቸው በአሕዛብ መካከል ንጹሕ ያልሆነ እንጀራቸውን ይበላሉ” አለ።'),
  ('baac77de-6ed8-5a8c-a887-e3f67b8dc725', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 14, 14, 'እኔም፥ “የእስራኤል አምላክ እግዚአብሔር ሆይ! ይህ አግባብ አይደለም፤ እነሆ ሰውነቴ አልረከሰችም፤ ከታናሽነቴ ጀምሮ እስከ ዛሬ ድረስ ጥንብና አውሬ የሰበረውን ከቶ አልበላሁም፤ ርኵስም ሥጋ በአፌ ውስጥ አልገባም” አልሁ።'),
  ('ad6e3892-66a8-5c76-a7e3-5834bfb7e3de', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 15, 15, 'እርሱም፥ “እነሆ በሰው ኵስ ፋንታ የከብት ኩበት ሰጥቼሃለሁ፤ በእርሱም እንጀራህን ትጋግራለህ” አለኝ።'),
  ('7b6284c0-4ca7-57d7-aeb8-54436a4ddeae', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 16, 16, 'ደግሞም እንዲህ አለኝ፥ “የሰው ልጅ ሆይ! የኢየሩሳሌምን እንጀራ በትር እሰብራለሁ፤ በችግር እያሉ እንጀራን በሚዛን ይበላሉ፥ እየደነገጡም ውኃን በልክ ይጠጣሉ፤'),
  ('38b2c553-d3af-50b0-ad93-69381af2e2f9', 'b281e40e-931d-5844-a5f7-cc6888ae0158', '065c575d-a2ee-5bea-a982-1cd61ebb7912', 17, 17, 'ይህም እንጀራንና ውኃን እንዲያጡ፥ እርስ በርሳቸውም እንዲገዳደሉ፥ በኀጢአታቸውም እንዲጠፉ ነው።'),
  ('b542888c-6f1a-520c-a459-72ffafb82011', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 1, 1, '“አንተም የሰው ልጅ ሆይ! ራስን ከሚላጭ ምላጭ ይልቅ የተሳለ ጐራዴን ውሰድ፤ ወስደህም በእርስዋ ራስህንና ጢምህን ተላጭ፤ ሚዛንንም ውሰድ፤ ጠጕሩንም ትከፋፍለዋለህ።'),
  ('28e90dc2-b00c-5974-ae3c-f3632dfe3846', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 2, 2, 'የእስራትህም ወራት በተፈጸመ ጊዜ በከተማዪቱ መካከል ሢሶውን በእሳት ታቃጥላለህ፤ ሢሶውንም ወስደህ ዙሪያውን በጎራዴ ትመታለህ፤ ሢሶውንም ወደ ነፋስ ትበትናለህ፤ እኔም በኋላቸው ጎራዴ እመዝዛለሁ።'),
  ('b23e85d6-54b0-57fe-ae2b-e1d21c241902', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 3, 3, 'ከዚያም በቍጥር ጥቂቶቹን ውሰድ፤ በመጐናጸፊያህም ቋጥራቸው።'),
  ('fab511e2-24d3-58d8-ac6e-a05237f90eb9', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 4, 4, 'ከእነርሱም ደግሞ ወስደህ በእሳት ውስጥ ትጥላለህ፤ በእሳትም ታቃጥላቸዋለህ፤ ከእርስዋም እሳት ይወጣል፤ የእስራኤልንም ቤት ሁሉ እንዲህ ትላቸዋለህ።”'),
  ('e772827e-e4f4-55f5-a6c6-0ad1e87fc753', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 5, 5, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ይህች ኢየሩሳሌም ናት፤ እርስዋንና አውራጃዎችዋንም በአሕዛብ መካከል አድርጌአለሁ፥'),
  ('909d387e-2c7c-5d0b-abd5-24c6ee6dd390', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 6, 6, 'እርስዋም ከአሕዛብ ይልቅ ፍርዴን በኀጢአት ለወጠች፤ በዙሪያዋም ከአሉ ሀገሮች ሁሉ ይልቅ ትእዛዜን ተላለፈች፤ ፍርዴን ጥለዋልና፥ በትእዛዜም አልሄዱምና።'),
  ('e24c224f-52a3-5f90-a129-6a5c23411331', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 7, 7, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፥ “በዙሪያችሁ ላሉት አሕዛብ ሰበብ ሆናችኋልና፥ በትእዛዜም አልሄዳችሁምና፥ ፍርዴንም አልጠበቃችሁምና፥ በዙሪያችሁም እንደ አሉ እንደ አሕዛብ ፍርድ እንኳ አላደረጋችሁምና፥'),
  ('493248ac-dc10-584e-a9f5-dd89f8c98f1b', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 8, 8, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ እኔ ራሴ በአንቺ ላይ ነኝ፤ በአሕዛብም ፊት ፍርድን በመካከልሽ አደርጋለሁ።'),
  ('977894c6-8e29-51f8-a227-f2bd3edcb9de', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 9, 9, 'ስለ ርኵሰትሽም ሁሉ ያልሠራሁትን፥ እርሱንም የሚመስል ደግሞ የማልሠራውን ነገር እሠራብሻለሁ።'),
  ('9971433f-0e22-5346-aa30-08ce5b6a06bb', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 10, 10, 'ስለዚህ በመካከልሽ አባቶች ልጆቻቸውን ይበላሉ፤ ልጆችም አባቶቻቸውን ይበላሉ፤ ፍርድንም አደርግብሻለሁ፤ ከአንቺም የቀረውን ሁሉ ወደ ነፋሳት ሁሉ እበትናለሁ።'),
  ('fee72b1e-2cbf-56d3-a90e-d5f7fa180325', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 11, 11, 'ስለዚህ እኔ ሕያው ነኝና በእድፍሽና በርኵሰትሽ መቅደሴን ስላረከስሽ፥ ስለዚህ በእውነት እኔ አሳንስሻለሁ፥ ይላል ጌታ እግዚአብሔር፤ ዐይኔም አይራራም፤ እኔም ይቅር አልልም።'),
  ('5e77ef25-1f29-5e52-a42c-3045cd7f4110', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 12, 12, 'ከአንቺም ሢሶው በቸነፈር ይሞታል፤ በመካከልሽም በራብ ያልቃል፤ ሢሶውም በዙሪያሽ በሰይፍ ይወድቃል፤ ሢሶውንም ወደ ነፋሳት ሁሉ እበትናለሁ፤ በኋላቸውም ሰይፍን እመዝዛለሁ።'),
  ('5c6222ac-8d26-5761-a26c-28588614412f', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 13, 13, '“ቍጣዬንና መዓቴንም በእነርሱ ላይ እጨርሳለሁ፤ መዓቴንም በፈጸምሁባቸው ጊዜ እኔ እግዚአብሔር በቅንዓቴ እንደ ተናገርሁ ታውቂያለሽ።'),
  ('af271ac8-96a0-50c0-a9cf-74e94daf32ee', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 14, 14, 'በዙሪያሽም በአሉ በአሕዛብ መካከል በሚያልፉም ሁሉ ፊት ከልጆችሽ ጋር አጠፋሻለሁ።'),
  ('375f1d93-604a-563f-a5cf-4cfcf1abb249', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 15, 15, 'በቍጣዬና በመቅሠፍቴ በተበቀልሁሽ ጊዜ በዙሪያሽ በአሉ በአሕዛብ ዘንድ ትጨነቂያለሽ፤ ትደነግጫለሽም፤ እኔ እግዚአብሔር ይህን ተናግሬአለሁ።'),
  ('412804a0-72f6-5986-a11f-cfde8044ac3f', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 16, 16, 'ለማጥፋትም የሆነውን፥ አጠፋችሁም ዘንድ የምሰድደውን የራብ ፍላጻ በላያችሁ በሰደድሁ ጊዜ፥ ራብን እጨምርባችኋለሁ፤ የእንጀራችሁንም በትር እሰብራለሁ።'),
  ('a06233ba-3702-5863-a642-4c29691e8274', 'f463c2a5-7f43-5905-a96c-616fb8c07955', '6362d954-f871-5fc5-a263-81369c1199e4', 17, 17, 'ራብንና ክፉዎችን አራዊት እሰድድብሻለሁ፤ እቀሥፍሻለሁ፤ ልጆችሽንም ያጠፋሉ ቸነፈርና ደምም በአንቺ ላይ ይመጡብሻል፤ ሰይፍንም አመጣብሻለሁ፤ ይከቡሻልም። እኔ እግዚአብሔር ይህን ተናግሬአለሁ።”'),
  ('6c22aa32-1c46-5ac7-aa61-341993ae5b41', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8063ffeb-f963-5d8d-aabb-1010a2689b56', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 2, 2, '“የሰው ልጅ ሆይ፥ ፊትህን ወደ እስራኤል ተራሮች አቅና፤ ትንቢትም ተናገርባቸው።'),
  ('11fc4aa3-c76c-5d1a-a10c-1ed702815a3b', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 3, 3, 'ለእስራኤል ተራሮች የጌታን የእግዚአብሔርን ቃል ስሙ በላቸው፤ ጌታ እግዚአብሔር ለተራሮችና ለኮረብቶች፥ ለምንጮችና ለሸለቆዎች እንዲህ ይላል፦ እነሆ እኔ ሰይፍን አመጣባችኋለሁ፤ የኮረብታ መስገጃዎቻችሁንም አጠፋለሁ።'),
  ('c066db7f-0e75-5b63-a039-2bd6802fcabc', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 4, 4, 'መሠዊያዎቻችሁም ይፈርሳሉ፤ የፀሐይ ምስሎቻችሁም ይሰበራሉ፤ የተገደሉ ሰዎቻችሁንም በጣዖቶቻችሁ ፊት እጥላለሁ።'),
  ('7e3e20db-ed0b-5a0c-a246-e58319c1307a', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 5, 5, 'የእስራኤልንም ልጆች ሬሳዎች በጣዖቶቻቸው ፊት አኖራለሁ፤ አጥንቶቻችሁንም በመሠዊያዎቻችሁ ዙሪያ እበትናለሁ።'),
  ('980e830f-5da1-5e20-adf2-a4e77dd7ebf7', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 6, 6, 'በምትኖሩባትም ስፍራ ሁሉ ከተሞች ይፈርሳሉ፥ የኮረብታ መስገጃዎችም ሁሉ ውድማ ይሆናሉ፤ መሠዊያዎቻችሁም ይፈርሳሉ፤ ባድማም ይሆናሉ፤ ጣዖቶቻችሁም ይሰበራሉ፤ ያልቃሉም፤ የፀሐይ ምስሎቻችሁም ይጠፋሉ፤ ሥራችሁም ይሻራል።'),
  ('b521d633-962e-59b5-a078-4d909c6847c3', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 7, 7, 'ሙታኖቻችሁም በመካከላችሁ ይወድቃሉ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('20163eb0-f80a-559f-ac1c-06e6351084ed', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 8, 8, '“ነገር ግን በሀገሮች በተበተናችሁ ጊዜ ከእናንተ ከአሕዛብ ጦር የዳኑትን አስቀራለሁ።'),
  ('0386f3c0-0927-5945-a4df-08ba7a1919dd', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 9, 9, 'በዚያ በተማረኩበት በአሕዛብ ዘንድ ከእናንተ የዳኑት ያስቡኛል፤ ለሰሰኑበት፥ ከእኔም ለራቁበት ለልቡናቸው፥ ለሰሰኑ፥ ጣዖትንም ለተከተሉ ለዓይኖቻቸው ማልሁ፤ ጣዖቶቻቸውን ሁሉ እንዳመለኩ መጠን ስለ ሥራቸው ክፋት ፊታቸውን ይነጫሉ።'),
  ('345dfaf6-de12-56cb-a4b0-4a7e85492c38', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 10, 10, 'እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ፤ ይህን ክፉ ነገር አደርግባቸው ዘንድ መናገሬ ለከንቱ አይደለም።'),
  ('a99a09c9-d49c-50b5-abff-2904c8ec034a', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 11, 11, 'እግዚአብሔር እንዲህ ይላል፦ በእጅህ አጨብጭብ፤ በእግርህም አሸብሽብ፤ ስለ እስራኤል ቤት ርኵሰት ሁሉ ወዮ ወዮ በል፤ በረኀብና በጦር፥ በቸነፈርም ይጠፋሉ።'),
  ('c485ad08-8487-5262-a48b-0e05342e915f', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 12, 12, 'በሩቅ ያለው በቸነፈር ይሞታል፤ በቅርብም ያለው በሰይፍ ይወድቃል፤ በሀገር የቀረውና የተከበበውም በራብ ይሞታል፤ እንዲሁ መዓቴን እፈጽምባቸዋለሁ።'),
  ('bb51f61b-5cd2-5bac-a330-67770345c581', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 13, 13, 'ሬሳዎቻቸው በጣዖቶቻቸው መካከልና በመሠዊያዎቻቸው ዙሪያ በወደቁ ጊዜ በረዣዥም ኮረብታ ሁሉ፥ በተራሮችም ራሶች ሁሉ፥ በዕንጨቱም ጥላ ሥር ለጣዖቶቻቸው ሁሉ፥ መልካም መዓዛን ባጠኑበት ከቅጠሉ ሁሉ በታች ሬሳዎቻቸው በወደቁ ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('8a85e687-8524-5876-a927-4c0534d1ec3b', '209ee132-4bcf-560f-a1e6-16d33b213b69', 'eb5f7a8a-2dec-5113-a6c5-4cb392017c63', 14, 14, 'እጄንም እዘረጋባቸዋለሁ፤ በሚኖሩበትም ስፍራ ሁሉ ምድሪቱን ከዴብላታ ምድረ በዳ ይልቅ ውድማና በረሃ አደርጋታለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('1c0ef56f-832a-574c-a420-970b2e8cd37b', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('480fd8a3-e059-5fb3-a149-eaa8e9130fdc', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 2, 2, '“አንተ የሰው ልጅ ሆይ! ጌታ እግዚአብሔር ለእስራኤል ምድር እንዲህ ይላል፦ ፍጻሜ በእስራኤል ምድር ላይ መጣ፤ በምድሪቱ በአራቱም ማዕዘን ፍጻሜ መጣ።'),
  ('ead41122-f2ff-5199-a370-b39925d5b3ae', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 3, 3, 'አሁንም ፍጻሜ በአንቺ ላይ ደርሶአል። ቍጣዬንም እሰድድብሻለሁ፤ እንደ መንገድሽም መጠን እፈርድብሻለሁ፤ ጕስቍልናሽንም ሁሉ አመጣብሻለሁ።'),
  ('a33873a5-974d-512b-af01-6b06424890a9', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 4, 4, 'ዐይኔም አይራራልሽም፤ እኔም ይቅር አልልሽም፤ መንገድሽንም አመጣብሻለሁ፤ ርኵሰትሽም በመካከልሽ ነው፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።”'),
  ('d123cea7-8e71-50ab-ad47-821b9417256a', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 5, 5, 'ጌታ እግዚአብሔር እንዲህ ይላል፥ “ክፋት በክፋት ላይ፤ እነሆ ይመጣል።'),
  ('1bc30593-6b5f-52ba-ab59-19ec5b90b8b7', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 6, 6, 'ፍጻሜ መጥቶአል፤ ፍጻሜ መጥቶአል፤ ነቅቶብሻል፤ እነሆ ደርሶአል።'),
  ('0fb65f53-1636-5669-ace1-91642c79d607', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 7, 7, 'በሀገር የምትኖር ሆይ! ስብራትህ ጊዜው ደረሰ፤ ቀኑም ቀረበ፤ የሽብር ቀን ነው እንጂ የተራራ ላይ ዕልልታ አይደለም፤'),
  ('156b4ebc-2615-5eca-a5be-0033323b847e', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 8, 8, 'አሁን በቅርብ መዓቴን አፈስስብሻለሁ፤ ቍጣዬንም እፈጽምብሻለሁ፤ እንደመንገድሽም መጠን እፈርድብሻለሁ፤ ጕስቍልናሽንም ሁሉ አመጣብሻለሁ።'),
  ('7580bd11-49ff-5aa3-a79f-928c237d5bb9', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 9, 9, 'ዐይኔም አይራራም፤ እኔም ይቅር አልልም፤ መንገድሽንም አመጣብሻለሁ፤ ርኵሰትሽም በመካከልሽ ነው፤ እኔም እግዚአብሔር የምቀሥፍ እንደ ሆንሁ ታውቃላችሁ።'),
  ('653669bb-b854-5450-af5f-4d19cfd0a293', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 10, 10, '“እነሆ ቀኑ ደርሶአል፤ እነሆ! የእግዚአብሔር ቀን ወጥታለች፤ ስብራትህ ደርሶአል፤ ብትርም አብባለች፤ ስድብም በዝቶአል።'),
  ('16d88e67-fef9-59f1-a8ee-83d3411679a1', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 11, 11, 'የኀጢአተኛው ምርኩዝ ተሰበረ፤ በደል በዛች፤ ይኸውም በሁከት አይደለም፤ በችኮላም አይደለም።'),
  ('089ce874-6428-5b79-a3ea-f1f8fbef50a4', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 12, 12, 'ጊዜው መጥቶአል፤ ቀኑ እነሆ ቀርቦአል፤ መቅሠፍቷ በሁለንተናዋ መልቶአልና የሚገዛ ደስ አይበለው፤ የሚሸጥም አይዘን።'),
  ('0df60209-e596-552c-ae6f-e88c37117e1b', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 13, 13, 'የገዛው ወደ ሻጩ አይመለስም፤ ዳግመኛም በሕይወት ይኖራል፤ ሁለንተናዋን አይቶአልና አልተመለሰም፤ የሰው ሕይወቱ በዐይኑ ፊት ነው።'),
  ('63aa84f9-f999-5b1d-ada0-b35c5eb5d39c', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 14, 14, '“መለከቱን ንፉ፤ ሁሉንም አዘጋጁ፤ ነገር ግን መዓቴ በብዙዎች ሁሉ ላይ ነውና ወደ ሰልፍ የሚሄድ የለም።'),
  ('8652135c-a174-5057-a4a5-10d5c72ca1ec', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 15, 15, 'ሰይፍ በውጭ፥ ቸነፈርና ራብ በውስጥ አለ፤ በሜዳ ያለው በሰይፍ ይሞታል፤ በከተማም ያለውን ቸነፈርና ራብ ይፈጁታል።'),
  ('8cc6b7a9-22a9-5ae2-aa15-4cd6da8c7da5', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 16, 16, 'ከእነርሱም የሚሸሹ ይድናሉ፤ መብረርን እንደሚማር ርግብም በተራራ ላይ ይሆናሉ፤ እኔም በኀጢአታቸው ሁሉ እገድላለሁ።'),
  ('f5ad40de-6649-50c7-a7a8-2f535d779cff', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 17, 17, 'እጅ ሁሉ ትደክማለች፤ ጕልበትም ሁሉ እንደ ውኃ ይሆናል።'),
  ('5d960147-d5ea-5b4e-ad7f-3d9dc36b5ba8', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 18, 18, 'ማቅም ትታጠቃላችሁ፤ ድንጋጤም ይሸፍናችኋል፤ በፊትም ሁሉ ላይ ሐፍረት ይሆናል፤ በራሳችሁም ሁሉ ላይ ቡሃነት ይሆናል።'),
  ('7feeb07b-a017-5886-a354-d38a299d505e', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 19, 19, 'ብራቸውን በጎዳናዎቹ ላይ ይጥላሉ፤ ወርቃቸውም ይረክሳል፤ በእግዚአብሔር መዓት ቀን ብራቸውና ወርቃቸው አያድናቸውም። እርሱ የኀጢአታቸው እንቅፋት ሆኖአልና ሰውነታቸውን አያጠግቡም፤ ሆዳቸውንም አይሞሉም።'),
  ('3fba62f3-3647-52a5-a116-fc2bdb350d97', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 20, 20, 'የክብሩንም ጌጥ ወደ ትዕቢት ለወጡ፤ የርኵስነታቸውንም ምስሎች አደረጉባት፤ ስለዚህ እኔ በእነርሱ ዘንድ ርኩስ አድርጌአታለሁ።'),
  ('65e7f092-2c75-54c3-abba-e45cfd920d80', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 21, 21, 'በባዕድም እጅ ለንጥቂያ፥ በምድር ኀጢአተኞችም እጅ ለብዝበዛ አሳልፌ እሰጣቸዋለሁ፤ እነርሱም ያረክሱአቸዋል።'),
  ('cc9902c8-29a9-527e-a11d-5270b0dec6dc', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 22, 22, 'ፊቴን ከእነርሱ እመልሳለሁ፤ ሥርዐቴንም ያረክሳሉ፤ ኀይለኞች ይገቡባታል፤ ያረክሱአትማል።'),
  ('50372698-ab4c-5a38-aba6-22888f8614ff', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 23, 23, '“ምድር በአሕዛብ እንደ ተመላች፥ ከተማም በኀጢአት ተመልታለችና ሰንሰለት ሥራ።'),
  ('e9815938-8e1a-54a1-a472-34e95ee1c08d', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 24, 24, 'ከአሕዛብ ዘንድ ከሁሉ የሚከፉትን አመጣለሁ፤ ቤታቸውንም ይወርሳሉ፥ የኀያላንንም ትዕቢት አጠፋለሁ፤ መቅደሶቻቸውም ይረክሳሉ።'),
  ('7bd1d699-58d4-52a0-a592-3e1157dc145d', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 25, 25, 'ጥፋት መጥቶአል፤ ሰላምም ይሻሉ፤ እርሱም አይገኝም።'),
  ('998da52e-1c15-5eb4-a577-0ae102a89c25', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 26, 26, 'ድንጋጤ በድንጋጤ ላይ ይመጣል፤ ወዮታ በወዮታ ላይ ይከተላል፤ ከነቢዩም ዘንድ ራእይን ይሻሉ፤ ከካህኑም ዘንድ ሕግ፥ ከሽማግሌዎችም ዘንድ ምክር ይጠፋል።'),
  ('b8aa5fc1-0309-5d72-a8fe-4e8dc7443cef', '94156dfa-591b-5b22-a58f-9fa96655bc9a', '73f62459-cfee-59bd-aa53-58c6e2c30c73', 27, 27, 'ንጉሡም ያለቅሳል፥ አለቃም ውርደትን ይለብሳል፤ የምድርም ሕዝብ እጅ ትሰላለች፤ እንደ መንገዳቸውም መጠን አደርግባቸዋለሁ፤ በፍርዳቸውም መጠን እፈርድባቸዋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('b40ac53d-f857-561c-a27f-03710ac0257b', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 1, 1, 'እንዲህም ሆነ፤ በስድስተኛው ዓመት በስድስተኛው ወር ከወሩም በአምስተኛው ቀን በቤቴ ተቀምጬ ሳለሁ፥ የይሁዳም ሽማግሌዎች በፊቴ ተቀምጠው ሳሉ፥ በዚያ የጌታ የእግዚአብሔር እጅ በላዬ መጣ።'),
  ('9218497d-90bf-5a90-afef-103871688086', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 2, 2, 'እኔም አየሁ፤ እነሆም ከወገቡ በታች እንደ እሳት የሚመስል የሰው አምሳያ ነበረ፤ ከወገቡም ወደ ላይ እንደ ፀዳል ምሳሌ፥ እንደሚያንጸባርቅ አይነት ነበረ።'),
  ('18bd79ae-8b23-5b3b-aa71-e78073bb03a6', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 3, 3, 'እጅ መሳይንም ዘረጋ፤ በራስ ጠጕሬም ያዘኝ፤ መንፈስም በምድርና በሰማይ መካከል አነሣኝ፤ በእግዚአብሔርም ራእይ ወደ ኢየሩሳሌም ወደ ሰሜን ወደሚመለከተው ወደ ውስጠኛው አደባባይ በር መግቢያ ቅንአት የተባለው ምስል ወደ አለበት አመጣኝ፤'),
  ('02d33210-383c-58da-a35a-f43eb4bd1394', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 4, 4, 'እነሆም ቀድሞ በሜዳ እንደ አየሁት ራእይ የእስራኤል አምላክ ክብር በዚያ ነበረ።'),
  ('ca087b76-38e2-5a7c-a6e7-64ce665d7f95', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 5, 5, 'እርሱም፥ “የሰው ልጅ ሆይ! ዐይንህን ወደ ሰሜን መንገድ አንሣ” አለኝ። ዐይኔንም ወደ ሰሜን መንገድ አነሣሁ፤ እነሆም በመሠዊያው በር በሰሜን በኩል በመግቢያው ይህ የቅንዓት ምስል ነበረ። ከዚያም ወደ ምሥራቅ ያስገባል።'),
  ('0573c6d8-a1f6-5b50-a954-f2a3efba9078', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 6, 6, 'እርሱም፥ “የሰው ልጅ ሆይ! የሚያደርጉትን ከመቅደሴ ያርቁኝ ዘንድ የእስራኤል ቤት በዚህ የሚያደርጉትን፥ ታላቁን ርኵሰት ታያለህን? ደግሞም ተመልሰህ ከዚህ የበለጠ ታላቅ ርኵሰት ታያለህ” አለኝ።'),
  ('0167651d-eddb-517a-a842-186369de7c7f', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 7, 7, 'ወደ አደባባዩም መግቢያ አስገባኝ፤ በአየሁም ጊዜ፥ እነሆ በግንቡ ውስጥ ፉካ ነበረ።'),
  ('126ec878-d775-5c7d-a33e-9ce10f43d370', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 8, 8, 'እርሱም፥ “የሰው ልጅ ሆይ! ግንቡን ንደለው” አለኝ፤ ግንቡንም በነደልሁት ጊዜ ደጃፍ አገኘሁ።'),
  ('607df9ba-f137-56c9-ab4e-6b937ff2f520', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 9, 9, 'እርሱም፥ “ግባ፤ በዚህ የሚያደርጉትን ክፉውን ርኵሰት እይ” አለኝ።'),
  ('e6d8a99a-9591-5894-a41f-4ce28272d6a4', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 10, 10, 'እኔም ገባሁና፥ እነሆ በግንቡ ዙሪያ ላይ የተንቀሳቃሾች አዕዋፍና እንስሳትን ምሳሌ ከንቱና ርኩስ የእስራኤልንም ቤት ጣዖታት ሁሉ ተሥለው አየሁ።'),
  ('4eed35db-8a9d-50b8-ad7d-7b0268762400', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 11, 11, 'በፊታቸውም ከእስራኤል ቤት ሽማግሌዎች ሰባ ሰዎችና የሳፋን ልጅ ያእዛንያ ቆመው ነበር፤ ሰውም ሁሉ እያንዳንዱ በእጁ ጥናውን ይዞ ነበር፥ የዕጣኑም ጢስ ሽታ ይወጣ ነበር።'),
  ('abeab943-1e1f-50ad-ab43-353c985f6e98', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 12, 12, 'እርሱም፥ “የሰው ልጅ ሆይ! የእስራኤል ቤት ሽማግሌዎች በስውር እያንዳንዱ በሥዕሉ ቤት የሚያደርጉትን አይተሃልን? እነርሱ እግዚአብሔር አያየንም፤ እግዚአብሔር ምድሪቱን ትቶአታል ይላሉና” አለኝ።'),
  ('70c85cf5-b497-51d0-a21d-45453f8cd24b', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 13, 13, 'እርሱም፥ “ከዚያ የበለጠውን የሚያደርጉትን ታላቅ ኀጢአት ታይ ዘንድ ና” አለኝ።'),
  ('6efeeaa1-ecdc-5883-ab77-df2225f68c36', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 14, 14, 'ወደ ሰሜንም ወደሚመለከተው ወደ እግዚአብሔር ቤት በር አመጣኝ፤ እነሆም፥ ሴቶች ለተሙዝ እያለቀሱ በዚያ ተቀምጠው ነበር።'),
  ('7fbd9951-4a42-560a-a506-02a77c82d6b6', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 15, 15, 'እርሱም፥ “የሰው ልጅ ሆይ! ይህን አይተሃልን? ደግሞ ከዚህ የበለጠ ርኵሰት ታያለህ” አለኝ።'),
  ('a4749a04-1fb4-5555-aee0-1216b7a5e5d8', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 16, 16, 'ወደ እግዚአብሔር ቤት ወደ ውስጠኛው አደባባይ አመጣኝ፤ እነሆም በእግዚአብሔር መቅደስ መግቢያ ፊት በወለሉና በመሠዊያው መካከል ሃያ አምስት የሚያህሉ ሰዎች ነበሩ፤ ጀርባቸውም ወደ እግዚአብሔር መቅደስ፥ ፊታቸውም ወደ ምሥራቅ ነበረ፤ እነርሱም ወደ ምሥራቅ ለፀሐይ ይሰግዱ ነበር።'),
  ('35d07b7a-aa29-573d-af33-bb4978dd60d4', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 17, 17, 'እርሱም፥ “የሰው ልጅ ሆይ! ይህን አይተሃልን? በዚህ የሚያደርጉትን ይህን ኀጢአት ያደርጉ ዘንድ ለይሁዳ ቤት ጥቂት ነገር ነውን? ምድሪቱን በኀጢአት ሞልተዋታል፤ ያስቈጡኝም ዘንድ ተመልሰዋል፤ እነሆም ቅርንጫፉን አስረዝመዋል። ይዘባበታሉም።'),
  ('88a9ac22-ce92-5d01-ab79-f6b524ee5029', '9784b88c-0412-595c-a335-9c7c55723388', 'aec850a5-0314-5c51-a42f-98f37de64ac0', 18, 18, 'ስለዚህ እኔ ደግሞ በመዓት እሠራለሁ፤ ዐይኔ አይራራም፤ እኔም ይቅርታ አላደርግም፤ ወደ ጆሮዬም በታላቅ ድምፅ ቢጮኹ አልሰማቸውም” አለኝ።'),
  ('8a8421c0-2fd3-5773-a854-a24f51d3eafd', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 1, 1, 'እርሱም፥ “እያንዳንዳቸው የሚያጠፉባት መሣሪያን በእጃቸው ይዘው ከተማዪቱን የሚቀሥፉ ይቅረቡ” ብሎ በታላቅ ድምፅ በጆሮዬ ጮኸ።'),
  ('0cc5fd3e-bb4e-57cf-a631-42c60090af73', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 2, 2, 'እነሆም እያንዳንዳቸው ገጀሞ መሣሪያ በእጃቸው ይዘው ስድስት ሰዎች ወደ ሰሜን ከሚመለከተው ከላይኛው በር መንገድ መጡ፤ በመካከላቸውም የበፍታ ልብስ የለበሰና የሰንፔር መታጠቂያ በወገቡ የታጠቀ አንድ ሰው ነበረ። እነርሱም ገብተው በናሱ መሠዊያ አጠገብ ቆሙ።'),
  ('db43124c-ec48-54f6-ae39-7862fb700e24', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 3, 3, 'የእስራኤልም አምላክ ክብር በበላዩ ከነበረበት ኪሩብ ተነሥቶ ወደ ቤቱ መድረክ ሄዶ ነበር፤ በፍታም የለበሰውን፥ የሰንፔር መታጠቂያም በወገቡ የታጠቀውን ሰው ጠራ።'),
  ('9bf2803f-9e4f-5b7e-a632-efb8278553d2', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 4, 4, 'እግዚአብሔርም፥ “በከተማዪቱ በኢየሩሳሌም መካከል እለፍ፥ በመካከልዋም ስለ ተሠራው ኀጢአት ሁሉ በሚያለቅሱና በሚተክዙ ሰዎች ግንባር ላይ ምልክት ጻፍ አለው።'),
  ('77fe16e8-721e-5c07-ac4e-5dbf3c42005f', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 5, 5, 'እኔም እየሰማሁ ለሌሎቹ፦ በስተኋላው ወደ ከተማው ግቡ፤ ግደሉም፤ ዐይናችሁ አይራራ፤ ይቅርም አትበሉ፤'),
  ('376c5e34-ee53-5ce0-acee-e2fb85677072', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 6, 6, 'ሽማግሌውንና ጎበዙን፥ ድንግሊቱንም፥ ሕፃናቱንና ሴቶቹን፥ ፈጽማችሁ ግደሉ፤ ነገር ግን ምልክቱ ወደ አለበት ሰው ሁሉ አትቅረቡ፤ በመቅደሴም ጀምሩ” አላቸው። በቤቱም አንጻር ባሉ ሽማግሌዎች ጀመሩ።'),
  ('a06bc116-950d-57b2-a610-89a49f4f44cd', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 7, 7, 'እርሱም፥ “ቤቱን አርክሱ፤ ወጥታችሁ ግደሉ፤ በሙታንም መንገዶችን ሙሉ” አላቸው።'),
  ('f35a8568-92f1-5037-acfa-10dcf7e74502', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 8, 8, 'ሲገድሉም እኔ ብቻዬን ቀርቼ ሳለሁ በግንባሬ ተደፍቼ፥ “ጌታ እግዚአብሔር ሆይ! ወዮ! መዓትህን በኢየሩሳሌም ላይ ስታፈስስ የእስራኤልን ቅሬታ ሁሉ ታጠፋለህን?” ብዬ ጮኽሁ።'),
  ('434fc829-b833-51c2-ae68-60fe7cda74f7', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 9, 9, 'እርሱም፥ “የእስራኤልና የይሁዳ ቤት ኀጢአት እጅግ በዝቶአል፤ ምድሪቱም በብዙ አሕዛብ እንደ ተመላች ከተማዪቱም እንዲሁ ዓመፅንና ርኵሰትን ተሞልታለች፤ እነርሱም፦ እግዚአብሔር ምድሪቱን ትቶአታል፤ እግዚአብሔርም አያይም” ብለዋል።'),
  ('56e2f8d4-e551-5154-a941-f3c765dc26be', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 10, 10, '“እኔም ደግሞ በዐይኔ አልራራም፤ ይቅርታም አላደርግም፤ መንገዳቸውንም በራሳቸው ላይ እመልሳለሁ” አለኝ።'),
  ('52e11859-3f8f-5847-a4d9-ee52d732939d', '91b02ff4-0993-567b-a7f3-75e7fafa1a01', '346753d1-30f2-56a2-a8e5-db4e988511fa', 11, 11, 'እነሆም በፍታ የለበሰው፥ የሰንፔር መታጠቂያም በወገቡ የታጠቀው ሰው መጣ፥ “ያዘዝኸኝንም አድርጌአለሁ” ብሎ በቃሉ መለሰ።'),
  ('c4153062-c319-5c28-aa0c-d27aa6cfb8b9', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 1, 1, 'እኔም አየሁ፤ እነሆም በኪሩቤል ራስ ላይ ባለው ጠፈር በላያቸው እንደ ሰንፔር ድንጋይ ያለ ዙፋን የሚመስል መልክ ተገለጠ።'),
  ('4c07a25a-5e11-5cf7-ab74-e9043832f930', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 2, 2, 'በፍታም የለበሰውን ሰው፥ “በመንኰራኵሮች መካከል በኪሩብ በታች ግባ፤ ከኪሩቤልም መካከል ከአለው እሳት ፍም እጆችህን ሙላ፤ በከተማዪቱም ላይ በትነው” ብሎ ተናገረው። እኔም እያየሁ ገባ።'),
  ('1da95545-325d-58f8-aece-3c33859f2b0e', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 3, 3, 'ሰውየውም ሲገባ ኪሩቤል በቤቱ ቀኝ በኩል ቆመው ነበር፤ ደመናውም ውስጠኛውን አደባባይ ሞላ።'),
  ('2f53fc05-7369-5a50-ae41-2a392020a44c', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 4, 4, 'የእግዚአብሔር ክብርም ከኪሩቤል ወጥቶ በቤቱ መድረክ ላይ ቆመ፤ ቤቱም በደመናው ተሞላ፤ አደባባዩም በእግዚአብሔር ክብር ፀዳል ተሞላ።'),
  ('c284ac20-bcd6-54f8-a465-317d93c592be', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 5, 5, 'የኪሩቤልም የክንፎቻቸው ድምፅ ሁሉን የሚችል አምላክ እንደሚናገረው ያለ ድምፅ እስከ ውጭው አደባባይ ድረስ በሩቅ ይሰማ ነበር።'),
  ('34988e8a-e662-5999-a376-f3e28d9c4443', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 6, 6, 'የተቀደሰ በፍታም የለበሰውን ሰው፥ “ከመንኰራኵሮቹ ከኪሩቤል መካከል እሳት ውሰድ” ብሎ በአዘዘው ጊዜ እርሱ ገብቶ በመንኰራኵር አጠገብ ቆመ።'),
  ('fea59b9b-6f44-532a-acab-90d8c0a6181e', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 7, 7, 'ከኪሩቤል መካከልም አንዱ ኪሩብ እጁን በኪሩቤል መካከል ወደ አለው እሳት ዘርግቶ ከዚያ እሳት ወሰደ፤ የተቀደሰ በፍታም በለበሰው ሰው እጅ አኖረው፤ እርሱም ይዞ ወጣ።'),
  ('4b5ccd6c-0f91-5faa-ae20-e50b7d9f874a', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 8, 8, 'ኪሩቤልንም አየሁ፤ ከክንፎቻቸውም በታች የሰው እጅ መሳይ አለ።'),
  ('aee9109c-3e65-517f-aec0-c2139d5e012a', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 9, 9, 'እኔም አየሁ፤ እነሆም በኪሩቤል አጠገብ አራት መንኰራኵሮች ነበሩ፤ አንዱ መንኰራኵር በአንዱ ኪሩብ፥ አንዱ መንኰራኵር በአንዱ ኪሩብ አጠገብ ነበረ። የመንኰራኵሮቹም መልክ እንደ ቢረሌ ድንጋይ ነበረ።'),
  ('ced5dc32-c3ea-5c03-ae34-233aef516bb7', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 10, 10, 'የአራቱም መልክ አንድ ይመስል ነበር፤ መልካቸውም በመንኰራኵር ውስጥ እንደ አለ መንኰራኵር ነበረ።'),
  ('322732c4-ac80-599e-ae0b-dcd66e6f9254', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 11, 11, 'ሲሔዱም በአራቱ ጎድናቸው ይሄዱ ነበር። ሲሄዱም ወዲያና ወዲህ አይሉም ነበር፤ መጀመሪያው ወደሚያመለክትበት ስፍራ ይሄዱ ነበር፤ ሲሄዱም ወዲያና ወዲህ አይሉም ነበር።'),
  ('b3c59e0c-8af5-521c-ad24-505c84bac03a', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 12, 12, 'ገላቸውም ሁሉ፥ ጀርባቸውም፥ እጆቻቸውም፤ ክንፎቻቸውም፥ መንኰራኵሮቹም፤ ለአራቱ የነበሩ መንኰራኵሮች በዙሪያቸው ዐይኖች ተሞልተው ነበር።'),
  ('dfa2071f-4067-53e4-af2d-60888c4baf28', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 13, 13, 'አራቱም መንኰራኵሮች እኔ እየሰማሁ ጌልጌል ተብለው ተጠሩ።'),
  ('dfafed45-1253-531f-a149-fe4fb958898e', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 14, 14, 'ለእያንዳንዱም አራት አራት ፊት ነበሩት፤ አንደኛው ፊት የኪሩብ ፊት፥ ሁለተኛውም የሰው ፊት፥ ሦስተኛው የአንበሳ ፊት፥ አራተኛውም የንስር ፊት ነበረ።'),
  ('092feacd-f219-52ac-adaf-f053b6cc41d9', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 15, 15, 'እነዚህም በኮቦር ወንዝ በእንስሶች አምሳል ያየኋቸው ኪሩቤል በረሩ።'),
  ('908378eb-6769-59cb-ac7d-5523582a31f1', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 16, 16, 'ኪሩቤልም ሲሄዱ መንኰራኵሮቹ ከእነርሱ ጋር ተያይዘው ይሄዱ ነበር፤ ኪሩቤልም ይበሩ ዘንድ ክንፋቸውን ከምድር በሚያነሡ ጊዜ ከእነርሱ ጋር የተያያዘ መንኰራኵራቸው አይመለስም ነበር።'),
  ('723b8916-aa5c-5084-a9d2-957e058c0939', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 17, 17, 'የሕይወት መንፈስ በውስጣቸው ነበርና እነዚህ ሲቆሙ እነዚያም ይቆሙ ነበር፤ እነዚህም ሲበርሩ፥ እነዚያ ከእነርሱ ጋር ይበርሩ ነበር።'),
  ('51b77044-ed62-5094-a613-68c728869a03', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 18, 18, 'የእግዚአብሔርም ክብር ከቤቱ መድረክ ላይ ወጥቶ በኪሩቤል ላይ ተቀመጠ።'),
  ('bafc2565-a602-5693-abee-9c918d6b9f66', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 19, 19, 'ኪሩቤልም ክንፎቻቸውን ዘረጉ፤ እኔም እያየሁ ከምድር በረሩ፤ በወጡም ጊዜ መንኰራኵሮቹ በአጠገባቸው ነበሩ፤ፊት ለፊት በአለው በእግዚአብሔር ቤት መግቢያ በር ዳርቻ ቆሙ፤ የእስራኤልም አምላክ ክብር ከእነርሱ ጋራ በላያቸው ነበረ።'),
  ('d61e447b-9fe5-53bb-a1e8-7c46816e297d', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 20, 20, 'ይህ በኮቦር ወንዝ ከእስራኤል አምላክ በታች ያየሁት እንስሳ ነው፤ ኪሩቤልም እንደ ነበሩ ዐወቅሁ።'),
  ('0d573c9a-2fe7-503e-ad39-39fdc417d295', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 21, 21, 'ለእያንዳንዱ አራት አራት ፊት፥ ለእያንዳንዱም አራት አራት ክንፍ ነበሩት፤ የሰውም እጅ አምሳያ ከክንፎቻቸው በታች ነበረ።'),
  ('6096049b-b194-595b-af50-065c998e84ae', '579ab8cd-9841-5472-ab6f-191810c21de3', 'eeccc4c8-6b06-5b8c-a35a-a27a4e01a57b', 22, 22, 'ፊቶቻቸውም በኮቦር ወንዝ ከእስራኤል አምላክ ክብር በታች ያየኋቸውን ፊቶች ይመስሉ ነበር፤ እነርሱና መልካቸውም እንዲሁ ነበረ፤ እያንዳንዱም አቅንቶ ወደ ፊት ይሄድ ነበር።'),
  ('3448f71c-8475-5bf7-a4a6-8760d56de347', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 1, 1, 'መንፈስም አነሣኝ፤ ወደ ምሥራቅም አንጻር ወደሚያሳየው ወደ እግዚአብሔር ቤት በር ወሰደኝ። እነሆም በበሩ መግቢያ ሃያ አምስት ሰዎች ነበሩ፤ በመካከላቸውም የሕዝቡን አለቆች የዓዙርን ልጅ ያእዛንያንና የበናያስ ልጅ ፈላጥያን አየሁ።'),
  ('e5c5d139-6cd6-559c-a204-b8c1e62df749', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 2, 2, 'እርሱም እንዲህ አለኝ፥ “የሰው ልጅ ሆይ! እነዚህ ከንቱን የሚያስቡ፥ በዚችም ከተማ ክፉን ምክር የሚመክሩ ሰዎች ናቸው።'),
  ('5cf3fb31-55a2-59d6-a56f-32984ca058a1', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 3, 3, 'እነርሱም፦ በውኑ ቤቶች በድንገት የሚሠሩ አይደለምን? ይህች ከተማ ድስት እኛም ሥጋ ነን ብለዋል።'),
  ('538a38f6-3997-58a5-a77d-11d6fa604f8d', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 4, 4, 'ስለዚህ የሰው ልጅ ሆይ! ትንቢት ተናገርባቸው፤ ትንቢት ተናገር።”'),
  ('c8ece253-9ae1-5df0-a40d-15dff1f0a44c', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 5, 5, 'የእግዚአብሔርም መንፈስ በላዬ መጣ፤ እንዲህም አለኝ፥ “እግዚአብሔር እንዲህ ይላል ብለህ ተናገር፦ የእስራኤል ቤት ሆይ! ይህን ነገር ተናግራችኋል፤ እኔም የሰውነታችሁን በደል አውቃለሁ።'),
  ('4b8df263-ffb2-50ca-aa27-2f596dc7fc03', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 6, 6, 'በዚህች ከተማ ውስጥ ግዳዮቻችሁን አብዝታችኋል፤ በጎዳናዎችዋም ሙታናችሁን ሞልታችኋል።'),
  ('226f6f1d-d114-577e-aee1-de3829f30f28', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 7, 7, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ በመካከልዋ ያኖራችኋቸው ግዳዮቻችሁ እነርሱ ሥጋ ናቸው፤ ይህችም ከተማ ድስት ናት፤ እናንተን ግን ከመካከልዋ አወጣችኋለሁ።'),
  ('6f429dc8-d4e6-56a1-a10c-208ca10aa3cf', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 8, 8, 'ሰይፍን ትፈራላችሁ፤ እኔም ሰይፍን አመጣባችኋለሁ፤ ይላል ጌታ እግዚአብሔር።'),
  ('b03ebfca-79aa-5333-abbf-45fee87d882f', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 9, 9, 'ከመካከልዋም አወጣችኋለሁ፤ በባዕዳንም እጅ አሳልፌ እሰጣችኋለሁ፤ በላያችሁም ፍርድን አደርጋለሁ።'),
  ('dc43aa81-198d-5ff5-a226-4b69df1c9a85', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 10, 10, 'በሰይፍ ትወድቃላችሁ፤ በእስራኤልም ተራሮች እፈርድባችኋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('b589c392-eef8-5486-a037-f56ce6ffe722', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 11, 11, 'ይህች ከተማ ድስት አትሆንላችሁም፤ እናንተም በመካከልዋ ሥጋ አትሆኑም፤ እኔም በእስራኤል ተራሮች እፈርድባችኋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('b34080cb-d7d7-5fd3-af08-e723d21bb0e0', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 12, 12, 'በትእዛዜ አልሄዳችሁምና፥ ፍርዴንም አላደረጋችሁምና፥ በዙሪያችሁም እንደሚኖሩት እንደ አሕዛብ ሕግ አድርጋችኋል።”'),
  ('60c17db8-a406-5e23-a165-f9476ecd5903', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', '9ee088d0-29cf-5c51-a0be-80c5c874ab80', 13, 13, 'ትንቢትም በተናገርሁ ጊዜ የበናያስ ልጅ ፈላጥያ ሞተ፤ እኔም በግንባሬ ተደፍቼ፥ “ጌታ እግዚአብሔር ሆይ! ወዮ! ወዮልኝ! በውኑ የእስራኤልን ቅሬታ ፈጽመህ ታጠፋለህን?” ብዬ በታላቅ ድምፅ ጮኽሁ።'),
  ('c1e5b59d-3292-5587-a4d7-53fc3ed16894', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 1, 14, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('9aaa778a-b88a-548b-a9ff-8a331d43c2ff', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 2, 15, '“የሰው ልጅ ሆይ! በኢየሩሳሌም የሚኖሩ፦ ከእግዚአብሔር ዘንድ ራቁ፤ ይህች ምድር ርስት ሆና ለእኛ ተሰጥታለች የሚሉአቸው ወንድሞችህና ዘመዶችህ፥ የምርኮ ሰዎችህም ሁሉ፥ የእስራኤልም ቤት ሁሉ ያልቃሉ።'),
  ('ca6f496d-efce-5ede-a834-95814f3234a2', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 3, 16, 'ስለዚህ፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ እኔ ወደ አሕዛብ አርቄአቸዋለሁ፤ ወደ ሀገሮችም እበትናቸዋለሁ፤ ይሁን እንጂ በመጡባቸው ሀገሮች በእነዚያ ትንሽ መቅደስ እሆናቸዋለሁ በል።'),
  ('6fa605fc-6048-5467-a93b-756fdf75c08e', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 4, 17, 'ስለዚህም በል፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ከአሕዛብ ዘንድ እቀበላቸዋለሁ፤ ከበተንሁባቸውም ሀገሮች እሰበስባቸዋለሁ፤ የእስራኤልንም ምድር እሰጣቸዋለሁ።'),
  ('2aab2e79-0793-5e11-ac83-aaa0e395e2bb', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 5, 18, 'ወደዚያም ይመጣሉ፤ በደልንና ርኵሰትንም ሁሉ ከእርስዋ ያስወግዳሉ።'),
  ('4561f5f9-e2e7-5333-a629-085a3710e581', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 6, 19, 'ሌላ ልብ እሰጣቸዋለሁ፤ በውስጣቸውም አዲስ መንፈስ አሳድራለሁ፤ ከሥጋቸውም ውስጥ የድንጋዩን ልብ አወጣለሁ፤ የሥጋንም ልብ እሰጣቸዋለሁ፤'),
  ('9b15a737-2af1-5d7c-adf2-5c57db407352', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 7, 20, 'በትእዛዜም ይሄዱ ዘንድ፥ ፍርዴንም ይጠብቁና ያደርጉ ዘንድ እነርሱ ሕዝብ ይሆኑኛል፥ እኔም አምላክ እሆናቸዋለሁ።'),
  ('fae6ed85-f9e8-5833-ab57-5fdfc246fddf', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'c72cd948-06f4-5393-a99d-1cb923bbac29', 8, 21, 'ጣዖት በሚያመልኩበት ልባቸውና በኀጢአታቸው እንደ ልባቸው ቢሄዱ መንገዳቸውን በራሳቸው ላይ እመልሳለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('3b6f2358-2adf-5528-ae53-d4aea2ec04d2', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'e4843b8c-0f5a-5d82-a318-9b6cb52c73b0', 1, 22, 'ኪሩቤልም ክንፎቻቸውን ዘረጉ፥ መንኰራኵሮችም በአጠገባቸው ነበሩ፤ የእስራኤልም አምላክ ክብር በላያቸው ነበረ።'),
  ('ebc70003-34df-5c71-abd5-42050c0398a0', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'e4843b8c-0f5a-5d82-a318-9b6cb52c73b0', 2, 23, 'የእግዚአብሔርም ክብር ከከተማዪቱ መካከል ተነሥቶ በከተማዪቱ ምሥራቅ በኩል በአለው ተራራ ላይ ቆመ።'),
  ('f6af1fc3-930b-5b3a-a732-1aed2b8aab95', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'e4843b8c-0f5a-5d82-a318-9b6cb52c73b0', 3, 24, 'መንፈስም አነሣኝ፤ በእግዚአብሔርም መንፈስ በራእይ ወደ ከላውዴዎን ምድር ወደ ምርኮኞቹ አመጣኝ።'),
  ('df860dcd-1630-598f-a6bf-2eb860f1fcaa', '1c7b5993-ec0b-53e5-a18e-a8b5090be17c', 'e4843b8c-0f5a-5d82-a318-9b6cb52c73b0', 4, 25, 'ያየሁትም ራእይ ከእኔ ወጣ። እግዚአብሔርም ያሳየኝን ነገር ሁሉ ለምርኮኞች ተናገርሁ።'),
  ('8416c9b6-b66c-5742-a881-f8676bb2a726', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('16b269ea-f1ff-56f3-ae5a-4c1601dfd245', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 2, 2, '“የሰው ልጅ ሆይ! በዐመፀኛ ቤት መካከል ተቀምጠሃል፤ እነርሱ ያዩ ዘንድ ዐይን አላቸው ነገር ግን አያዩም፤ ይሰሙም ዘንድ ጆሮ አላቸው፤ ነገር ግን አይሰሙም፤ እነርሱ ዐመፀኛ ቤት ናቸውና።'),
  ('ca46c5aa-1599-55c4-afc1-9313beb4eabe', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 3, 3, 'አንተም የሰው ልጅ ሆይ! የስደተኛ እክት አዘጋጅ፤ በፊታቸውም ቀን ለቀን ተማረክ፤ በፊታቸውም ከስፍራ ወደ ሌላ ስፍራ ተማርከህ ሂድ፤ እነርሱም ዐመፀኛ ቤት እንደ ሆኑ ምንአልባት ያስተውሉ ይሆናል።'),
  ('b66a0ae4-454c-5ffb-aeca-7697764c83f7', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 4, 4, 'ቀን ለቀንም በፊታቸው እክትህን እንደ ስደተኛ እክት አውጣው፤ በማታም ጊዜ በዐይናቸው እያዩህ ስደተኞች እንደሚወጡ እንዲሁ ውጣ።'),
  ('9395b92f-fb18-5070-a9fd-03eb35c57ae4', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 5, 5, 'በፊታቸውም ግንቡን ነድለህ በዚያ ውጣ።'),
  ('41e17ac6-5cf2-519f-a11c-c9afe9235e1b', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 6, 6, 'ለእስራኤልም ቤት ምልክት አድርጌሃለሁና በፊታቸው ዕቃህን በትከሻህ ላይ አንግተው፤ በጨለማም ተሸክመህ ውጣ፤ ምድሪቱንም እንዳታይ ፊትህን ሸፍን።”'),
  ('5fcccecd-b20a-5bdf-a0a8-51260f5d2dd7', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 7, 7, 'እንዳዘዘኝም አደረግሁ፤ ቀን ለቀንም እክቴን እንደ ስደተኛ እክት አወጣሁ፤ በማታም ጊዜ ግንቡን በእጄ ነደልሁ፤ በጨለማም አወጣሁት፤ በፊታቸውም በትከሻዬ ላይ አንግቼ ተሸከምሁት።'),
  ('bc29203c-516e-5c66-a563-d01626baedbe', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 8, 8, 'በነጋውም የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('e6fc666e-d75e-5898-a20a-2fa76efa4a03', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 9, 9, '“የሰው ልጅ ሆይ! ዐመፀኛ ቤት የእስራኤል ቤት፦ የምታደርገው ምንድር ነው? አላሉህምን?'),
  ('f87994af-2e32-5c34-a704-9f1db3d8c548', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 10, 10, 'አንተም፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ይህ ሸክም በኢየሩሳሌም በሚኖረው አለቃ ላይ፥ በመካከላቸውም በሚኖሩት በእስራኤል ቤት ሁሉ ላይ ነው በላቸው።'),
  ('52e27354-6d07-5a1c-ad2a-db2d90cc59b8', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 11, 11, 'ደግሞም፦ እኔ ምልክታችሁ ነኝ፤ እኔ እንዳደረግሁ እንዲሁ ይደረግባቸዋል፥ እነርሱንም ማርከው ይወስዷቸዋል በል።'),
  ('385ee54d-94ab-5d8f-a7b4-0426fb337bb7', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 12, 12, 'በመካከላቸውም የሚኖረው አለቃ በትከሻው ላይ አንግቶ በጨለማ ይወጣል፤ በዚያ ያወጡ ዘንድ ግንቡን ይነድላሉ፤ በዐይኑም ምድርን እንዳያይ ፊቱን ይሸፍናል።'),
  ('9d512de4-7d2b-5cf3-a094-cc65b9849297', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 13, 13, 'መረቤንም በእርሱ ላይ እዘረጋለሁ፤ በወጥመዴም ይያዛል፤ ወደ ከለዳውያንም ምድር ወደ ባቢሎን አመጣዋለሁ፤ ሆኖም አያያትም፤ በዚያም ይሞታል።'),
  ('98e80fb5-45cc-55ba-a7b9-c3bf078a66f1', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 14, 14, 'የሚረዱትንም፥ በዙሪያው ያሉትን ሁሉ፥ ጭፍሮቹንም ሁሉ ወደ ነፋሳት ሁሉ እበትናቸዋለሁ፤ በኋላቸውም ሰይፍን እመዝዛለሁ።'),
  ('1485657d-5361-54df-a453-8d76bff5b21e', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 15, 15, 'በአሕዛብም መካከል በምበትናቸው ጊዜ፥ በሀገሮችም በምዘራቸው ጊዜ፥ እኔ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('8a36925f-b655-58eb-aeab-bb2e8875c94f', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 16, 16, 'በሚሄዱባቸውም አሕዛብ መካከል ርኵሰታቸውን ሁሉ ይናገሩ ዘንድ ከሰይፍና ከራብ፥ ከቸነፈርም ጥቂቶች ሰዎችን ከእነርሱ አስቀራለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ያውቃሉ።”'),
  ('db60196d-61f8-5075-ae84-a332eb407a26', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 17, 17, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('b75d7af6-53d8-58e6-ab16-8598e677cce7', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 18, 18, '“የሰው ልጅ ሆይ! እንጀራህን በመታወክ ብላ፤ ውኃህንም በፍርሃትና በድንጋጤ ጠጣ፤'),
  ('6145813c-1dfc-533a-a332-6fe41787f716', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 19, 19, 'ለምድሪቱም ሕዝብ፦ ጌታ እግዚአብሔር በኢየሩሳሌም ስለሚኖሩ ስለ እስራኤል ምድርም እንዲህ ይላል፦ የሚኖሩባት ሁሉ በዐመፅ ይኖራሉና ምድሪቱ በመላዋ ትጠፋ ዘንድ እንጀራቸውን በችግር ይበላሉ፤ ውኃቸውንም በድንጋጤ ይጠጣሉ።'),
  ('5aa8da3e-489b-590c-a39f-12dac7155da3', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 20, 20, 'ሰዎች የሚኖሩባቸው ከተሞች ይጠፋሉ፤ ምድሪቱም ውድማ ትሆናለች፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ በላቸው።”'),
  ('9ed528da-02f3-50d0-a6c6-327bc22a7b64', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 21, 21, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('2bca53a4-a35f-5f30-ab33-20075a27d106', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 22, 22, '“የሰው ልጅ ሆይ! በእስራኤል ምድር፦ ዘመኑ ረዝሞአል፤ ራእዩም ሁሉ ጠፍቶአል የምትሉት ምሳሌው ምንድን ነው?'),
  ('7c927c3e-a5c8-58f1-a702-91b7f0bc8caa', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 23, 23, 'ስለዚህ እንዲህ በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ይህን ምሳሌ አስቀረዋለሁ፤ በእስራኤልም ዘንድ ደግሞ ምሳሌ አድርገው አይናገሩትም፤ አንተ ግን፦ ዘመኑና የራእዩ ሁሉ ነገር ቀርቦአል በላቸው።'),
  ('1e6035f3-da23-53f4-a469-0aca88acf377', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 24, 24, 'ከዚህም በኋላ በእስራኤል ቤት መካከል ከንቱ ራእይና ውሸተኛ ምዋርት አይሆንም።'),
  ('bb60658b-370a-584c-a220-89b3dea5b7a3', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 25, 25, 'እኔ እግዚአብሔር ነኝ፤ እናገራለሁ፤ የምናገረውም ቃል ይፈጸማል፤ ደግሞም አይዘገይም፤ እናንተ ዐመፀኛ ቤት ሆይ! በዘመናችሁ ቃሌን እናገራለሁ፤ እፈጽመውማለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('3db8117e-1057-533b-a04d-4691cd6f1607', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 26, 26, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('89df765d-db89-538f-a7c6-caf7fbbfb6c9', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 27, 27, '“የሰው ልጅ ሆይ! ዐመፀኛው የእስራኤል ቤት፦ ይህቺ የሚያያት ራእይ ለብዙ ዘመን ናት፤ እርሱም ለሩቅ ወራት ትንቢትን ይናገራል” ይላሉ።'),
  ('b74af950-ff7b-5aa0-ac9d-69ea8af8d4ad', '95acb6cf-e736-5a75-a034-3afd37237af4', '25642590-0400-536e-a1af-8e9b7b7235a9', 28, 28, 'ስለዚህ በላቸው፥ “ጌታ እግዚአብሔር እንዲህ ይላል፦ የምናገረው ቃል ይፈጸማል እንጂ ከቃሌ ሁሉ ደግሞ የሚዘገይ የለም፥” ይላል ጌታ እግዚአብሔር።'),
  ('d3caceb1-d21d-50e6-aa62-4dd95fa79f3d', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 1, 1, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('d54357da-a0a6-5bf0-a4e6-eb367d4ce2c7', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 2, 2, '“የሰው ልጅ ሆይ! ትንቢት በሚናገሩ በእስራኤል ነቢያት ላይ ትንቢት ተናገር፤ ከገዛ ልባቸውም ትንቢት የሚናገሩትን፦ የእግዚአብሔርን ቃል ስሙ በላቸው፤'),
  ('b9e70e7a-201b-52cc-afa5-1199c8dc84c6', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 3, 3, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ፈጽሞ ሳያዩ ከገዛ ልባቸው አንቅተው ትንቢት ለሚናገሩ ወዮላቸው!'),
  ('3f073ae5-c0b4-52d8-a629-81d3a7355932', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 4, 4, 'እስራኤል ሆይ! ነቢያትህ በምድረ በዳ እንደሚኖሩ ቀበሮዎች ናቸው።'),
  ('b68ef73d-7617-5071-a31c-d0f84173a806', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 5, 5, 'ወደ ተሰበረው ቅጥር አልወጣችሁም፤ በእግዚአብሔርም ቀን በሰልፍ ትቆሙ ዘንድ ለእስራኤል ቤት ቅጥርን አልሠራችሁም።'),
  ('5b580e80-63c0-5c52-abe3-a993ce84cd52', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 6, 6, 'እግዚአብሔር ሳይልካቸው፦ እግዚአብሔር ይላል የሚሉ ሰዎች ሐሰትን ያያሉ፤ ከንቱን ያምዋርታሉ፤ ቃሉንም ማጽናት ይጀምራሉ።'),
  ('b990bcc1-c358-5cad-a891-21cc6b5a7bb0', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 7, 7, 'እኔም ሳልናገር፦ እግዚአብሔር እንዲህ ብሎአል ስትሉ፥ ከንቱ ምዋርትን የተናገራችሁ፥ የሐሰት ራእይንም ያያችሁ አይደላችሁምን?”'),
  ('f9171fc6-2c1a-55e1-a741-79c50266a8d1', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 8, 8, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፥ “ከንቱ ነገርን ስለ ተናገራችሁ፥ ሐሰተኛ ራእይንም ስለ አያችሁ፥ ስለዚህ እነሆ እኔ በእናንተ ላይ ነኝ፥ ይላል እግዚአብሔር።'),
  ('902bee5d-4943-5637-aaa1-ffaf5b7cbd74', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 9, 9, 'እጄም ሐሰተኛ ራእይን በሚያዩ፥ ሕዝቤንም ለማታለል በከንቱ በሚያምዋርቱ ነቢያት ላይ ትሆናለች። እነርሱም በሕዝቤ ማኅበር ውስጥ አይኖሩም፤ በእስራኤልም ቤት መጽሐፍ አይጻፉም፥ ወደ እስራኤልም ምድር አይገቡም፤ እኔም ጌታ እግዚአብሔር እንደ ሆንሁ ያውቃሉ።'),
  ('c3ef0834-e741-570a-ad48-87e562e0b03f', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 10, 10, 'ሰላም ሳይኖር፦ ሰላም እያሉ ሕዝቤን አታልለዋልና፤ አንዱም ሰው ቅጥር ሲሠራ እነርሱ ያለገለባ ይመርጉታል፤ ይወድቃልም፤'),
  ('226072c0-ac30-5996-a44e-00d507c6acc0', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 11, 11, 'ያለ ገለባም ለሚመርጉት ሰዎች፦ ይወድቃል በላቸው። የሚያሰጥም ዝናብ ይዘንባል፤ ታላቅም የበረዶ ድንጋይ በራሳቸው ላይ አወርዳለሁ፤ እነርሱም ይወድቃሉ፤ ኀይለኛ ዐውሎ ነፋስም ይሰነጣጥቀዋል።'),
  ('f1b608c1-b48c-5db9-a395-0377ff4e3317', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 12, 12, 'እነሆ ግንቡ በወደቀ ጊዜ፦ የመረጋችሁት ምርግ ወዴት አለ? አይሉአችሁምን?'),
  ('b3def5e0-7261-58c2-ae1a-8d2c701bb82a', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 13, 13, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ በመዓቴ በዐውሎ ነፋስ እሰነጣጥቀዋለሁ፤ ያጠፋውም ዘንድ በቍጣዬ የሚያሰጥም ዝናብ፥ በመዓቴም ታላቅ የበረዶ ድንጋይ አወርዳለሁ።'),
  ('6c2e5bde-157a-5d59-a80d-f695d6a89186', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 14, 14, 'ያለ ገለባ የመረጋችሁትንም ቅጥር አፈርሳለሁ፤ ይወድቃል፤ ወደ ምድርም እጥለዋለሁ፤ መሠረቱም ይታያል፤ እርሱም ይናዳል፤ በመካከሉም ትጠፋላችሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('7115ea00-a9d4-51f6-a521-ae3334f98ed5', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 15, 15, 'መዓቴንም በግንቡ ላይና ያለገለባ በመረጉት ላይ እፈጽማለሁ፤ ግንቡም ይወድቃል፤ እኔም፦ ግንቡና መራጊዎቹ የሉም እላችኋለሁ።'),
  ('268b8406-3e8e-500e-a10a-be08ea5e0cc4', '3874c849-1490-50a3-a187-63780c3db200', '86f423b2-8b99-5c9d-aa89-6740f81ae8f9', 16, 16, 'እነርሱም ስለ ኢየሩሳሌም ትንቢት የሚናገሩ፥ የሰላምንም ራእይ የሚያዩላት የእስራኤል ነቢያት ናቸው፤ ሰላምም የለም፥” ይላል ጌታ እግዚአብሔር።'),
  ('981f3489-1aac-5a68-ae94-8b950da45440', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 1, 17, '“አንተም፥ የሰው ልጅ ሆይ! ከልባቸው አንቅተው ትንቢት በሚናገሩ በሕዝብህ ሴቶች ልጆች ላይ ፊትህን አድርግ፤ ትንቢትም ተናገርባቸው፤'),
  ('87b45a11-1038-57ec-a7bf-bc9429a2f4ee', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 2, 18, 'እንዲህም በላቸው፦ ጌታ እግዚአብሔር እንዲህ ይላል፦ ነፍስን ለማጥመድ ለእጅ ድጋፍ ሁሉ መከዳ ለሚሰፉ፥ ለሰውም ሁሉ ራስ እንደ እየቁመቱ ሽፋን ለሚሠሩ ሴቶች ወዮላቸው! የሕዝቤን ነፍስ ታጠምዳላችሁ፤ በውኑ እናንተ ነፍሳችሁን ታድናላችሁ?'),
  ('0596908f-e3f7-5883-acbe-3891f7815782', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 3, 19, 'ከንቱ ነገርን ለሚሰሙት ሕዝቤ እየዋሻችሁ ሞት የማይገባቸውን ነፍሳት ትገድሉ ዘንድ፥ በሕይወትም መኖር የማይገባቸውን በሕይወት ታኖሩ ዘንድ ስለ ጭብጥ ገብስና ስለ ቍራሽ እንጀራ ሕዝቤን አርክሳችኋል።'),
  ('9efff191-12fc-5676-aa4c-992d8990807a', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 4, 20, '“ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ እኔ ነፍሳትን እንደ ወፍ በምታጠምዱባት በመከዳችሁ ላይ ነኝ፤ ከክንዳችሁም ወስጄ እቀድዳታለሁ፤ እንደ ወፍም የምታጠምዱአቸውን ነፍሳት እለቅቃለሁ።'),
  ('c20b054b-fd7c-5303-a941-4b99716e0f50', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 5, 21, 'ሽፋኖቻችሁን ደግሞ እቀድዳለሁ፤ ሕዝቤንም ከእጃችሁ አድናለሁ፤ ከዚያም ወዲያ በእጃችሁ ለመታደን አይሆኑም፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('c0475898-eef4-50c9-afc7-6c831ac43893', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 6, 22, 'እኔም ያልመለስሁትን የጻድቁን ልብ ወደ ዐመፃ መልሳችኋልና፥ በሕይወትም ይኖር ዘንድ ከክፉ መንገድ እንዳይመለስ የኀጢአተኛውን እጅ አበርትታችኋልና፤'),
  ('a69ddeb2-952b-59b8-af39-9264cad33f7f', '3874c849-1490-50a3-a187-63780c3db200', 'a85019c6-c510-5667-a7ba-39c246c9d86e', 7, 23, 'ስለዚህ፥ ሐሰትን አታዩም፤ እንግዲህም ከንቱ ምዋርትን አታምዋርቱም፤ ሕዝቤንም ከእጃችሁ አድናለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።”'),
  ('ff68cce0-b764-5b09-a353-2682be324221', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 1, 1, 'ከእስራኤልም ሽማግሌዎች አያሌ ሰዎች ወደ እኔ መጥተው በፊቴ ተቀመጡ።'),
  ('5d17c603-212e-57e9-a015-7df287e25e8d', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 2, 2, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('1a508d79-4c30-5386-a605-9a48ea8d8cc8', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 3, 3, '“የሰው ልጅ ሆይ! እነዚህ ሰዎች በልባቸው ጣዖቶቻቸውን አኑረዋል፤ የበደላቸውንም መቅሠፍት በፊታቸው አቁመዋል፤ እኔስ ለእነርሱ መልስ ልመልስላቸውን?'),
  ('4abbf759-fe74-5fb8-a625-9b7ef90e554f', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 4, 4, 'ስለዚህ ንገራቸው፤ እንዲህም በላቸው፥ ጌታ እግዚአብሔር እንዲህ ይላል፦ ከእስራኤል ቤት ጣዖቶቹን በልቡ የሚያኖር፥ የበደሉንም መቅሠፍት በፊቱ የሚያቆም ሰው ሁሉ ወደ ነቢዩ ቢመጣ እኔ እግዚአብሔር እንደ ጣዖታቱ ብዛት እመልስለታለሁ።'),
  ('0fcd7e2c-0e52-5461-a661-64b5f7979891', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 5, 5, 'ይህም የእስራኤልን ወገኖች በዐሳባቸው ከእኔ እንደ ተለዩበት እንደ ልባቸውና እንደ ርኵሰታቸው ያስታቸው ዘንድ ነው።”'),
  ('1f38a457-cdd1-5d8a-af2d-15ad71a2715d', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 6, 6, 'ስለዚህ ለእስራኤል ቤት እንዲህ በል፥ “ጌታ እግዚአብሔር እንዲህ ይላል፦ ንስሓ ግቡ፤ ከበደላችሁም ተመለሱ፤ ፊታችሁንም ከኀጢአታችሁ ሁሉ መልሱ።'),
  ('639b6a34-9800-500c-a48a-5d68f1c85a41', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 7, 7, 'ከእስራኤልም ቤት፥ በእስራኤልም ዘንድ ከሚቀመጡ መጻተኞች የሚሆን፥ ከእኔ ተለይቶ ጣዖቶቹን በልቡ የሚያኖር፥ የበደሉንም መቅሠፍት በፊቱ የሚያቆም ሰው ሁሉ ስለ እኔ ይጠይቅ ዘንድ ወደ ነቢዩ በመጣ ጊዜ፥ እኔ እግዚአብሔር በራሴ እመልስለታለሁ።'),
  ('499a270d-c223-5d01-a788-a2e870209267', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 8, 8, 'ፊቴንም በዚያ ሰው ላይ አደርጋለሁ፤ እንዲጠፋም አደርገዋለሁ፤ ከሕዝቤም መካከል አስወግደዋለሁ፤ እኔም እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('50d2b03d-2b25-5617-ae73-0a0660364d59', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 9, 9, 'ነቢዩም ቢታለል፥ ቃልንም ቢናገር፥ ያን ነቢይ ያታለልሁ እኔ እግዚአብሔር ነኝ፥ እጄንም በእርሱ ላይ እዘረጋለሁ፤ ከሕዝቤም ከእስራኤል መካከል አጠፋዋለሁ።'),
  ('6315fbfa-6dd3-5057-aced-3d9df48ad1c1', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 10, 10, 'ኀጢአታቸውን ይሸከማሉ፤ እንደሚጠይቀውም ሰው ኀጢአት እንዲሁ የነቢዩ ኀጢአት ይሆናል።'),
  ('a3250e6d-3594-5f2b-aa54-bae1b636a7d3', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 11, 11, 'ይኸውም የእስራኤል ቤት ደግሞ ከእኔ ርቀው እንዳይስቱ፥ በኀጢአታቸውም ሁሉ እንዳይረክሱ ነው፤ እነርሱ ሕዝብ ይሆኑኛል፤ እኔም አምላክ እሆናቸዋለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('f35fdc85-feb2-5146-a07f-55033a3ab068', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 12, 12, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('51c35940-bc0f-53a6-a1af-4f5e8cc78653', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 13, 13, '“የሰው ልጅ ሆይ! ምድር ብትበድለኝ፥ ብትስት፥ ኀጢአትም ብትሠራ እጄን በእርስዋ አነሣለሁ፤ የእህሉንም ኀይል አጠፋለሁ፤ በእርስዋም ረሀብን እልካለሁ፤ ከብቱንና ሰዉንም ከእርስዋ አጠፋለሁ።'),
  ('c8d53bdd-a7d7-5c77-a4b6-579ed4959d1e', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 14, 14, 'እነዚህ ሦስቱ ሰዎች ኖኅና ዳንኤል ኢዮብም በመካከልዋ ቢኖሩ በጽድቃቸው የገዛ ነፍሳቸውን ያድናሉ፥” ይላል ጌታ እግዚአብሔር።'),
  ('76f9a88f-41fa-53d9-a7b9-dc90d82d2e5c', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 15, 15, 'በዚያች ሀገር ላይ ክፉ አውሬን ባመጣ፥ ፈጽሜም ባጠፋት በዚያም አውሬ ፊት የሚያልፍ ባይገኝ፥'),
  ('209eb14c-fb44-5973-afb0-d8e9576f34e5', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 16, 16, 'እነዚህ ሦስት ሰዎች በመካከልዋ ቢኖሩ፥ እኔ ሕያው ነኝ! እነርሱ ብቻቸውን ይድናሉ እንጂ ወንዶችንና ሴቶች ልጆቻቸውን አያድኑም፤ ምድሪቱም ባድማ ትሆናለች፥ ይላል ጌታ እግዚአብሔር።'),
  ('c3d00890-03a1-5c2e-a109-4072ebbf186a', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 17, 17, 'ወይም በዚያች ምድር ላይ ሰይፍ አምጥቼ፦ ሰይፍ ሆይ! በምድሪቱ ላይ እለፊ ብል፥ ሰውንና እንስሳውንም ከእርስዋ ባጠፋ፥'),
  ('b9ab5790-e20b-56ba-a74a-83fcb9323567', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 18, 18, 'እነዚህ ሦስት ሰዎች በመካከልዋ ቢኖሩ፥ እኔ ሕያው ነኝ! እነርሱ ብቻቸውን ይድናሉ እንጂ ወንዶችንና ሴቶች ልጆቻቸውን አያድኑም፥” ይላል ጌታ እግዚአብሔር።'),
  ('0609b172-72bc-5929-acdf-5aad2242bfd6', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 19, 19, 'ወይም በዚያች ምድር ላይ ቸነፈርን ብሰድድ፥ ሰውንና እንስሳውንም ከእርስዋ አጠፋ ዘንድ መዓቴን በደም ባፈስስባት፥'),
  ('6d951e50-9c50-58b3-adbf-b7409d3b9e19', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 20, 20, 'ኖኅና ዳንኤል ኢዮብም በመካከልዋ ቢኖሩ፤ እኔ ሕያው ነኝ! በጽድቃቸው ነፍሳቸውን ብቻ ያድናሉ እንጂ ወንዶችንና ሴቶች ልጆቻቸውን አያድኑም፥” ይላል ጌታ እግዚአብሔር።'),
  ('3912ac01-a194-51b8-ac16-babd24d1a318', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 21, 21, 'ጌታ እግዚአብሔርም እንዲህ ይላል፥ “ይልቁንስ ሰውንና እንስሳን ከእርስዋ አጠፋ ዘንድ በኢየሩሳሌም ላይ አራቱን ክፉ መቅሠፍቶችን፥ ሰይፍንና ራብን፥ ክፉዎችንም አውሬዎች፥ ቸነፈርንም ስሰድድባት፥'),
  ('b21eced7-5166-5cea-a4e9-d49ad222e528', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 22, 22, 'ነገር ግን እነሆ የሚያመልጡና ወንዶችና ሴቶች ልጆችን ከእርስዋ የሚያወጡ ይቀሩላታል፤ እነሆ ወደ እናንተ ይወጣሉ፤ እናንተም መንገዳቸውንና ሥራቸውን ታያላችሁ፤ በኢየሩሳሌምም ላይ ስላመጣሁት ክፉ ነገር ሁሉ፥ ስላመጣሁባትም ነገር ሁሉ ትጽናናላችሁ፤'),
  ('2745c5d7-2520-5470-a238-1484a46dde0c', '583f4733-ce8b-501e-a1da-61ab59d85a7b', 'e67f0db9-2d59-567d-a6e3-7022a6511b85', 23, 23, 'መንገዳቸውንና ሥራቸውን በአያችሁ ጊዜ ያጽናኗችኋል፤ ያደረግሁባትንም ሁሉ በከንቱ እንዳላደረግሁባት ታውቃላችሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('19a27fea-eb6a-563d-aa3f-a5a1e25af240', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 1, 1, 'የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('7d386f02-54f1-5402-a216-d09b2176284e', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 2, 2, '“የሰው ልጅ ሆይ! የወይን ግንድ ከዱር ዛፎች ሁሉና ከዱር ዛፎች ቅርንጫፎች ሁሉ ይልቅ ብልጫው ምንድን ነው?'),
  ('3b91d8d5-0e10-5705-a9bd-7100484d6206', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 3, 3, 'በውኑ ሥራ የሚሠራበትን እንጨት ከእርሱ ይወስዳሉን? ወይስ ሰዎች ዕቃ የሚንጠለጠልበትን ኩላብ ከእርሱ ይወስዳሉን?'),
  ('093374c1-fbb9-5b25-a074-0b8b01209eaf', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 4, 4, 'እነሆ ለመቃጠል በእሳት ላይ ተጥሎአል፤ እሳቱም ሁለቱን ጫፎቹን በልቶአል፤ መካከሉም ተቃጥሎአል፤ በውኑ ለሥራ ይጠቅማልን?'),
  ('57a75982-1ecd-51fc-a254-9ae91f241ab5', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 5, 5, 'ከውፍረቱም የተነሣ ለሥራ አይሆንም፤ ለምትበላና ለምታጠፋ እሳት ይሆናል እንጂ ከዚያ በኋላ በውኑ ለሥራ ይሆናልን?'),
  ('8086da95-7268-54c7-a5e2-9139345c2477', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 6, 6, 'ስለዚህ ጌታ እግዚአብሔር እንዲህ ይላል፦ በዱር ዛፎች መካከል ያለውን የወይን ግንድ እሳት ይበላው ዘንድ እንደ ሰጠሁት፥ እንዲሁ በኢየሩሳሌም የሚኖሩትን አሳልፌ እሰጣለሁ።'),
  ('a5e65019-69a2-549e-a4f0-1a4edaf1a9c3', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 7, 7, 'ፊቴንም በእነርሱ ላይ አጸናለሁ፤ ከእሳትም አይወጡም፤ እሳትም ይበላቸዋል፤ ፊቴንም በእነርሱ ላይ በአጸናሁ ጊዜ እኔ እግዚአብሔር እንደ ሆንሁ ታውቃላችሁ።'),
  ('607bcceb-718b-54b9-ad6e-ab43332b04a8', 'b859af05-95b8-5c7b-ae5d-68952d5b8128', '7343e3a5-0872-5edf-ac82-1cdda7eb0f67', 8, 8, 'ዐመፅን አድርገዋልና ምድሪቱን ባድማ አደርጋለሁ፥” ይላል ጌታ እግዚአብሔር።'),
  ('629fded1-1904-508c-ac65-8c39fa92caea', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 1, 1, 'የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('c79ee4c4-1fba-57f5-a537-65350ec2217e', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 2, 2, '“የሰው ልጅ ሆይ! ለኢየሩሳሌም ኀጢአትዋን አስታውቃት፤ እንዲህም በላት፦'),
  ('49c676d5-3e79-5e63-a2a5-1edb77631754', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 3, 3, 'ጌታ እግዚአብሔር ለኢየሩሳሌም እንዲህ ይላል፦ ዘርሽና ትውልድሽ ከከነዓን ምድር ነው፤ አባትሽ አሞራዊ ነበረ፤ እናትሽም ኬጢያዊት ነበረች።'),
  ('d7c4b79d-b7bd-5633-ab14-58c7c18fab8a', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 4, 4, 'በተወለድሽ ጊዜ በዚያው ቀን እትብትሽ አልታተበም፤ ንጹሕም ትሆኚ ዘንድ በውኃ አልታጠብሽም፤ በጨውም አልተወለወልሽም፤ በጨርቅም አልተጠቀለልሽም፤ በጭንም አልታቀፍሽም።'),
  ('fe83a40c-69ea-5295-a1c6-416e2eeb0418', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 5, 5, 'በተወለድሽበት ቀን ከሰውነትሽ ጕስቍልና የተነሣ በሜዳ ላይ ተጣልሽ እንጂ፥ ከዚህ አንዳች ይደረግልሽ ዘንድ ዐይኔ አልራራልሽም፤ ማንም አላዘነልሽም።'),
  ('b6288871-27bd-5532-a99b-d2906c06ae04', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 6, 6, '“በአንቺም ዘንድ ባለፍሁ ጊዜ፤ በደምሽም ተለውሰሽ በአየሁሽ ጊዜ፦ ከደምሽ ዳኝ አልሁሽ፤'),
  ('cd6564d4-2b4c-5ac1-a280-43bb8e45158c', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 7, 7, 'በእርሻ ላይ እንደ አለ ቡቃያ አበዛሁሽ፤ አንቺም አደግሽ፤ ታላቅም ሆንሽ፤ በእጅጉም አጌጥሽ፤ ከከተማ ወደ ከተማ ገባሽ፤ ጡቶችሽም አጐጠጐጡ፤ ጠጕርሽም አደገ፤ ነገር ግን ዕርቃንሽን ሆንሽ፤ ተራቍተሽም ነበርሽ።'),
  ('12f80a14-4a39-59a4-ad5f-cf517d8a3d71', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 8, 8, 'በአንቺ ዘንድ በአለፍሁና በአየሁሽ ጊዜ፥ እነሆ ጊዜሽ እንደ ደረሰ፥ በአንቺም የሚያድሩ ሰዎች ጊዜ እንደ ደረሰ አየሁ። እጆችን በላይሽ ዘረጋሁ፤ ኀፍረተ ሥጋሽንም ከደንሁ፤ ማልሁልሽም፤ ከአንቺም ጋራ ቃል ኪዳን ገባሁ፥” ይላል ጌታ እግዚአብሔር፤ አንቺም ለእኔ ሆንሽ።'),
  ('56ee6afe-6f46-57df-a9a1-67dd85fd7d4b', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 9, 9, 'በውኃም አጠብሁሽ፤ ከደምሽም አጠራሁሽ፤ በዘይትም ቀባሁሽ።'),
  ('43e58d34-caf1-5c69-ac84-524a1feff4eb', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 10, 10, 'ወርቀ ዘቦም አለበስሁሽ፤ ጥቁር ጫማም አደረግሁልሽ፤ በጥሩ በፍታ አስታጠቅሁሽ፤ በሐርም ከደንሁሽ።'),
  ('fe2a4aec-61ce-52fb-abfc-2c52a83969e9', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 11, 11, 'በጌጥም አስጌጥሁሽ፤ በእጅሽም ላይ አንባር፥ በአንገትሽም ላይ ድሪ አደረግሁልሽ።'),
  ('8411de1e-b4ee-5307-aa11-2ccc0ecd51d6', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 12, 12, 'በአፍንጫሽም ቀለበት፥ በጆሮሽም ጉትቻ፥ በራስሽም ላይ የክብር አክሊል አደረግሁ።'),
  ('d7508713-c875-5733-aa7f-d4477518dee5', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 13, 13, 'በወርቅና በብር አጌጥሽ፤ ልብስሽም ጥሩ በፍታና ሐር፥ ወርቀ ዘቦም ነበረ፤ አንቺም መልካምን ዱቄትና ማርን፥ ዘይትንም በላሽ፤ ወፈርሽ፤ እጅግም ውብ ሆንሽ፤ ለመንግሥትም የተዘጋጀሽ አደረግሁሽ።'),
  ('1ae2d364-86bc-51cb-a689-8c10c6d3a867', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 14, 14, 'ባንቺ ላይ ከአኖርኋት ከክብሬ የተነሣ ውበትሽ ፍጹም ነበረና ስምሽ በአሕዛብ መካከል ተሰማ፥ ይላል ጌታ እግዚአብሔር።'),
  ('bc7f3bf1-4edf-5d57-acc2-1e14b342df66', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 15, 15, '“ነገር ግን በውበትሽ ታምነሻል፤ በስምሽም አመንዝረሻል፤ ምንዝርናሽንም ከመንገድ አላፊ ሁሉ ጋር አበዛሽ።'),
  ('64340b95-8e51-5796-af74-1d2c1378e4c8', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 16, 16, 'ከልብስሽም ወስደሽ በመርፌ የተጠለፉ ጣዖታትን ሠራሽ፤ አመነዘርሽባቸውም፤ ስለዚህ ፈጽመሽ አልገባሽም፤ ከእንግዲህም ወዲህ እንዲህ ያለ ነገር አይሆንም።'),
  ('14434305-c669-5b2f-ac51-ab7da330b92f', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 17, 17, 'ከሰጠሁሽም ከወርቄና ከብሬ የተሠራውን የክብርሽን ዕቃ ወስደሽ የወንድ ምስሎችን ለራስሽ አድርገሻል፤ አመንዝረሽባቸውማል።'),
  ('6033e2a7-68f2-5120-afd7-faa1ece58434', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 18, 18, 'ወርቀ ዘቦውን ልብስሽንም ወስደሽ ደረብሽላቸው፤ ዘይቴንና ዕጣኔንም በፊታቸው አኖርሽ።'),
  ('a186fefe-6915-583d-a1ce-4f48dd0a1835', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 19, 19, 'የሰጠሁሽንም እንጀራዬን፥ ያበላሁሽንም ዱቄትና ዘይቱን፥ ማሩንም ጣፋጭ ሽታ አድርገሽ በፊታቸው አኖርሽ፤ እንዲህም ሆኖአል፥ ይላል ጌታ እግዚአብሔር።'),
  ('a8163776-fecc-55c7-a4fb-5912f70d479b', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 20, 20, 'ለእኔም የወለድሻቸውን ወንዶችና ሴቶች ልጆችሽን ወስደሽ መብል ይሆኑ ዘንድ ሠዋሽላቸው፤ ገደልሻቸውም።'),
  ('7c608144-a1d4-520b-a855-02d35683a3b9', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 21, 21, 'ልጆችን አረድሽ፤ ለሚቃጠል መሥዋዕትም አሳልፈሽ ሰጠሽ፤ በውኑ ግልሙትናሽ ጥቂት ነውን?'),
  ('a772cb98-ac37-5dc7-af6f-7b9c7aee1366', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 22, 22, 'ከኀጢአትሽና ከዝሙትሽ ሁሉ ይህ ይከፋል፤ አንቺ ዕራቁትሽን ሳለሽ፥ ኀፍረትም ሞልቶብሽ ሳለሽ፥ በደምሽም ተለውሰሽ ሳለሽ፥ የሕፃንነትሽን ወራት አላሰብሽም።'),
  ('57112b3a-da03-522c-acb2-5d39af58590b', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 23, 23, '“ከዚህም ከክፋትሽ ሁሉ በኋላ ወዮልሽ! ወዮልሽ! ይላል ጌታ እግዚአብሔር።'),
  ('dd9351f5-d000-526d-a081-9b6a908ede5e', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 24, 24, 'የምትሰስኝበትን ቤት ለራስሽ ሠራሽ፤ በአደባባዩ ሁሉ ከፍ ያለ ቦታን አደረግሽ።'),
  ('93fa914c-6f9d-5e63-ae33-dc47a1b07e4a', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 25, 25, 'በየመንገዱ ራስ ከፍ ያለውን ቦታሽን ሠራሽ፤ ውበትሽንም አረከስሽ፤ ለመንገድ አላፊም ሁሉ እግርሽን ገለጥሽ፤ ዝሙትሽንም አበዛሽ።'),
  ('90dec13f-5e65-589b-ac87-1b1d3f918736', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 26, 26, 'አካላቸውም ከወፈረ ከጐረቤቶችሽ ከግብፃውያን ልጆች ጋር አመነዘርሽ፤ እኔንም ታስቆጭ ዘንድ ዝሙትሽን አበዛሽ።'),
  ('0b61bb68-c416-5794-a632-9e314c70e2c6', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 27, 27, 'ስለዚህ እነሆ እጄን በአንቺ ላይ ዘርግቻለሁ፤ ድርሻሽንም አጕድያለሁ፤ ለሚጠሉሽም፥ ከመንገድሽ ለመለሱሽና ለአሳቱሽ ለፍልስጥኤም ሴቶች ልጆች ፈቃድ አሳልፌ ሰጥቼሻለሁ።'),
  ('092c41ce-35b0-5a77-a266-8396fddd7c5c', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 28, 28, 'ከአሦራውያን ልጆች ጋር ፈጽመሽ አመነዘርሽ፤ ከዚህም ጋር ገና አልጠገብሽም፤ ዝሙትሽም አልበቃሽም።'),
  ('b774c4d9-abfe-5ea2-afab-fa78ec25e587', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 29, 29, 'እስከ ከነዓን ምድር እስከ ከላውዴዎንም ድረስ ዝሙትሽን አበዛሽ። ከዚህም ጋር ገና አልጠገብሽም።'),
  ('6464e85a-760d-58b4-ac43-8e4c37fa28ad', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 30, 30, '“ይህን ሁሉ የሴሰኛ ሴት ሥራን ሠርተሻልና፥ ከሴቶች ልጆችሽም ጋር ሦስት ጊዜ አመንዝረሻልና ሴቶች ልጆችሽን ምን አደርጋቸዋለሁ? ይላል ጌታ እግዚአብሔር።'),
  ('88a5beca-df3f-53c7-addb-414900157379', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 31, 31, 'በየመንገዱ ራስ የምንዝርናሽን ስፍራ ሠርተሻል፤ በየአደባባዩም ከፍ ያለውን ቦታሽን አድርገሻል። ዋጋዋን እንደምትሰበስብ እንደ ጋለሞታም አልሆንሽም።'),
  ('a7abc821-e470-5b25-a479-566994852def', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 32, 32, 'ከባልዋ ገንዘብ ተቀብላ የምታመነዝር ሴትን ትመስያለሽ።'),
  ('5e2d26f3-4c76-5682-ad99-619aceb43f5f', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 33, 33, 'ለአመንዝራዎች ሁሉ ዋጋ ይሰጡአቸዋል፤ አንቺ ግን ለወዳጆችሽ ሁሉ ዋጋ ትሰጫለሽ፤ ከአንቺም ጋር ለማመንዘር በዙሪያሽ ይገቡብሽ ዘንድ መማለጃን ትሰጫቸዋለሽ።'),
  ('45e16764-de99-5496-ac07-3a44c02b157a', '8144132e-6311-5911-a58b-9a7566d6fd07', '44d59595-13b2-5c8f-a9d5-8f5ce08f1a00', 34, 34, 'ዝሙትሽ ከሌሎች ሴቶች ዝሙት ልዩ ነው፤ ማንም ለዝሙት የሚከተልሽ የለም፤ ዋጋ ሳይሰጥሽ አንቺ ዋጋ በመስጠትሽ በዚህ ነገር ልዩ ሆነሻል።'),
  ('446249b8-c059-5672-a8ac-4ff4a171b091', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 1, 35, '“ስለዚህ ዘማ ሆይ! የእግዚአብሔርን ቃል ስሚ።'),
  ('3109b3e3-8bc6-5d77-a3c2-fd0a71d23c63', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 2, 36, 'ጌታ እግዚአብሔር እንዲህ ይላል፦ ወርቄን በትነሻልና ከኀጢአት ምኞት በሠራሽው ዝሙት ኀፍረተ ሥጋሽን ገልጠሻልና በሰጠሻቸውም በልጆችሽ ደም፥'),
  ('5565728c-6012-585d-a3fa-e5d8f963047d', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 3, 37, 'ስለዚህ እነሆ እኔ ከአንቺ ጋር አንድ የሆኑ ውሽሞችሽን በአንቺ ላይ እሰበስባቸዋለሁ፤ የምትወጃቸውንም ከምትጠያቸው ጋር በአንቺ ላይ እሰበስባቸዋለሁ፤ ይከቡሻል፤ በእነርሱም ዘንድ ጕስቍልናሽን እገልጥብሻለሁ፤ ሁሉም ኀፍረትሽን ያዩብሻል።'),
  ('08518c11-92e6-5937-aab0-cae2af7cc48c', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 4, 38, 'በአመንዝሮችና በደም አፍሳሾች በቀል እበቀልሻለሁ፤ በመዓትና በቅንአት ደምም አስቀምጥሻለሁ።'),
  ('52e481f0-93d1-544e-ae08-d114036ae916', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 5, 39, 'በእጃቸውም አሳልፌ እሰጥሻለሁ፤ የምንዝርናሽንም ስፍራ ያፈርሳሉ፤ ከፍ ያለውንም ቦታሽን ይገለብጣሉ፤ ልብስሽንም ይገፉሻል፤ የክብርሽንም ጌጥ ይወስዳሉ፤ ዕራቁትሽንም ይተዉሻል፤ ቷረጃለሽም።'),
  ('2d1dbebb-8183-5f68-afb2-7cc2c6942f3d', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 6, 40, 'ብዙ ሕዝብን ይሰበሰቡብሻል፤ በድንጋይም ይወግሩሻል፤ በሰይፋቸውም ይወጉሻል።'),
  ('7aaac0f9-0ffe-50c7-aba1-4ef3ac9f3109', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 7, 41, 'ቤቶችሽንም በእሳት ያቃጥላሉ፤ በብዙም ሴቶች ፊት ይበቀሉሻል፤ ግልሙትናሽንም አስተውሻለሁ፤ ከእንግዲህም ወዲህ ዋጋ አትሰጪም።'),
  ('4fd62eb9-0d66-5281-a2de-cc04d5938f3f', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 8, 42, 'መዓቴንም በአንቺ ላይ እጨርሳለሁ፤ ቅንዓቴም ከአንቺ ይርቃል፤ እኔም ዝም እላለሁ፤ ደግሞም አልቈጣም።'),
  ('ca59fb9e-0d4f-59fa-ac5f-4295250a9419', '8144132e-6311-5911-a58b-9a7566d6fd07', 'd99f5d55-17f9-5d17-a6e9-2cdd925a72d1', 9, 43, 'የሕፃንነትሽን ወራት አላሰብሽምና፥ በዚህም ነገር ሁሉ አስቈጥተሽኛልና፤ ስለዚህ እነሆ እኔ ደግሞ መንገድሽን በራስሽ ላይ አመጣለሁ፥” ይላል ጌታ እግዚአብሔር፤ እንደዚህም በበደልሽ ሁሉ ላይ ኀጢአትን ሠራሽ።'),
  ('e68b1bf2-f2af-5570-ae99-d8f36d2c4291', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 1, 44, '“እነሆ በምሳሌ የሚናገር ሁሉ፥ እንደ እናቲቱ እንዲሁ ልጅቱ ናት፤ እያለ ምሳሌ ይመስልብሻል።'),
  ('89a3107b-856b-5f23-af73-17e95a898829', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 2, 45, 'አንቺ ባልዋንና ልጆችዋን የጠላች የእናትሽ ልጅ ነሽ፤ አንቺም ባሎቻቸውንና ልጆቻቸውን የጠሉ የእኅቶችሽ እኅት ነሽ፤ እናታችሁ ኬጢያዊት ነበረች፤ አባታችሁም አሞራዊ ነበረ።'),
  ('a61b51b8-350d-5d3e-a226-036d0075ab53', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 3, 46, 'ታላቂቱም እኅትሽ ከሴቶች ልጆችዋ ጋር በስተ ግራሽ የምትቀመጥ ሰማርያ ናት፤ ታናሽቱም እኅትሽ ከሴቶች ልጆችዋ ጋር በሰተ ቀኝሽ የምትቀመጥ ሰዶም ናት።'),
  ('a4955c36-22c3-565c-ace1-6854fcb81471', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 4, 47, 'አንቺ ግን በመንገዳቸው አልሄድሽም፤ እንደ ኀጢአታቸውም አላደረግሽም፤ ያው ለአንቺ ጥቂት ነበረና በመንገድሽ ሁሉ ከእነርሱ የሚከፋ ኀጢአት አደረግሽ።'),
  ('0bdbf99f-d038-5782-a2d4-c79097ad7ee2', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 5, 48, 'እኔ ሕያው ነኝ! አንቺና ሴቶች ልጆችሽ እንዳደረጋችሁት እንዲሁ ሰዶምና ሴቶች ልጆችዋ አላደረጉም፥ ይላል ጌታ እግዚአብሔር።'),
  ('677af8e5-79e4-53b9-adc6-0fd8ba6b0176', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 6, 49, 'እነሆ የእኅትሽ የሰዶም ኀጢአት ይህ ነበረ፤ ትዕቢት፥ እንጀራን መጥገብ፥ መዝለልና ሥራን መፍታት፥ ይህ ሁሉ በእርስዋና በልጆችዋ ነበር፤ የችግረኛውንና የድሀውንም እጅ አላጸናችም።'),
  ('4404f4e7-0b9f-5649-ae0e-fc45721a2011', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 7, 50, 'ኰርተው ነበር፤ በፊቴም ርኵስ ነገር አደረጉ፤ ስለዚህ እንደ አየሁ አስወገድኋቸው።'),
  ('4aecf92b-1d37-5ea1-aa81-7db90da4d940', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 8, 51, 'ሰማርያም የኀጢአትሽን እኩሌታ አልሠራችም፤ አንቺ ግን ከእኅቶችሽ ይልቅ ኀጢአትን አበዛሽ፤ በሠራሽውም ኀጢአት ሁሉ አጸደቅሻቸው።'),
  ('35e9d847-9a83-5f6d-ab52-bec6aa7275be', '8144132e-6311-5911-a58b-9a7566d6fd07', '240c517e-787b-52a8-a6b4-73bfcf6e5920', 9, 52, 'አሁንም ከእነርሱ ይልቅ አብዝተሽ በሠራሽው ኀጢአትሽ እኅቶችሽን ስላረከስሻቸው ቅጣትሽን ተሸከሚ። ከአንቺም ይልቅ አጸደቅሻቸው፤ አንችም እፈሪ፤ እፍረትሽንም ተሸከሚ፤ እኅቶችሽን አጽድቀሻቸዋልና።')
